package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Component;
import java.awt.Container;
import java.awt.EventQueue;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;
import javax.swing.BoxLayout;
import javax.swing.JPanel;

/**
 * Dev-only: renders Flips-tab board rows headlessly to a PNG: a confirmed
 * row, risk-tier rows (Stale Prints / Big), and a plain row: so the row
 * design can be iterated without a live feed. Args: [outputPath]. Never
 * shipped (test source set).
 */
public final class FlipsPreview
{
	private FlipsPreview()
	{
	}

	public static void main(String[] args) throws Exception
	{
		System.setProperty("java.awt.headless", "true");
		final String out = args.length > 0 ? args[0] : "/tmp/flips.png";

		final PriceCheckPanel.Listener stub = new PriceCheckPanel.Listener()
		{
			public void onTrack(FlipData flip) { }
			public void onUntrack(int geId) { }
			public void onSearch(String query) { }
			public void onFetchAccount() { }
			public void onBuildPlan(long capital, int slots, int accounts, int hours) { }
			public void onDeleteFlip(String flipId) { }
			public void onDeleteLot(int itemId, int qty, long cost, long openedAt) { }
			public void onOpenPluginConfig() { }
		};

		final JPanel[] holder = new JPanel[1];
		EventQueue.invokeAndWait(() ->
		{
			final PriceCheckPanel panel = new PriceCheckPanel(stub, null, null, new PriceCheckConfig() { });
			final JPanel list = new JPanel();
			list.setLayout(new BoxLayout(list, BoxLayout.Y_AXIS));
			list.setBackground(new Color(30, 30, 30));
			final TrackedItem trackedItem = new TrackedItem();
			trackedItem.setGeId(24579);
			trackedItem.setName("Bloodbark legs");
			trackedItem.setEntryBuy(193_139);
			trackedItem.setSellNow(202_403L);
			trackedItem.setPnl(5_220);
			trackedItem.setRoi(2.7);
			trackedItem.setFloor(197_080);
			trackedItem.setStatus("healthy");
			list.add(panel.trackingCard(trackedItem));
			list.add(gap(list));
			list.add(panel.flipRow(flip("Uncharged toxic trident", 1_410_000, 1_495_000, 86_100, 1_240_000, true, null), false));
			list.add(gap(list));
			list.add(panel.flipRow(flip("Ranger boots", 32_850_000, 33_600_000, 385_240, 890_000, true, null), true));
			list.add(gap(list));
			list.add(panel.flipRow(flip("Tonalztics of ralos (uncharged)", 39_970_000, 40_390_000, 23_800, 310_000, false, "age"), false));
			list.add(gap(list));
			list.add(panel.flipRow(flip("Tumeken's shadow (uncharged)", 818_800_000, 824_500_000, 752_000, 1_710_000, false, "big"), false));
			holder[0] = list;
		});

		EventQueue.invokeAndWait(() ->
		{
			final int w = 226;
			holder[0].setSize(w, 2000);
			layoutTree(holder[0]);
			final int h = holder[0].getPreferredSize().height;
			holder[0].setSize(w, h);
			layoutTree(holder[0]);
			final BufferedImage img = new BufferedImage(w * 2, h * 2, BufferedImage.TYPE_INT_RGB);
			final Graphics2D g = img.createGraphics();
			g.scale(2, 2);
			g.setColor(new Color(30, 30, 30));
			g.fillRect(0, 0, w, h);
			holder[0].paint(g);
			g.dispose();
			try
			{
				ImageIO.write(img, "png", new File(out));
			}
			catch (Exception e)
			{
				throw new RuntimeException(e);
			}
		});
		System.out.println("wrote " + out);
	}

	private static FlipData flip(String name, long buy, long sell, long profit, long evPerHr, boolean confirmed, String risk)
	{
		final FlipData f = new FlipData();
		f.setGeId(4151);
		f.setName(name);
		f.setBuy(buy);
		f.setSell(sell);
		f.setProfit(profit);
		f.setEvPerHr(evPerHr);
		f.setConfirmed(confirmed);
		f.setRisk(risk);
		return f;
	}

	private static Component gap(JPanel parent)
	{
		return javax.swing.Box.createRigidArea(new java.awt.Dimension(0, 5));
	}

	private static void layoutTree(Component c)
	{
		c.doLayout();
		if (c instanceof Container)
		{
			for (final Component k : ((Container) c).getComponents())
			{
				layoutTree(k);
			}
		}
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.image.BufferedImage;
import java.io.File;
import java.util.ArrayList;
import java.util.List;
import javax.imageio.ImageIO;

/** Dev preview only: renders the active-offers board to a PNG so the layout can
 *  be judged headless. Not a test. */
public final class GeOffersPanelPreview
{
	private static final Color BUY = new Color(0x49, 0xc9, 0x7f);
	private static final Color SELL = new Color(0xd9, 0x5c, 0x5e);
	private static final Color HOLD = new Color(0x7f, 0xb0, 0xff);

	private GeOffersPanelPreview()
	{
	}

	private static GeOffersPanelOverlay.Row row(String chip, Color chipCol, String name, String verdict, Color vCol,
		long price, long margin, long total, long sold, long closeGp, int trend, boolean seated, String last, String lean)
	{
		final GeOffersPanelOverlay.Row r = new GeOffersPanelOverlay.Row();
		r.chip = chip;
		r.chipColor = chipCol;
		r.name = name;
		r.verdict = verdict;
		r.verdictColor = vCol;
		r.price = price;
		r.liveMargin = margin;
		r.totalQty = total;
		r.soldQty = sold;
		r.unfilledQty = Math.max(0, total - sold);
		r.posProfit = margin * total;
		r.closenessGp = closeGp;
		r.trend = trend;
		r.seated = seated;
		r.lastTrade = last;
		r.pressure = lean;
		r.pressureColor = "sell".equals(lean) ? Palette.RED : "buy".equals(lean) ? Palette.GREEN : Palette.SUBTLE_CANVAS;
		return r;
	}

	public static void main(String[] args) throws Exception
	{
		final List<GeOffersPanelOverlay.Row> rows = new ArrayList<>();
		rows.add(row("S", SELL, "Inquisitor's hauberk", "OK +1.85m", Palette.GREEN, 116_240_000L, 1_850_000L, 1, 0, 0, 1, true, "@116.24m 19m", "sell"));
		rows.add(row("S", SELL, "Scythe of vitur (uncharged)", "OK -2.64m", Palette.RED, 1_300_000_000L, -2_640_000L, 1, 0, 3_900_000L, 1, false, "@1.3b 14m", "flat"));
		rows.add(row("B", BUY, "Inquisitor's hauberk", "OK +1.85m", Palette.GREEN, 112_060_000L, 1_850_000L, 6, 2, 112_000L, 1, false, "@112m 29m", "sell"));
		rows.add(row("B", BUY, "Serpentine visage", "RAISE +156.88k", Palette.AMBER, 3_360_000L, 156_880L, 5, 0, 150_000L, -1, false, "@3.51m 14m", "sell"));
		rows.add(row("S", SELL, "Twisted bow", "OK +538.99k", Palette.GREEN, 1_490_000_000L, 538_990L, 1, 0, 1_490_000L, 0, false, "@1.49b 9m", "flat"));
		rows.add(row("B", BUY, "Harmonised orb", "HOLD", HOLD, 374_100_000L, 0, 1, 0, 7_100_000L, 1, false, "@378.46m 19m", "flat"));
		rows.add(row("B", BUY, "Twisted buckler", "OK +136.23k", Palette.GREEN, 17_800_000L, 136_230L, 8, 3, 90_000L, 0, false, "@17.89m 21s", "flat"));

		final String base = args.length > 0 ? args[0] : "offers-panel.png";
		render(rows, false, true, 1.0, base);                                  // Active: expanded, Shift shows [-]
		render(rows, true, true, 1.0, base.replace(".png", "-collapsed.png")); // Active: collapsed pill, [+]
		render(rows, false, true, 1.3, base.replace(".png", "-overnight.png")); // Overnight: 1.3x bigger
	}

	private static void render(List<GeOffersPanelOverlay.Row> rows, boolean collapsed, boolean shift, double contentScale, String path) throws Exception
	{
		final int scale = 2;   // supersample for a crisp PNG, independent of the overlay's own scale
		final int wLogical = (int) Math.round(GeOffersPanelOverlay.W * contentScale) + 16;
		final int hLogical = (int) Math.round(340 * contentScale);
		final BufferedImage img = new BufferedImage(wLogical * scale, hLogical * scale, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = img.createGraphics();
		g.scale(scale, scale);
		g.setColor(new Color(0x33, 0x2c, 0x22));   // GE-parchment-ish backdrop
		g.fillRect(0, 0, wLogical, hLogical);
		g.translate(8, 8);
		// Mirror the overlay's Overnight enlargement: a uniform content scale
		// around the same static painter the live overlay calls.
		g.scale(contentScale, contentScale);
		final GeOffersPanelOverlay.Result r = GeOffersPanelOverlay.paint(g, rows, collapsed, shift);
		g.dispose();
		ImageIO.write(img, "png", new File(path));
		System.out.println("wrote " + path + " panel " + r.size.width + "x" + r.size.height
			+ " (drawn " + Math.round(r.size.width * contentScale) + "x" + Math.round(r.size.height * contentScale) + ")");
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.GeneralPath;
import java.awt.image.BufferedImage;
import java.io.File;
import javax.imageio.ImageIO;

/**
 * Dev-only design mockup: the GE item card re-skinned in a terminal-terminal
 * language (amber-on-black, monospace tabular figures, a dense quote grid, a
 * time-and-sales tape, tick-flash). Standalone (no plugin painter dep) so the
 * real GeItemInfoPainter stays untouched until this look is approved.
 * Args: [outputPath]. Never shipped (test source set).
 */
public final class TerminalCardPreview
{
	private static final Color BG      = new Color(0x08, 0x08, 0x0a);
	private static final Color PANEL   = new Color(0x0d, 0x0d, 0x10);
	private static final Color BORDER  = new Color(0x39, 0x33, 0x1c);
	private static final Color AMBER   = new Color(0xe8, 0xb8, 0x4b);
	private static final Color AMBERHI = new Color(0xf6, 0xc9, 0x52);
	private static final Color LABEL   = new Color(0x8f, 0x88, 0x66);
	private static final Color DIM     = new Color(0x55, 0x51, 0x3d);
	private static final Color GREEN   = new Color(0x55, 0xc4, 0x6a);
	private static final Color RED     = new Color(0xf0, 0x56, 0x3f);
	private static final Color GRID    = new Color(0x1b, 0x1b, 0x14);
	private static final Color FLASH   = new Color(0x1e, 0x3a, 0x22);

	private TerminalCardPreview() { }

	private static Font mono(int s)  { return new Font("Monospaced", Font.PLAIN, s); }
	private static Font monoB(int s) { return new Font("Monospaced", Font.BOLD, s); }

	// right-align a string so it ENDS at xr
	private static void rt(Graphics2D g, String s, int xr, int y)
	{
		g.drawString(s, xr - g.getFontMetrics().stringWidth(s), y);
	}

	// A quote-grid cell: dim uppercase label on top, value below (right-aligned to the column).
	private static void cell(Graphics2D g, int x, int w, int y, String label, String value, Color vc)
	{
		g.setFont(mono(9));
		g.setColor(LABEL);
		g.drawString(label, x, y);
		g.setFont(monoB(13));
		g.setColor(vc);
		rt(g, value, x + w, y + 15);
	}

	public static void main(String[] args) throws Exception
	{
		System.setProperty("java.awt.headless", "true");
		// -Dpc.lang=ja renders the panel in Japanese, so the real layout can be
		// checked for clipping without launching a client. A property, not an
		// arg: some previews already parse their own positional args.
		if ("ja".equals(System.getProperty("pc.lang"))) { I18n.setLanguage(PriceCheckConfig.Language.JAPANESE); }
		final String out = args.length > 0 ? args[0] : "/tmp/bbg.png";
		final int W = 476, H = 660, S = 2;
		final BufferedImage img = new BufferedImage(W * S, H * S, BufferedImage.TYPE_INT_RGB);
		final Graphics2D g = img.createGraphics();
		g.scale(S, S);
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

		g.setColor(BG);
		g.fillRect(0, 0, W, H);
		g.setColor(PANEL);
		g.fillRect(6, 6, W - 12, H - 12);
		g.setColor(BORDER);
		g.setStroke(new BasicStroke(1f));
		g.drawRect(6, 6, W - 12, H - 12);

		final int L = 18, R = W - 18;
		int y = 26;

		// ── 1 · STATUS HEADER ──
		g.setFont(monoB(13));
		g.setColor(AMBERHI);
		g.drawString("TUMEKEN'S SHADOW (UNCHARGED)", L, y);
		g.setFont(mono(10));
		g.setColor(DIM);
		g.drawString("27277", L + 268, y);
		g.setFont(mono(10));
		final String liveStr = "LIVE 1.5s   20:14:07";
		final int liveW = g.getFontMetrics().stringWidth(liveStr);
		g.setColor(GREEN);
		g.fillOval(R - liveW - 13, y - 8, 6, 6);
		g.setColor(LABEL);
		g.drawString(liveStr, R - liveW, y);
		y += 8;
		g.setColor(GRID);
		g.drawLine(L, y, R, y);
		y += 16;

		// ── 2 · QUOTE GRID ── three columns
		final int cw = (R - L - 16) / 3, c0 = L, c1 = L + cw + 8, c2 = L + 2 * cw + 16;
		final int rowH = 30;
		cell(g, c0, cw, y, "BID",   "1,022,500", AMBER);
		cell(g, c1, cw, y, "ASK",   "1,050,000", AMBER);
		cell(g, c2, cw, y, "SPRD",  "27,500", AMBER);
		y += rowH;
		cell(g, c0, cw, y, "NET/EA", "+6,500", GREEN);
		cell(g, c1, cw, y, "ROI",    "+0.64%", GREEN);
		cell(g, c2, cw, y, "TAX",    "21,000", DIM.brighter());
		y += rowH;
		cell(g, c0, cw, y, "Δ1H",  "+0.8%", GREEN);
		cell(g, c1, cw, y, "Δ24H", "+3.4%", GREEN);
		cell(g, c2, cw, y, "VOL 24H",  "1,240", AMBER);
		y += rowH;
		cell(g, c0, cw, y, "HI",     "1,072,000", AMBER);
		cell(g, c1, cw, y, "LO",     "1,012,000", AMBER);
		cell(g, c2, cw, y, "OFI",    "+62% SELL", RED);
		y += rowH;
		cell(g, c0, cw, y, "LIMIT",  "4 / 8", AMBER);
		cell(g, c1, cw, y, "RESET",  "2h14m", AMBER);
		cell(g, c2, cw, y, "FILL",   "~6m", AMBER);
		y += rowH - 4;

		// verdict cells (two, full width)
		g.setFont(monoB(12));
		g.setColor(new Color(0x2a, 0x1e, 0x14));
		g.fillRect(L, y, (R - L) / 2 - 4, 20);
		g.fillRect(L + (R - L) / 2 + 4, y, (R - L) / 2 - 4, 20);
		g.setColor(AMBER);
		g.drawString("B  WAIT", L + 8, y + 14);
		g.setColor(GREEN);
		g.drawString("S  OK  +6.5k", L + (R - L) / 2 + 12, y + 14);
		y += 30;

		// ── 3 · CHART (band, amber grid) ──
		final int cx = L, cy = y, cW = R - L, cH = 96;
		g.setColor(GRID);
		for (int i = 0; i <= 3; i++)
		{
			int gy = cy + i * cH / 3;
			g.drawLine(cx, gy, cx + cW - 46, gy);
		}
		// price axis labels
		g.setFont(mono(9));
		g.setColor(LABEL);
		final String[] px = { "1.07m", "1.05m", "1.03m", "1.01m" };
		for (int i = 0; i < 4; i++)
		{
			g.drawString(px[i], cx + cW - 40, cy + i * cH / 3 + 3);
		}
		// series
		final int n = 60;
		final GeneralPath hi = new GeneralPath(), lo = new GeneralPath();
		final double loP = 1_012_000, hiP = 1_072_000;
		int lastHx = 0, lastHy = 0, lastLy = 0;
		for (int i = 0; i < n; i++)
		{
			double wave = Math.sin(i / 9.0) * 6500;
			double mid = 1_020_000 + i * 620 + wave;
			double sp = 22_000 + Math.abs(wave);
			double h = mid + sp / 2, lo2 = mid - sp / 2;
			int xx = cx + (int) (i * (cW - 48.0) / (n - 1));
			int hy = cy + (int) ((hiP - h) / (hiP - loP) * cH);
			int ly = cy + (int) ((hiP - lo2) / (hiP - loP) * cH);
			if (i == 0) { hi.moveTo(xx, hy); lo.moveTo(xx, ly); }
			else { hi.lineTo(xx, hy); lo.lineTo(xx, ly); }
			lastHx = xx; lastHy = hy; lastLy = ly;
		}
		// amber fill between
		final GeneralPath fill = new GeneralPath(hi);
		fill.lineTo(lastHx, lastLy);
		final double[] rev = new double[0];
		// build reverse of lo by re-walking
		final GeneralPath band = new GeneralPath();
		band.append(hi, false);
		for (int i = n - 1; i >= 0; i--)
		{
			double wave = Math.sin(i / 9.0) * 6500;
			double mid = 1_020_000 + i * 620 + wave;
			double sp = 22_000 + Math.abs(wave);
			double lo2 = mid - sp / 2;
			int xx = cx + (int) (i * (cW - 48.0) / (n - 1));
			int ly = cy + (int) ((hiP - lo2) / (hiP - loP) * cH);
			band.lineTo(xx, ly);
		}
		band.closePath();
		g.setColor(new Color(0x2a, 0x24, 0x12));
		g.fill(band);
		g.setStroke(new BasicStroke(1.4f));
		g.setColor(GREEN);
		g.draw(hi);
		g.setColor(RED);
		g.draw(lo);
		// your-sell dashed line
		g.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 1f, new float[]{3f, 3f}, 0f));
		g.setColor(AMBER);
		int syY = cy + (int) ((hiP - 1_050_000) / (hiP - loP) * cH);
		g.drawLine(cx, syY, cx + cW - 48, syY);
		g.setStroke(new BasicStroke(1f));
		g.setColor(AMBERHI);
		g.fillOval(lastHx - 3, lastHy - 3, 6, 6);
		y = cy + cH + 6;

		// timeframe function keys
		final String[] keys = { "LATEST", "24H", "7D" };
		int kx = L;
		for (int i = 0; i < keys.length; i++)
		{
			g.setFont(monoB(10));
			int kw = g.getFontMetrics().stringWidth(keys[i]) + 14;
			g.setColor(i == 0 ? new Color(0x3a, 0x2c, 0x10) : PANEL);
			g.fillRect(kx, y, kw, 16);
			g.setColor(BORDER);
			g.drawRect(kx, y, kw, 16);
			g.setColor(i == 0 ? AMBERHI : LABEL);
			g.drawString(keys[i], kx + 7, y + 12);
			kx += kw + 6;
		}
		g.setFont(mono(9));
		g.setColor(DIM);
		rt(g, "SPREAD 24H", R, y + 12);
		y += 26;

		// ── 4 · VOLUME + PRESSURE ──
		g.setColor(GRID);
		g.drawLine(L, y + 22, R, y + 22);
		for (int i = 0; i < 58; i++)
		{
			int bh = 3 + (int) (Math.abs(Math.sin(i / 4.0) * 18) + (i % 3) * 2);
			int bx = L + i * ((R - L) / 58);
			g.setColor(i % 2 == 0 ? new Color(0x6a, 0x55, 0x22) : new Color(0x4a, 0x3a, 0x18));
			g.fillRect(bx, y + 22 - bh, 2, bh);
		}
		g.setFont(mono(9));
		g.setColor(LABEL);
		g.drawString("VOL 24H", L, y + 34);
		y += 40;
		// pressure/OFI bar
		int pbW = R - L - 96;
		g.setColor(GREEN);
		g.fillRect(L, y, (int) (pbW * 0.38), 8);
		g.setColor(RED);
		g.fillRect(L + (int) (pbW * 0.38), y, pbW - (int) (pbW * 0.38), 8);
		g.setFont(monoB(10));
		g.setColor(RED);
		rt(g, "OFI +62% SELL", R, y + 8);
		y += 22;

		// ── 5 · TIME & SALES TAPE ──
		// ▲/▼ = a market print (buy-side / sell-side). ◆ (gold) = one of YOUR
		// fills, labelled past-tense with qty so it reads as history, not advice.
		g.setColor(GRID);
		g.drawLine(L, y - 4, R, y - 4);
		g.setFont(mono(9));
		g.setColor(LABEL);
		g.drawString("TIME & SALES", L, y + 7);
		g.setColor(GREEN); rt(g, "▲5", R - 26, y + 7);
		g.setColor(RED);   rt(g, "▼4", R, y + 7);
		y += 16;
		// column sub-header anchors the numbers
		g.setFont(mono(8));
		g.setColor(DIM);
		rt(g, "PRICE", L + 118, y);
		g.drawString("Δ VS YOU", L + 134, y);
		rt(g, "AGE", R, y);
		y += 20;
		final String[][] tape = {
			// marker, price, tag, age, flag(0 market,1 you,2 hi,3 lo)
			{ "▲", "1,049,900", "+2.4k",         "12s", "0" },
			{ "◆", "1,048,200", "YOU SOLD ×1",   "1m",  "1" },
			{ "▼", "1,046,500", "-3.4k",         "2m",  "0" },
			{ "▲", "1,050,600", "day high",      "26m", "2" },
			{ "▼", "1,039,800", "day low",       "41m", "3" },
			{ "▲", "1,043,500", "-7.0k",         "55m", "0" },
			{ "◆", "1,041,000", "YOU BOUGHT ×1", "1h",  "1" },
			{ "▲", "1,047,200", "-3.3k",         "1h",  "0" },
