			flips.get(3).setTrendPct(flips.get(3).getTrendPct() - 0.9);
		}
		TerminalRadarOverlay.paintColumn(g, w, availH, flips, catches, tfIdx, new ArrayList<>());
		g.dispose();
		ImageIO.write(img, "png", new File(out));
		System.out.println("wrote " + out);
	}
}

