package gg.pricecheck.runelite;

import lombok.Data;

/**
 * One flip as served by GET /api/plugin/flips. Field names match the server's
 * trimmed plugin shape exactly, so Gson maps them directly. No scoring internals
 * are sent: this is all the client ever sees.
 */
@Data
public class FlipData
{
	private int geId;
	private String name;
	private boolean members;
	private long buy;
	private long sell;
	private long margin;
	private long profit;
	private double roi;
	private long evPerHr;
	private boolean confirmed;
	private boolean fallingKnife;   // price dropping vs its 1h average -> margin at risk
	private double trendPct;        // mid vs 1h-avg, % (negative = falling)
	private double trend24h;        // mid vs 24h-avg, % (TOP MOVERS 24h window)
	private double trend7d;         // mid vs 7d-avg, %  (TOP MOVERS 7d window)
	private Long limit;             // null = no published buy limit for this item
	private long vol1h;
	private String risk;            // null = clean board row; else why it missed one quality bar
	private String quote;           // "band" = laneBid/laneAsk are resting p25/p75 levels
	private Long laneBid;           // big-lane resting quote (null = not a lane item)
	private Long laneAsk;
	private Double laneOdds;        // measured sell-fill odds for the lane play
	private Double laneHold;        // expected hold in hours
	                                // ("age" | "qty" | "ev" | "profit")

	String riskLabel()
	{
		if (risk == null)
		{
			return null;
		}
		switch (risk)
		{
			case "age": return "Stale Prints";
			case "qty": return "Slow Fills";
			case "ev": return "Low EV";
			case "profit": return "Small Margin";
			// Unknown code from a newer server: show it capitalized. An empty
			// string means no usable label at all, same as null.
			default: return risk.isEmpty() ? null
				: risk.substring(0, 1).toUpperCase(java.util.Locale.ROOT) + risk.substring(1);
		}
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Shape;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The desk's price TICKER: a thin full-width strip along the bottom of the screen
 * that scrolls the live board - item, direction and price - like an exchange tape.
 * Reads the ranked board (Trader Pro); only shows when market data is live and the
 * GE is open. Opt-in via config.terminalDesk(); look from TerminalKit.
 */
class TerminalTickerOverlay extends Overlay
{
	static final int H = 24;
	private static final int SCROLL_MS_PER_PX = 22;   // ~45 px/sec

	private final Client client;
	private final PriceCheckPlugin plugin;

	TerminalTickerOverlay(Client client, PriceCheckPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.terminalDesk() || !plugin.marketDataOk() || !plugin.isGrandExchangeOpen())
		{
			return null;
		}
		final List<FlipData> flips = plugin.boardFlips();
		if (flips.isEmpty())
		{
			return null;
		}
		// Snap directly under the session strip so the centre column reads as one
		// stack (Held / status / GE / Session / Ticker), at the same x and width.
		// Fall back to just below the GE when the session strip isn't shown.
		final int sb = plugin.sessionBottomY();
		final int x, w, y;
		if (sb > 0 && plugin.sessionX() >= 0 && plugin.sessionW() > 0)
		{
			x = plugin.sessionX();
			w = plugin.sessionW();
			y = sb + 4;
		}
		else
		{
			final Rectangle ge = plugin.geGridBounds();
			if (ge == null)
			{
				return null;
			}
			x = ge.x;
			w = ge.width;
			y = ge.y + ge.height + 4;
		}
		// Never poke into the chat box.
		int floor = client.getCanvasHeight() - 4;
		final Rectangle cb = plugin.chatboxBounds();
		if (cb != null && cb.height > 0)
		{
			floor = Math.min(floor, cb.y - 4);
		}
		if (y + H > floor)
		{
			return null;
		}
		// Keep the scroll phase as a long; paintTicker reduces it modulo the strip
		// width (casting the raw ms/px to int overflows and slings the tape off-screen).
		final long offset = System.currentTimeMillis() / SCROLL_MS_PER_PX;

		final Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Object taa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		final int ph;
		g.translate(x, y);
		try
		{
			ph = paintTicker(g, w, flips, offset);
		}
		finally
		{
			g.translate(-x, -y);
			if (aa != null) { g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa); }
			if (taa != null) { g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, taa); }
		}
		plugin.noteDeskRect("ticker", x, y, w, ph);
		return new Dimension(w, ph);
	}

	/** Pure drawing (0,0-origin). offset scrolls the tape leftward (0 = static, for
	 *  the headless preview). Draws the strip twice for a seamless wrap.
	 *  Returns the painted height. */
	static int paintTicker(Graphics2D g, int w, List<FlipData> flips, long offset)
	{
		TerminalKit.hints(g);
		g.setColor(TerminalKit.PANEL); g.fillRect(0, 0, w, H);
		g.setColor(TerminalKit.BORDER); g.drawLine(0, 0, w, 0);

		g.setFont(TerminalKit.monoB(12));
		final FontMetrics fm = g.getFontMetrics();
		final int n = Math.min(flips.size(), 24);
		final int contentW = stripWidth(fm, flips, n);
		if (contentW <= 0)
		{
			return H;   // the strip background is already down
		}
		final Shape clip = g.getClip();
		g.clipRect(0, 0, w, H);
		if (contentW <= w)
		{
			drawStrip(g, fm, flips, n, 8);
		}
		else
		{
			final int start = -(int) Math.floorMod(offset, (long) contentW);
			drawStrip(g, fm, flips, n, start);
			drawStrip(g, fm, flips, n, start + contentW);
		}
		g.setClip(clip);
		return H;
	}

	private static final int GAP = 26;

	private static int stripWidth(FontMetrics fm, List<FlipData> flips, int n)
	{
		int x = 0;
		for (int i = 0; i < n; i++)
		{
			x += segW(fm, flips.get(i)) + GAP;
		}
		return x;
	}

	private static int segW(FontMetrics fm, FlipData f)
	{
		return fm.stringWidth(label(f) + "  " + TerminalKit.gp(price(f)));
	}

	private static void drawStrip(Graphics2D g, FontMetrics fm, List<FlipData> flips, int n, int x0)
	{
		final int baseline = H / 2 + 5;
		int x = x0;
		for (int i = 0; i < n; i++)
		{
			final FlipData f = flips.get(i);
			final double t = f.getTrendPct();
			final Color c = t > 0.3 ? TerminalKit.GREEN : t < -0.3 ? TerminalKit.RED : TerminalKit.LABEL;
			final String arrow = t > 0.3 ? "▲" : t < -0.3 ? "▼" : "·";
			g.setColor(TerminalKit.AMBER);
			g.drawString(label(f), x, baseline);
			final int lw = fm.stringWidth(label(f));
			g.setColor(c);
			g.drawString(arrow + TerminalKit.gp(price(f)), x + lw + fm.stringWidth(" "), baseline);
			x += segW(fm, f) + GAP;
		}
	}

	private static long price(FlipData f)
	{
		return f.getSell() > 0 ? f.getSell() : f.getBuy();
	}

	private static String label(FlipData f)
	{
		final String nm = f.getName() == null ? ("#" + f.getGeId()) : f.getName();
		return nm.length() > 16 ? nm.substring(0, 16) : nm;
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import lombok.Value;

/** One line of advice for one active/finished GE slot. */
@Value
class OfferAdvice
{
	enum Kind
	{
		ON_TRACK, RAISE_BUY, DROP_SELL, DEAD, FALLING, HOLD, COLLECT, NO_DATA
	}

	int slot;
	String itemName;
	String side;       // "BUY", "SELL" or ""
	Kind kind;
	String message;    // the exact instruction: no filler (floating panel)
	String shortText;  // compact form for the on-slot status chip, e.g. "RAISE +12.9k"
	Color color;
}

package gg.pricecheck.runelite;

import java.awt.Color;

/**
 * Turns one active GE offer plus the live market into an exact instruction: keep
 * it, move it by a precise amount, or cancel it. Pure logic, no client or network
 * calls, so it is deterministic and unit-testable.
 *
 * Market reference (matches the server): to buy you place at FlipData.buy and to
 * sell at FlipData.sell. The server's prices are already positioned so an offer
 * at them heads the queue. Margins are post-GE-tax.
 */
final class OfferAdvisor
{
	private static final Color GREEN = new Color(0x5d, 0xf2, 0x9a);
	private static final Color AMBER = new Color(0xe6, 0xc6, 0x67);
	private static final Color RED = new Color(0xf2, 0x6b, 0x6d);
	private static final Color GREY = new Color(0x9a, 0x91, 0x7c);
	private static final Color BLUE = new Color(0xb5, 0xa1, 0x5e);   // patient hold: no action, will fill (dim gold - the desk has no blue)

	private OfferAdvisor()
	{
	}

	static OfferAdvice advise(TrackedOffer offer, FlipData live)
	{
		final int slot = offer.getSlot();

		if (offer.isDone())
		{
			final String nm = live != null ? live.getName() : "Item " + offer.getItemId();
			return new OfferAdvice(slot, nm, "", OfferAdvice.Kind.COLLECT, "Filled - collect", "COLLECT", GREY);
		}
		if (!offer.isActive())
		{
			return null;
		}

		final String side = offer.isBuying() ? "BUY" : "SELL";
		if (live == null)
		{
			return new OfferAdvice(slot, "Item " + offer.getItemId(), side, OfferAdvice.Kind.NO_DATA, "No live data yet", "", GREY);
		}

		final String name = live.getName();
		final long yourPrice = offer.getPrice();
		final long marketBuy = live.getBuy();      // current low  - place a BUY here
		final long marketSell = live.getSell();    // current high - place a SELL here
		// A returned-but-unpriced item deserializes to 0 (Gson leaves a missing
		// primitive at its default). Never derive a reprice target from that or
		// we'd tell a seller to "drop to 0" and give the item away.
		if (marketBuy <= 0 || marketSell <= 0)
		{
			return new OfferAdvice(slot, name, side, OfferAdvice.Kind.NO_DATA, "No live price yet", "", GREY);
		}
		final long marketMargin = live.getProfit(); // net(marketBuy, marketSell), post-tax

		// The one condition that turns a patient offer into a real problem: the item
		// is dropping against its own 1h average, so the spread is closing and waiting
		// only makes it worse. A thin or briefly-inverted spread on a stable item is
		// not that: it reopens and the offer still fills, so we hold rather than tell
		// the user to cancel or cut the price and lose value.
		final boolean falling = live.isFallingKnife() || live.getTrendPct() <= -2.0D;

		if (offer.isBuying())
		{
			// An offer that has already transacted is filling.
			final boolean filling = offer.getSoldQty() > 0;
			final long yourMargin = GeTax.net(yourPrice, marketSell);

			// A real error, not a market wobble: bidding at or above the price you
			// could sell into is a guaranteed loss whatever the trend. Lower it.
			if (yourPrice >= marketSell)
			{
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.DEAD,
					"Bid at/above the sell price - " + signed(yourMargin) + " if it fills, lower it", "BID TOO HIGH", RED);
			}
			// Dead: the price is falling and there is no margin left, so the spread
			// will not reopen soon. This is the only cancel-a-buy state.
			if (falling && marketMargin <= 0)
			{
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.DEAD,
					"Price falling and margin gone (" + signed(marketMargin) + ") - cancel", "MARGIN DEAD", RED);
			}
			// Falling but not yet filling: a heads-up, not a cancel.
			if (!filling && falling)
			{
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.FALLING,
					"Price falling " + pct(Math.abs(live.getTrendPct())) + " - margin closing, watch it",
					"FALLING " + pct(Math.abs(live.getTrendPct())), AMBER);
			}
			// Spread thin or briefly gone but the item is not falling: the buy still
			// fills and the spread reopens. Hold it. Do not tell the user to cancel a
			// buy that will fill.
			if (marketMargin <= 0)
			{
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.HOLD,
					"Spread thin right now, not falling - the buy still fills, hold for it to reopen", "HOLD", BLUE);
			}
			// Sitting below the low and not yet buying: nudge the bid to head the queue.
			final long buyTol = Math.max(marketBuy / 100, 1);
			if (!filling && yourPrice < marketBuy - buyTol)
			{
				final long delta = marketBuy - yourPrice;
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.RAISE_BUY,
					"Raise buy to " + full(marketBuy) + " (+" + gp(delta) + ") - margin " + signed(marketMargin),
					"RAISE +" + gp(delta), AMBER);
			}
			return new OfferAdvice(slot, name, side, OfferAdvice.Kind.ON_TRACK,
				"On track - " + signed(yourMargin) + " if sold at market", "OK " + signed(yourMargin), GREEN);
		}

		// SELLING: an ask above the current high is a PATIENT sell, not a mistake -
		// it fills when a buyer prints up at your price. Only advise a drop when the
		// item is actually falling, so waiting would cost you; otherwise hold and let
		// it fill, rather than telling the user to cut the price and lose value.
		final boolean sellFilling = offer.getSoldQty() > 0;
		final long sellTol = Math.max(marketSell / 100, 1);
		if (!sellFilling && yourPrice > marketSell + sellTol)
		{
			final long delta = yourPrice - marketSell;
			if (falling)
			{
				return new OfferAdvice(slot, name, side, OfferAdvice.Kind.DROP_SELL,
					"Above market and price falling " + pct(Math.abs(live.getTrendPct())) + " - drop to " + full(marketSell) + " so it fills",
					"DROP -" + gp(delta), AMBER);
			}
			return new OfferAdvice(slot, name, side, OfferAdvice.Kind.HOLD,
				"Patient sell, " + gp(delta) + " above the current high - it fills when a buyer prints up here, holding", "HOLD", BLUE);
		}
		return new OfferAdvice(slot, name, side, OfferAdvice.Kind.ON_TRACK,
			"On track - at/near market, filling (" + signed(marketMargin) + " live margin)", "OK " + signed(marketMargin), GREEN);
	}

	private static String signed(long n)
	{
		return (n >= 0 ? "+" : "-") + gp(Math.abs(n));
	}

	private static String pct(double p)
	{
		return String.format("%.1f%%", p);
	}

	/** Exact, comma-grouped price to type into the GE. */
	static String full(long n)
	{
		return String.format("%,d", n);
	}

	/** Compact gp for deltas and margins. */
	static String gp(long n)
	{
		final long a = Math.abs(n);
		final String sign = n < 0 ? "-" : "";
		if (a >= 1_000_000_000L)
		{
			return sign + trim(a / 1e9D) + "b";
		}
		if (a >= 1_000_000L)
		{
			return sign + trim(a / 1e6D) + "m";
		}
		if (a >= 1_000L)
		{
			return sign + trim(a / 1e3D) + "k";
		}
		return String.valueOf(n);
	}

	private static String trim(double d)
	{
		String s = String.format("%.2f", d);
		if (s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s;
	}
}

package gg.pricecheck.runelite;

import com.google.gson.Gson;
import java.io.IOException;
import java.util.Collection;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.extern.slf4j.Slf4j;
import okhttp3.HttpUrl;
import okhttp3.MediaType;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.RequestBody;
import okhttp3.Response;

/**
 * The only network surface. Calls the gated data API with the user's plugin key
 * as a Bearer token. The server re-checks the subscription live on every request,
 * so a lapsed sub returns 403 here and the panel goes empty: there is no local
 * gate to bypass.
 */
@Slf4j
@Singleton
public class PriceCheckApiClient
{
	// Hardcoded on purpose: this is our endpoint, not something the user sets.
	private static final HttpUrl BASE = HttpUrl.get("https://flipping.pricecheck.gg/api/plugin");

	private final OkHttpClient http;
	private final Gson gson;

	@Inject
	PriceCheckApiClient(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	enum AuthState
	{
		OK, NO_KEY, INVALID_KEY, NO_SUBSCRIPTION, PLAN_REQUIRED, ERROR
	}

	// 403 means either a lapsed subscription or a plan below Trader Pro: the
	// body's error code tells them apart so the panel can say the right thing.
	private AuthState forbiddenState(Response res)
	{
		try
		{
			final String body = res.body() != null ? res.body().string() : "";
			if (body.contains("plan_required"))
			{
				return AuthState.PLAN_REQUIRED;
			}
		}
		catch (IOException | RuntimeException ignored)
		{
		}
		return AuthState.NO_SUBSCRIPTION;
	}

	static final class FlipsResult
	{
		final AuthState state;
		final List<FlipData> flips;
		// The movers sibling array on /flips: live dumps for the Catch tab. Empty
		// on every path that carries no board data (search, errors, older builds).
		final List<CatchData> catches;

		FlipsResult(AuthState state, List<FlipData> flips)
		{
			this(state, flips, Collections.emptyList());
		}

		FlipsResult(AuthState state, List<FlipData> flips, List<CatchData> catches)
		{
			this.state = state;
			this.flips = flips;
			this.catches = catches != null ? catches : Collections.emptyList();
		}
	}

	FlipsResult getFlips(String key, int limit)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new FlipsResult(AuthState.NO_KEY, Collections.emptyList());
		}

		final HttpUrl url = BASE.newBuilder()
			.addPathSegment("flips")
			.addQueryParameter("limit", String.valueOf(limit))
			.build();
		final Request req = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + key.trim())
			.build();

		try (Response res = http.newCall(req).execute())
		{
			switch (res.code())
			{
				case 401:
					return new FlipsResult(AuthState.INVALID_KEY, Collections.emptyList());
				case 403:
					return new FlipsResult(forbiddenState(res), Collections.emptyList());
				default:
					break;
			}
			if (!res.isSuccessful() || res.body() == null)
			{
				return new FlipsResult(AuthState.ERROR, Collections.emptyList());
			}
			final FlipsResponse parsed = gson.fromJson(res.body().string(), FlipsResponse.class);
			final List<FlipData> flips = parsed != null && parsed.flips != null
				? parsed.flips : Collections.emptyList();
			final List<CatchData> movers = parsed != null && parsed.movers != null
				? parsed.movers : Collections.emptyList();
			return new FlipsResult(AuthState.OK, flips, movers);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck flips fetch failed", e);
			return new FlipsResult(AuthState.ERROR, Collections.emptyList());
		}
	}

	private static final class FlipsResponse
	{
		boolean ok;
		long scannedAt;
		List<FlipData> flips;
		List<CatchData> movers;
	}

	/** A day of 5m windows for one item, plus the board's live read of it. */
	static final class SeriesData
	{
		long[] ts;
		long[] ah;
		long[] al;
		int[] hv;
		int[] lv;
		long quoteBuy;
		long quoteSell;
		int fillPct = -1;
	}

	private static final class SeriesResponse
	{
		SeriesBody series;
		QuoteBody quote;
	}

	private static final class SeriesBody
	{
		long[] ts;
		long[] ah;
		long[] al;
		int[] hv;
		int[] lv;
	}

	private static final class QuoteBody
	{
		long buy;
		long sell;
		int fillPct;
	}

	/** Bind the current game account to an active trial. The server no-ops
	 * for non-trial users, so this is safe to send on every login. */
	void bindTrialAccount(String key, long accountHash)
	{
		if (key == null || key.trim().isEmpty() || accountHash == 0 || accountHash == -1)
		{
			return;
		}
		final java.util.Map<String, Object> body = new java.util.HashMap<>();
		body.put("accountHash", String.valueOf(accountHash));
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("trial").addPathSegment("account").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response res = http.newCall(req).execute())
		{
			// Outcome is server-side; a revoked trial surfaces naturally as
			// the next market poll losing access.
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck trial bind failed", e);
		}
	}

	/** Report the Discord offer-alert cadence the user chose. Fire-and-forget;
	 *  the server 400s an unknown mode and 404s a non-Pro key, both harmless. */
	void postAlertMode(String key, String mode)
	{
		if (key == null || key.trim().isEmpty() || mode == null)
		{
			return;
		}
		final java.util.Map<String, Object> body = new java.util.HashMap<>();
		body.put("mode", mode);
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("alerts").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response res = http.newCall(req).execute())
		{
			// Server owns the outcome; nothing to read back.
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck alert-mode post failed", e);
		}
	}

	/** Fetch the evidence-chart series for one item. Null on any failure. */
	SeriesData fetchSeries(String key, int geId)
	{
		return fetchSeries(key, geId, null);
	}

	/** {@code window} selects a longer server series (e.g. "7d"); null is the
	 *  default day series. Unknown windows are ignored server-side. */
	SeriesData fetchSeries(String key, int geId, String window)
	{
		if (key == null || key.trim().isEmpty() || geId <= 0)
		{
			return null;
		}
		final okhttp3.HttpUrl.Builder url = BASE.newBuilder()
			.addPathSegment("series").addPathSegment(String.valueOf(geId));
		if (window != null && !window.isEmpty())
		{
			url.addQueryParameter("window", window);
		}
		final Request req = new Request.Builder()
			.url(url.build())
			.header("Authorization", "Bearer " + key.trim())
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return null;
			}
			final SeriesResponse parsed = gson.fromJson(res.body().string(), SeriesResponse.class);
			if (parsed == null || parsed.series == null || parsed.series.ts == null)
			{
				return null;
			}
			final SeriesData out = new SeriesData();
			out.ts = parsed.series.ts;
			out.ah = parsed.series.ah;
			out.al = parsed.series.al;
			out.hv = parsed.series.hv;
			out.lv = parsed.series.lv;
			if (parsed.quote != null)
			{
				out.quoteBuy = parsed.quote.buy;
				out.quoteSell = parsed.quote.sell;
				out.fillPct = parsed.quote.fillPct;
			}
			return out;
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck series fetch failed", e);
			return null;
		}
	}

	/** Server-side search over ALL tradeable items (not just the ranked flips). */
	FlipsResult searchItems(String key, String query)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new FlipsResult(AuthState.NO_KEY, Collections.emptyList());
		}
		if (query == null || query.trim().length() < 2)
		{
			return new FlipsResult(AuthState.OK, Collections.emptyList());
		}
		final HttpUrl url = BASE.newBuilder()
			.addPathSegment("search")
			.addQueryParameter("q", query.trim())
			.build();
		final Request req = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + key.trim())
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (res.code() == 401)
			{
				return new FlipsResult(AuthState.INVALID_KEY, Collections.emptyList());
			}
			if (res.code() == 403)
			{
				return new FlipsResult(AuthState.NO_SUBSCRIPTION, Collections.emptyList());
			}
			if (!res.isSuccessful() || res.body() == null)
			{
				return new FlipsResult(AuthState.ERROR, Collections.emptyList());
			}
			final SearchResponse parsed = gson.fromJson(res.body().string(), SearchResponse.class);
			final List<FlipData> results = parsed != null && parsed.results != null
				? parsed.results : Collections.emptyList();
			return new FlipsResult(AuthState.OK, results);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck search failed", e);
			return new FlipsResult(AuthState.ERROR, Collections.emptyList());
		}
	}

	private static final class SearchResponse
	{
		long scannedAt;
		List<FlipData> results;
	}

	/** Account identity for the Settings tab. Returns null on any failure. */
	AccountInfo getAccount(String key)
	{
		if (key == null || key.trim().isEmpty())
		{
			return null;
		}
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("me").build())
			.header("Authorization", "Bearer " + key.trim())
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return null;
			}
			return gson.fromJson(res.body().string(), AccountInfo.class);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck account fetch failed", e);
			return null;
		}
	}

	/** Live data for a set of item ids (the items in your active GE offers). */
	Map<Integer, FlipData> getItems(String key, Collection<Integer> ids)
	{
		return getItems(key, ids, null);
	}

	/** {@code window} ("1h"/"24h"/"7d") re-prices buy/sell/profit to that window's
	 *  reachable levels; null is the live quote. */
	Map<Integer, FlipData> getItems(String key, Collection<Integer> ids, String window)
	{
		if (key == null || key.trim().isEmpty() || ids == null || ids.isEmpty())
		{
			return Collections.emptyMap();
		}
		final String idsCsv = ids.stream().map(String::valueOf).collect(Collectors.joining(","));
		final HttpUrl.Builder ub = BASE.newBuilder()
			.addPathSegment("items")
			.addQueryParameter("ids", idsCsv);
		if (window != null && !window.isEmpty())
		{
			ub.addQueryParameter("window", window);
		}
		final HttpUrl url = ub.build();
		final Request req = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + key.trim())
			.build();

		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return Collections.emptyMap();
			}
			final ItemsResponse parsed = gson.fromJson(res.body().string(), ItemsResponse.class);
			if (parsed == null || parsed.items == null)
			{
				return Collections.emptyMap();
			}
			final Map<Integer, FlipData> map = new HashMap<>(parsed.items.size());
			for (FlipData f : parsed.items)
			{
				map.put(f.getGeId(), f);
			}
			return map;
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck items fetch failed", e);
			return Collections.emptyMap();
		}
	}

	private static final class ItemsResponse
	{
		long scannedAt;
		List<FlipData> items;
	}

	// ── Tracked positions (shared account store with the website dashboard) ──

	static final class TrackedResult
	{
		final AuthState state;
		final List<TrackedItem> tracked;

		TrackedResult(AuthState state, List<TrackedItem> tracked)
		{
			this.state = state;
			this.tracked = tracked;
		}
	}

	private static final MediaType JSON = MediaType.get("application/json");

	private TrackedResult readTracked(Request req)
	{
		try (Response res = http.newCall(req).execute())
		{
			switch (res.code())
			{
				case 401:
					return new TrackedResult(AuthState.INVALID_KEY, Collections.emptyList());
				case 403:
					return new TrackedResult(AuthState.NO_SUBSCRIPTION, Collections.emptyList());
				default:
					break;
			}
			if (!res.isSuccessful() || res.body() == null)
			{
				return new TrackedResult(AuthState.ERROR, Collections.emptyList());
			}
			final TrackedResponse parsed = gson.fromJson(res.body().string(), TrackedResponse.class);
			final List<TrackedItem> list = parsed != null && parsed.tracked != null
				? parsed.tracked : Collections.emptyList();
			return new TrackedResult(AuthState.OK, list);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck tracked call failed", e);
			return new TrackedResult(AuthState.ERROR, Collections.emptyList());
		}
	}

	TrackedResult getTracked(String key)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new TrackedResult(AuthState.NO_KEY, Collections.emptyList());
		}
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("tracked").build())
			.header("Authorization", "Bearer " + key.trim())
			.build();
		return readTracked(req);
	}

	/** Start tracking an item at the given cost basis. Returns the updated list. */
	TrackedResult addTracked(String key, int geId, long entryBuy, String name, long entryMargin)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new TrackedResult(AuthState.NO_KEY, Collections.emptyList());
		}
		final Map<String, Object> body = new HashMap<>();
		body.put("geId", geId);
		body.put("entryBuy", entryBuy);
		if (name != null) body.put("name", name);
		body.put("entryMargin", entryMargin);
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("tracked").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		return readTracked(req);
	}

	TrackedResult removeTracked(String key, int geId)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new TrackedResult(AuthState.NO_KEY, Collections.emptyList());
		}
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("tracked").addPathSegment(String.valueOf(geId)).build())
			.header("Authorization", "Bearer " + key.trim())
			.delete()
			.build();
		return readTracked(req);
	}

	private static final class TrackedResponse
	{
		long scannedAt;
		List<TrackedItem> tracked;
	}

	// ── Slot planner ──

	static final class PlanResult
	{
		final AuthState state;
		final PlanData plan;        // null unless state == OK
		final boolean needCapital;  // server has no capital for you and none was sent

		PlanResult(AuthState state, PlanData plan, boolean needCapital)
		{
			this.state = state;
			this.plan = plan;
			this.needCapital = needCapital;
		}
	}

	/** Build a plan. capital < 0 means "use my last reported bank total". */
	PlanResult getPlan(String key, long capital, int slots, int accounts, int hours)
	{
		if (key == null || key.trim().isEmpty())
		{
			return new PlanResult(AuthState.NO_KEY, null, false);
		}
		final HttpUrl.Builder url = BASE.newBuilder()
			.addPathSegment("plan")
			.addQueryParameter("slots", String.valueOf(slots))
			.addQueryParameter("accounts", String.valueOf(accounts))
			.addQueryParameter("hours", String.valueOf(hours));
		if (capital >= 0)
		{
			url.addQueryParameter("capital", String.valueOf(capital));
		}
		final Request req = new Request.Builder()
			.url(url.build())
			.header("Authorization", "Bearer " + key.trim())
			.build();
		try (Response res = http.newCall(req).execute())
		{
			switch (res.code())
			{
				case 401:
					return new PlanResult(AuthState.INVALID_KEY, null, false);
				case 403:
					return new PlanResult(forbiddenState(res), null, false);
				case 400:
					return new PlanResult(AuthState.OK, null, true);
				default:
					break;
			}
			if (!res.isSuccessful() || res.body() == null)
			{
				return new PlanResult(AuthState.ERROR, null, false);
			}
			final PlanData parsed = gson.fromJson(res.body().string(), PlanData.class);
			return new PlanResult(parsed != null ? AuthState.OK : AuthState.ERROR, parsed, false);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck plan fetch failed", e);
			return new PlanResult(AuthState.ERROR, null, false);
		}
	}

	/** Sync a flip-log batch (fills + flips + open lots) for one game account.
	 *  Free-tier endpoint: needs only a valid key. Returns true when the server
	 *  accepted the batch (the caller then marks it synced). */
	boolean postFills(String key, FlipLogEngine.SyncBatch batch)
	{
		if (key == null || key.trim().isEmpty() || batch == null)
		{
			return false;
		}
		final Map<String, Object> body = new HashMap<>(4);
		body.put("accountHash", String.valueOf(batch.accountHash));
		body.put("lotsMutMs", batch.lotsMutMs);
		final List<Map<String, Object>> fills = new java.util.ArrayList<>(batch.fills.size());
		for (final FlipLogEngine.Fill f : batch.fills)
		{
			final Map<String, Object> m = new HashMap<>(8);
			m.put("id", f.id);
			m.put("itemId", f.itemId);
			m.put("buy", f.buy);
			m.put("qty", f.qty);
			m.put("gross", f.gross);
			m.put("tax", f.tax);
			m.put("ts", f.ts);
			fills.add(m);
		}
		body.put("fills", fills);
		final List<Map<String, Object>> flips = new java.util.ArrayList<>(batch.flips.size());
		for (final FlipLogEngine.Flip f : batch.flips)
		{
			final Map<String, Object> m = new HashMap<>(10);
			m.put("id", f.id);
			m.put("itemId", f.itemId);
			m.put("itemName", f.name);
			m.put("qty", f.qty);
			m.put("buyGross", f.buyGross);
			m.put("sellGross", f.sellGross);
			m.put("tax", f.tax);
			m.put("openedAt", f.openedAt);
			m.put("closedAt", f.closedAt);
			m.put("marginCheck", f.check);
			flips.add(m);
		}
		body.put("flips", flips);
		final List<Map<String, Object>> lots = new java.util.ArrayList<>(batch.lots.size());
		for (final FlipLogEngine.Lot l : batch.lots)
		{
			final Map<String, Object> m = new HashMap<>(6);
			m.put("itemId", l.itemId);
			m.put("itemName", l.name);
			m.put("qty", l.qty);
			m.put("cost", l.cost);
			m.put("openedAt", l.openedAt);
			lots.add(m);
		}
		body.put("lots", lots);
		if (batch.deletes != null && !batch.deletes.isEmpty())
		{
			body.put("deletes", batch.deletes);
		}
		final List<Map<String, Object>> slots = new java.util.ArrayList<>(batch.slots == null ? 0 : batch.slots.size());
		if (batch.slots != null)
		{
			for (final FlipLogEngine.SlotExport s : batch.slots)
			{
				final Map<String, Object> m = new HashMap<>(10);
				m.put("slot", s.slot);
				m.put("itemId", s.itemId);
				m.put("qtySold", s.qtySold);
				m.put("total", s.total);
				m.put("price", s.price);
				m.put("spent", s.spent);
				m.put("state", s.state);
				m.put("placedMs", s.placedMs);
				m.put("updatedMs", s.updatedMs);
				slots.add(m);
			}
		}
		body.put("slots", slots);
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("fills").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response res = http.newCall(req).execute())
		{
			return res.isSuccessful();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck fills sync failed", e);
			return false;
		}
	}

	/** The freshest slot snapshots + open lots another machine uploaded for
	 *  this game account (the multi-machine handoff). Null on any failure. */
	FlipLogEngine.RemoteState getSlots(String key, long accountHash)
	{
		if (key == null || key.trim().isEmpty() || accountHash == -1)
		{
			return null;
		}
		final HttpUrl url = BASE.newBuilder()
			.addPathSegment("slots")
			.addQueryParameter("account", String.valueOf(accountHash))
			.build();
		final Request req = new Request.Builder()
			.url(url)
			.header("Authorization", "Bearer " + key.trim())
			.build();
		try (Response res = http.newCall(req).execute())
		{
			if (!res.isSuccessful() || res.body() == null)
			{
				return null;
			}
			return gson.fromJson(res.body().string(), FlipLogEngine.RemoteState.class);
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck slots fetch failed", e);
			return null;
		}
	}

	/** Report the player's liquid capital (coins + platinum tokens, bank +
	 *  inventory) so the web planner can prefill. Best-effort. */
	boolean postCapital(String key, long coins, long platTokens)
	{
		if (key == null || key.trim().isEmpty())
		{
			return false;
		}
		final Map<String, Object> body = new HashMap<>(2);
		body.put("coins", coins);
		body.put("platTokens", platTokens);
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("capital").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response res = http.newCall(req).execute())
		{
			return res.isSuccessful();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck capital post failed", e);
			return false;
		}
	}

	/** Ship a batch of the player's own GE offer events (see TelemetryCollector).
	 *  Best-effort: any failure just drops the batch. */
	boolean postTelemetry(String key, List<Map<String, Object>> events)
	{
		if (key == null || key.trim().isEmpty() || events == null || events.isEmpty())
		{
			return false;
		}
		final Map<String, Object> body = new HashMap<>(1);
		body.put("events", events);
		final Request req = new Request.Builder()
			.url(BASE.newBuilder().addPathSegment("telemetry").build())
			.header("Authorization", "Bearer " + key.trim())
			.post(RequestBody.create(JSON, gson.toJson(body)))
			.build();
		try (Response res = http.newCall(req).execute())
		{
			return res.isSuccessful();
		}
		catch (IOException | RuntimeException e)
		{
			log.debug("PriceCheck telemetry post failed", e);
			return false;
		}
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.Collections;
import java.util.Map;
import java.util.WeakHashMap;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Draws the plugin's own Grand Exchange lines in a language the game cannot.
 *
 * The client's fonts carry no Japanese glyphs, so writing kana into a widget
 * paints nothing at all. Instead the widget keeps an EMPTY string - it still
 * owns its bounds, its right-click action and its hover - and this overlay
 * paints the translated line over the top in a face that can draw it.
 *
 * English never comes through here: the helper writes the text into the widget
 * itself, exactly as before.
 */
class GeLabelOverlay extends Overlay
{
	// Keyed on the widget, weakly: the GE rebuilds its children constantly, and
	// a dropped widget must not keep its label alive.
	private static final Map<Widget, String> LABELS =
		Collections.synchronizedMap(new WeakHashMap<>());

	private static final Font BASE = new Font(Font.SANS_SERIF, Font.BOLD, 11);

	static void note(Widget w, String text)
	{
		if (w != null && text != null && !text.isEmpty())
		{
			LABELS.put(w, text);
		}
	}

	static void clear()
	{
		LABELS.clear();
	}

	GeLabelOverlay()
	{
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!I18n.japanese() || LABELS.isEmpty())
		{
			return null;
		}
		final Object aa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
		try
		{
			synchronized (LABELS)
			{
				final java.util.Iterator<Map.Entry<Widget, String>> it = LABELS.entrySet().iterator();
				while (it.hasNext())
				{
					final Map.Entry<Widget, String> e = it.next();
					final Widget w = e.getKey();
					// A widget the GE has torn down keeps no bounds; drop it
					// rather than wait for the collector, so nothing can paint
					// over whatever the client puts there next.
					if (w == null || w.getBounds() == null)
					{
						it.remove();
						continue;
					}
					paint(g, w, e.getValue());
				}
			}
		}
		finally
		{
			if (aa != null)
			{
				g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, aa);
			}
		}
		return null;
	}

	private void paint(Graphics2D g, Widget w, String text)
	{
		if (w == null || w.isHidden())
		{
			return;
		}
		final Rectangle b = w.getBounds();
		if (b == null || b.width <= 0 || b.height <= 0)
		{
			return;
		}
		final Font f = I18n.font(BASE);
		g.setFont(f);
		final FontMetrics fm = g.getFontMetrics();
		// Sit on the line the widget's own text would have used.
		final int y = b.y + (b.height + fm.getAscent() - fm.getDescent()) / 2;
		// The widget's live colour, so the hover highlight still reads.
		g.setColor(new Color(w.getTextColor() & 0xFFFFFF));
		g.drawString(text, b.x, y);
	}
}

