package gg.pricecheck.runelite;

import com.google.gson.Gson;
import com.google.gson.annotations.SerializedName;
import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.StandardCopyOption;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.Iterator;
import java.util.List;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.GameState;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * The free flip log: an exact, crash-proof ledger of every Grand Exchange fill,
 * matched into flips. Design goals, each aimed at a documented weakness in the
 * incumbent trackers:
 *
 *  - Exact gp. Fills are deltas of the client's cumulative spent/quantity
 *    counters against a persisted per-slot snapshot (the same method RuneLite
 *    itself uses for its trade submissions), so partial fills and price
 *    improvement are real coins, never an averaged int. All math is long.
 *  - NEVER lose a flip. State is written atomically (temp file + move) after
 *    every mutating event, not on shutdown.
 *  - DETERMINISTIC matching. Buys become lots; sells consume lots FIFO with
 *    proportional cost. Open positions are first-class (visible, with cost
 *    basis), margin checks (qty-1 probes completing within 2 ticks) are tagged
 *    and kept out of the win rate, and sells with no tracked cost are counted
 *    separately instead of inventing profit.
 *  - Keyed by account hash, so a display-name change never orphans history.
 *
 * Runs on the client thread (offer events); the sync drain runs on the poller.
 * All cross-thread access goes through synchronized methods on this object.
 */
@Slf4j
class FlipLogEngine
{
	private static final int SLOTS = 8;
	private static final int LOGIN_BURST_TICKS = 2;   // events this close to login aggregate offline fills
	// A qty-1 offer completing this fast after placement is a spread probe, not
	// a flip. Wall-clock, so it survives client restarts (game ticks do not).
	private static final long MARGIN_CHECK_MS = 3000;
	private static final long ACTIVE_WINDOW_MS = 10 * 60_000L;   // GE activity gap that still counts as flipping
	private static final int MAX_FLIPS_KEPT = 5000;
	private static final int MAX_PENDING_FILLS = 2000;
	private static final int MAX_OPEN_LOTS = 400;
	private static final long FLIP_MERGE_MS = 5 * 60_000L;   // fold a nibbling sell offer's fills into one flip
	// A margin check is a PAIR of probes: a qty-1 buy that crossed at once and
	// a qty-1 sell that crossed at once, minutes apart. One fast side alone is
	// how a real 1-item position (a bow, an orb) is normally opened or closed.
	private static final long CHECK_PAIR_MS = 10 * 60_000L;
	private static final int MAX_UNTRACKED = 200;

	static class SlotSnap
	{
		int itemId;
		int qtySold;
		int total;
		long price;
		long spent;
		String state;
		// Wall-clock placement time; 0 = placement never seen (first sight
		// mid-trade), which can never qualify as a margin check.
		long placedMs;
		// Last mutation time: the multi-machine handoff picks whichever copy
		// of a slot (local file vs server) is fresher.
		long updatedMs;
	}

	/** GET /slots response: the freshest state another machine uploaded. */
	static class RemoteState
	{
		List<SlotExport> slots;
		long slotsUpdatedAt;
		List<Lot> lots;
		long lotsUpdatedAt;
		// The uploading client's own lotsMutMs (its clock), 0 when the server
		// has no stamp for the row yet.
		long lotsMutMs;
		// Flips deleted on the web or on another machine; applied on adoption so
		// a delete anywhere is a delete everywhere.
		List<String> deletions;
	}

	/** Slot snapshot as it travels to/from the server. */
	static class SlotExport
	{
		int slot;
		int itemId;
		int qtySold;
		int total;
		long price;
		long spent;
		String state;
		long placedMs;
		long updatedMs;
	}

	/** One GE offer event captured as primitives (safe to replay off-thread). */
	private static class HeldEvent
	{
		int slot;
		int itemId;
		int qtySold;
		int total;
		long price;
		long spent;
		GrandExchangeOfferState st;
		boolean loggedIn;
		int tick;
		int lastLoginTick;
		String name;
	}

	static class Fill
	{
		String id;
		int itemId;
		boolean buy;
		int qty;
		long gross;
		long tax;
		long ts;
		boolean agg;      // login-burst aggregate: real coins, unreliable timing
		transient boolean check;
		transient String name;
		// Was the offer resting when this fill landed (1), crossed instantly
		// (0), or unknown (-1)? Resting fills surface on the OPPOSITE wiki
		// side, which the card's own-trade matcher scores on.
		transient int resting = -1;
	}

	static class Lot
	{
		int itemId;
		// The server ships lots as "itemName"; the local file has always said
		// "name". Without the alternate, every multi-machine adoption nulled the
		// name and the panel degraded to "#itemId".
		@SerializedName(value = "name", alternate = {"itemName"})
		String name;
		int qty;
		long cost;
		long openedAt;
		boolean check;
	}

	/** A sell that found no open lot of the item: real coins, unknown cost.
	 *  Kept visible in the log so a sale never silently disappears; never
	 *  counted as profit and never sent to the server as a flip. */
	static class Untracked
	{
		int itemId;
		String name;
		int qty;
		long gross;
		long tax;
		long ts;
	}

	static class Flip
	{
		String id;
		int itemId;
		String name;
		int qty;
		long buyGross;
		long sellGross;
		long tax;
		long profit;
		long openedAt;
		long closedAt;
		boolean check;
		boolean synced;
	}

	static class Data
	{
		int v = 1;
		// One-time heal flag for the merge-resync fix. Absent in all pre-fix
		// saves, so it defaults false and the re-sync runs exactly once per
		// account, then stays true.
		boolean resyncFlipsV2;
		SlotSnap[] slots = new SlotSnap[SLOTS];
		List<Lot> openLots = new ArrayList<>();
		List<Flip> flips = new ArrayList<>();           // oldest first
		List<Fill> pendingFills = new ArrayList<>();    // awaiting server sync
		long allProfit;
		long allTax;
		int allFlips;
		int allWins;
		int checks;
		long untrackedSells;                            // sold qty with no tracked cost basis
		List<Untracked> untracked = new ArrayList<>();  // the sells behind that count, oldest first
		// Dedupe keys ("item:side:qty:gross") for the GE-history import: every
		// live fill and every import records one, so re-opening the history tab
		// can never import the same trade twice.
		List<String> fillKeys = new ArrayList<>();
		// User-deleted flips. deletedFlipIds is the local tombstone set (a sync
		// or adoption can never resurrect one); pendingDeletes are ids still
		// awaiting server acknowledgement.
		List<String> deletedFlipIds = new ArrayList<>();
		List<String> pendingDeletes = new ArrayList<>();
		long lastBackupMs;
		// When the local open-lot list last changed (multi-machine adoption
		// only replaces lots with a server copy that is strictly newer).
		long lotsMutMs;
		// The lotsMutMs the server last acknowledged; equal to lotsMutMs when
		// nothing local is unsynced.
		long lotsSyncedMutMs;
		// Slot snapshots changed since the last successful sync.
		boolean slotsDirty;
	}

	/** Immutable snapshot for the panel. */
	static class Summary
	{
		long todayProfit;
		long weekProfit;
		long allProfit;
		long allTax;
		int allFlips;
		int allWins;
		int winRatePct = -1;
		// Capital-weighted: total profit vs total gp spent across the retained
		// flip history, checks excluded. NaN until a flip with a cost exists.
		double avgRoiPct = Double.NaN;
		int checks;
		long sessionProfit;
		long sessionGpHr = Long.MIN_VALUE;   // MIN_VALUE = not enough active time yet
		List<Lot> openLots;
		List<Flip> recent;                   // newest first
		int pendingSync;
		long untrackedSells;
		List<Untracked> untracked;           // newest first
	}

	private final Gson gson;
	private final File dir;

	private long accountHash = -1;
	private Data data = new Data();

	// Session (runtime only): honest active time, not wall clock.
	private long sessionStartMs;
	private long sessionProfit;
	private long activeMs;
	private long lastEventMs;

	// Login hold: while another machine's fresher state is being fetched,
	// incoming offer events queue here instead of diffing against stale local
	// snapshots (which would re-report fills the other machine recorded).
	private boolean holdActive;
	private long holdStartedMs;
	private final List<HeldEvent> held = new ArrayList<>();
	private static final long HOLD_MAX_MS = 6000;
	private static final int HOLD_MAX_EVENTS = 64;

	FlipLogEngine(Gson gson, File runeliteDir)
	{
		this.gson = gson;
		this.dir = new File(runeliteDir, "pricecheck");
	}

	synchronized void setAccount(long hash)
	{
		if (hash == -1 || hash == accountHash)
		{
			return;
		}
		accountHash = hash;
		data = load();
		// One-time heal: older builds synced each flip once and never re-sent it,
		// so any flip that grew via a merge left a stale, smaller total on the
		// server. Re-push every flip once (the server now upserts by clientFlipId)
		// so the web portfolio and leaderboard match the local log.
		if (!data.resyncFlipsV2)
		{
			for (final Flip f : data.flips)
			{
				f.synced = false;
			}
			data.resyncFlipsV2 = true;
			save();
		}
		sessionStartMs = System.currentTimeMillis();
		sessionProfit = 0;
		activeMs = 0;
		lastEventMs = 0;
	}

	synchronized long getAccountHash()
	{
		return accountHash;
	}

	// ── login hold + multi-machine adoption ──

	synchronized void beginLoginHold()
	{
		// Re-arming (CONNECTION_LOST, then LOGGING_IN) keeps whatever is already
		// queued: those are real slot states and replay on release. Clearing
		// them here dropped fills on the floor.
		holdActive = true;
		holdStartedMs = System.currentTimeMillis();
	}

	/** Adopt the server's open lots only when they are provably newer than
	 *  ours. The stamp is the uploading client's own lotsMutMs, so it is a
	 *  client clock against a client clock. A row with no stamp yet (server
	 *  or jar from before the stamp) falls back to the row's server write
	 *  time, and then only while nothing local is unsynced: comparing the
	 *  server's clock to this machine's let a relog seconds after a fill
	 *  replace the fresh lot list with the copy uploaded just before it (a
	 *  buy's lot vanished, a sell's came back), and the next sell of that item
	 *  was logged as untracked instead of a flip. */
	private boolean adoptLots(RemoteState remote)
	{
		if (remote.lotsMutMs > 0)
		{
			return remote.lotsMutMs > data.lotsMutMs;
		}
		return remote.lotsUpdatedAt > data.lotsMutMs && data.lotsMutMs <= data.lotsSyncedMutMs;
	}

	/** Adopt whatever the server has that is fresher than us, then replay the
	 *  held events against the adopted snapshots. remote == null (fetch failed,
	 *  no key) just releases the hold. */
	synchronized void adoptRemote(RemoteState remote)
	{
		if (remote != null && accountHash != -1)
		{
			boolean changed = false;
			if (remote.slots != null)
			{
				for (final SlotExport rs : remote.slots)
				{
					if (rs == null || rs.slot < 0 || rs.slot >= SLOTS)
					{
						continue;
					}
					final SlotSnap local = data.slots[rs.slot];
					if (local == null || rs.updatedMs > local.updatedMs)
					{
						final SlotSnap s = new SlotSnap();
						s.itemId = rs.itemId;
						s.qtySold = rs.qtySold;
						s.total = rs.total;
						s.price = rs.price;
						s.spent = rs.spent;
						s.state = rs.state;
						s.placedMs = rs.placedMs;
						s.updatedMs = rs.updatedMs;
						data.slots[rs.slot] = s;
						changed = true;
					}
				}
			}
			// Lots follow the same rule: only a strictly-newer server copy wins,
			// so unsynced local mutations are never thrown away.
			if (remote.lots != null && adoptLots(remote))
			{
				data.openLots = new ArrayList<>(remote.lots);
				data.lotsMutMs = remote.lotsMutMs > 0 ? remote.lotsMutMs : remote.lotsUpdatedAt;
				data.lotsSyncedMutMs = data.lotsMutMs;
				changed = true;
			}
			// Deletes made on the web or another machine reach this one here.
			if (remote.deletions != null)
			{
				for (final String id : remote.deletions)
				{
					if (id != null && !data.deletedFlipIds.contains(id) && removeFlip(id, false))
					{
						changed = true;
					}
				}
			}
			if (changed)
			{
				save();
			}
		}
		releaseHold();
	}

	// ── deletion (import mistakes, or the user just wants a trade gone) ──

	/** Delete one flip everywhere: out of the list and totals, tombstoned so no
	 *  sync or adoption resurrects it, queued for server deletion. The fills
	 *  behind it stay in fillKeys, so a GE-history import won't re-offer the
	 *  same trade. Consumed lots are NOT restored (delete, not undo). */
	synchronized boolean deleteFlip(String id)
	{
		if (id == null || !removeFlip(id, true))
		{
			return false;
		}
		save();
		return true;
	}

	private boolean removeFlip(String id, boolean tellServer)
	{
		final Iterator<Flip> it = data.flips.iterator();
		while (it.hasNext())
		{
			final Flip f = it.next();
			if (!id.equals(f.id))
			{
				continue;
			}
			it.remove();
			data.allProfit -= f.profit;
			data.allTax -= f.tax;
			if (f.check)
			{
				data.checks--;
			}
			else
			{
				data.allFlips--;
				if (f.profit > 0)
				{
					data.allWins--;
				}
			}
			tombstone(data.deletedFlipIds, id);
			if (tellServer)
			{
				tombstone(data.pendingDeletes, id);
			}
			return true;
		}
		// Not held locally (evicted long ago): still tombstone, so a stale
		// machine can't push it back after the server forgot it.
		tombstone(data.deletedFlipIds, id);
		return false;
	}

	private static void tombstone(List<String> list, String id)
	{
		if (!list.contains(id))
		{
			list.add(id);
			while (list.size() > 500)
			{
				list.remove(0);
			}
		}
	}

	/** Remove one open position by exact identity. Sells of that item later
	 *  become untracked instead of matching a lot the user disowned. */
	synchronized boolean deleteLot(int itemId, int qty, long cost, long openedAt)
	{
		final Iterator<Lot> it = data.openLots.iterator();
		while (it.hasNext())
		{
			final Lot l = it.next();
			if (l.itemId == itemId && l.qty == qty && l.cost == cost && l.openedAt == openedAt)
			{
				it.remove();
				data.lotsMutMs = System.currentTimeMillis();
				data.slotsDirty = true;   // force a push so the server copy updates too
				save();
				return true;
			}
		}
		return false;
	}

	// ── name healing ──
	// Names can be missing on old records (a serialization gap in early builds
	// nulled them on multi-machine adoption). The plugin resolves ids on the
	// client thread and hands the answers back here.

	synchronized java.util.Set<Integer> idsMissingNames()
	{
		final java.util.Set<Integer> out = new java.util.HashSet<>();
		for (final Lot l : data.openLots)
		{
			if (l.name == null || l.name.isEmpty())
			{
				out.add(l.itemId);
			}
		}
		for (final Flip f : data.flips)
		{
			if (f.name == null || f.name.isEmpty())
			{
				out.add(f.itemId);
			}
		}
		return out;
	}

	synchronized void applyNames(java.util.Map<Integer, String> names)
	{
		if (names == null || names.isEmpty())
		{
			return;
		}
		boolean changed = false;
		for (final Lot l : data.openLots)
		{
			final String n = names.get(l.itemId);
			if ((l.name == null || l.name.isEmpty()) && n != null)
			{
				l.name = n;
				changed = true;
			}
		}
		for (final Flip f : data.flips)
		{
			final String n = names.get(f.itemId);
			if ((f.name == null || f.name.isEmpty()) && n != null)
			{
				f.name = n;
				changed = true;
			}
		}
		if (changed)
		{
			// Healed lots must win the next adoption and reach the server.
			data.lotsMutMs = System.currentTimeMillis();
			data.slotsDirty = true;
			save();
		}
	}

	synchronized void releaseHold()
	{
		if (!holdActive)
		{
			return;
		}
		holdActive = false;
		final List<HeldEvent> q = new ArrayList<>(held);
		held.clear();
		for (final HeldEvent h : q)
		{
			process(h.slot, h.itemId, h.qtySold, h.total, h.price, h.spent, h.st, h.loggedIn, h.tick, h.lastLoginTick, h.name);
		}
	}

	// ── event intake (client thread) ──

	synchronized void onOffer(int slot, GrandExchangeOffer o, GameState gameState, int tick, int lastLoginTick, String itemName)
	{
		if (accountHash == -1 || slot < 0 || slot >= SLOTS || o == null)
		{
			return;
		}
		if (holdActive)
		{
			// Safety valves: a hung fetch must never dam events forever, and a
			// busy login must never overflow the queue and lose a fill. Either
			// way the queue replays now and this event goes straight through.
			if (System.currentTimeMillis() - holdStartedMs > HOLD_MAX_MS || held.size() >= HOLD_MAX_EVENTS)
			{
				releaseHold();
			}
			else
			{
				final HeldEvent h = new HeldEvent();
				h.slot = slot;
				h.itemId = o.getItemId();
				h.qtySold = o.getQuantitySold();
				h.total = o.getTotalQuantity();
				h.price = o.getPrice();
				h.spent = o.getSpent();
				h.st = o.getState();
				h.loggedIn = gameState == GameState.LOGGED_IN;
				h.tick = tick;
				h.lastLoginTick = lastLoginTick;
				h.name = itemName;
				held.add(h);
				return;
			}
		}
		process(slot, o.getItemId(), o.getQuantitySold(), o.getTotalQuantity(), o.getPrice(), o.getSpent(),
			o.getState(), gameState == GameState.LOGGED_IN, tick, lastLoginTick, itemName);
	}

	private void process(int slot, int itemId, int qtySold, int totalQty, long price, long spent,
		GrandExchangeOfferState st, boolean loggedIn, int tick, int lastLoginTick, String itemName)
	{
		if (st == GrandExchangeOfferState.EMPTY)
		{
			// Real collection only while logged in; the client blanks all slots
			// during login/hopping and honoring those would wipe good snapshots.
			if (loggedIn && data.slots[slot] != null)
			{
				data.slots[slot] = null;
				data.slotsDirty = true;
				save();
			}
			return;
		}

		final boolean isBuy = st == GrandExchangeOfferState.BUYING || st == GrandExchangeOfferState.BOUGHT
			|| st == GrandExchangeOfferState.CANCELLED_BUY;
		SlotSnap snap = data.slots[slot];
		final long now = System.currentTimeMillis();

		// New offer placement: remember when, for margin-check detection.
		if (qtySold == 0)
		{
			// The client replays every live offer on login and after a hop, and
			// a replay looks exactly like a placement. Keep the placement time
			// already on record for the same offer, and never invent one inside
			// the login burst: a qty-1 sale that completed a couple of seconds
			// after a hop was being tagged as a margin check and kept out of
			// the totals.
			final boolean sameOffer = snap != null && snap.itemId == itemId && snap.price == price && snap.total == totalQty;
			final long placed = sameOffer ? snap.placedMs : (tick <= lastLoginTick + LOGIN_BURST_TICKS ? 0 : now);
			snap = new SlotSnap();
			snap.itemId = itemId;
			snap.qtySold = 0;
			snap.total = totalQty;
			snap.price = price;
			snap.spent = 0;
			snap.state = st.name();
			snap.placedMs = placed;
			snap.updatedMs = now;
			data.slots[slot] = snap;
			data.slotsDirty = true;
			save();
			return;
		}

		// Desync: the slot was changed from another client: resync, no delta.
		if (snap != null && (snap.itemId != itemId || snap.price != price || snap.total != totalQty))
		{
			snap = null;
		}

		// Duplicate event (RuneLite fires most events twice) or the redundant
		// full-quantity BUYING/SELLING that precedes BOUGHT/SOLD: no new fill.
		final int prevQty = snap == null ? 0 : snap.qtySold;
		final long prevSpent = snap == null ? 0 : snap.spent;
		final int dqty = qtySold - prevQty;
		final long dspent = spent - prevSpent;

		if (snap == null)
		{
			// First sight mid-trade (placed on another machine or before install):
			// treat the whole progress as one aggregate fill.
			snap = new SlotSnap();
			snap.itemId = itemId;
			snap.total = totalQty;
			snap.price = price;
			snap.placedMs = 0;   // never margin-check an unseen placement
			data.slots[slot] = snap;
		}

		if (dqty > 0 && dspent >= 0)
		{
			final Fill f = new Fill();
			f.id = accountHash + ":" + slot + ":" + now + ":" + qtySold;
			f.itemId = itemId;
			f.buy = isBuy;
			f.qty = dqty;
			f.gross = dspent;
			f.tax = isBuy ? 0 : fillTax(dspent, dqty);
			f.ts = now;
			f.agg = tick <= lastLoginTick + LOGIN_BURST_TICKS;
			// The completing fill usually arrives on the redundant full-quantity
			// BUYING/SELLING event, so key on completion, not terminal state.
			f.check = qtySold == totalQty && totalQty == 1
				&& snap.placedMs > 0 && now - snap.placedMs >= 0 && now - snap.placedMs <= MARGIN_CHECK_MS
				&& !f.agg;
			f.name = itemName;
			f.resting = snap.placedMs > 0 ? (now - snap.placedMs > 30_000 ? 1 : 0) : -1;
			ingest(f);
		}

		snap.qtySold = qtySold;
		snap.spent = spent;
		snap.state = st.name();
		snap.updatedMs = now;
		data.slotsDirty = true;
		save();
	}

	// Tax the way the game does per item (2% floored, 5m cap), applied to the
	// exact average price of THIS fill; within qty gp of the true charge.
	private static long fillTax(long gross, int qty)
	{
		if (qty <= 0)
		{
			return 0;
		}
		return GeTax.tax(gross / qty) * qty;
	}

	// Live fill events, in memory only: {itemId, unit price, ts ms, buy 1/0,
	// resting 1/0/-1}. The card's tape matches wiki prints against THESE,
	// because lot and flip aggregates anchor to their first fill and a
	// progressing offer's later fills drift out of any window anchored there.
	private final java.util.ArrayDeque<long[]> fillEvents = new java.util.ArrayDeque<>();

	synchronized List<long[]> recentFillEvents()
	{
		return new ArrayList<>(fillEvents);
	}

	private void ingest(Fill f)
	{
		if (f.qty > 0)
		{
			fillEvents.addLast(new long[]{f.itemId, f.gross / f.qty, f.ts, f.buy ? 1 : 0, f.resting});
			while (fillEvents.size() > 48)
			{
				fillEvents.removeFirst();
			}
		}
		final long now = f.ts;
		// Login aggregates are real coins but not live activity: keep them out
		// of the session clock and session profit so gp/hr stays honest.
		if (!f.agg)
		{
			if (lastEventMs > 0)
			{
				activeMs += Math.min(now - lastEventMs, ACTIVE_WINDOW_MS);
			}
			lastEventMs = now;
		}

		data.pendingFills.add(f);
		while (data.pendingFills.size() > MAX_PENDING_FILLS)
		{
			data.pendingFills.remove(0);
		}
		// Remember the tuple so a GE-history import can tell this trade is
		// already logged.
		data.fillKeys.add(f.itemId + ":" + (f.buy ? "b" : "s") + ":" + f.qty + ":" + f.gross);
		while (data.fillKeys.size() > 800)
		{
			data.fillKeys.remove(0);
		}

		if (f.buy)
		{
			// Merge consecutive fills of the same item at the same unit price into
			// ONE open position. A buy that fills a nibble at a time was minting a
			// new lot per nibble (dozens of "open positions" for a single offer);
			// now it grows one lot instead. Each fill is still recorded the moment
			// it lands, so a crash loses nothing, and the earliest openedAt is kept
			// so the held time stays true. Match on item + exact unit price, which
			// is fixed for the life of one offer.
			final long unit = f.gross / f.qty;
			Lot merge = null;
			for (int i = data.openLots.size() - 1; i >= 0; i--)
			{
				final Lot l = data.openLots.get(i);
				if (l.itemId == f.itemId && l.qty > 0 && l.cost / l.qty == unit)
				{
					merge = l;
					break;
				}
			}
			if (merge != null)
			{
				merge.qty += f.qty;
				merge.cost += f.gross;
				merge.name = merge.name != null ? merge.name : f.name;
				merge.check = false;   // a multi-fill lot is not a clean 1-item margin check
			}
			else
			{
				final Lot lot = new Lot();
				lot.itemId = f.itemId;
				lot.name = f.name;
				lot.qty = f.qty;
				lot.cost = f.gross;
				lot.openedAt = f.ts;
				lot.check = f.check;
				data.openLots.add(lot);
				while (data.openLots.size() > MAX_OPEN_LOTS)
				{
					data.openLots.remove(0);
				}
			}
			data.lotsMutMs = now;
			return;
		}

		// Sell: consume lots FIFO with proportional cost. Totals are conserved:
		// each consumed share is subtracted from the lot, so rounding never
		// creates or destroys gp.
		final boolean liveFill = !f.agg;
		int remaining = f.qty;
		long buyShare = 0;
		long openedAt = Long.MAX_VALUE;
		boolean checkLot = false;
		String name = f.name;
		final Iterator<Lot> it = data.openLots.iterator();
		while (it.hasNext() && remaining > 0)
		{
			final Lot lot = it.next();
			if (lot.itemId != f.itemId)
			{
				continue;
			}
			final int take = Math.min(lot.qty, remaining);
			final long share = lot.qty == take ? lot.cost : lot.cost * take / lot.qty;
			lot.cost -= share;
			lot.qty -= take;
			buyShare += share;
			openedAt = Math.min(openedAt, lot.openedAt);
			checkLot |= lot.check;
			if (name == null)
			{
				name = lot.name;
			}
			if (lot.qty == 0)
			{
				it.remove();
			}
			remaining -= take;
		}
		final int matched = f.qty - remaining;
		data.lotsMutMs = now;
		// Proportional slice of the sell for the matched quantity.
		final long sellGross = matched <= 0 ? 0 : (matched == f.qty ? f.gross : f.gross * matched / f.qty);
		final long tax = matched <= 0 ? 0 : (matched == f.qty ? f.tax : f.tax * matched / f.qty);
		if (remaining > 0)
		{
			data.untrackedSells += remaining;
			// Keep the sale itself on the log. Whatever lost the buy (a lot removed
			// by hand, a position opened before the plugin, a handoff that went
			// wrong), the coins were real and the user must be able to see them.
			final Untracked u = new Untracked();
			u.itemId = f.itemId;
			u.name = name;
			u.qty = remaining;
			u.gross = f.gross - sellGross;
			u.tax = f.tax - tax;
			u.ts = f.ts;
			data.untracked.add(u);
			while (data.untracked.size() > MAX_UNTRACKED)
			{
				data.untracked.remove(0);
			}
		}
		if (matched <= 0)
		{
			return;
		}
		final long profit = sellGross - tax - buyShare;
		// A margin check needs BOTH probes fast and close together; a real
		// position that merely closed on an instant sell is a flip.
		final boolean isCheck = f.check && checkLot && openedAt != Long.MAX_VALUE && f.ts - openedAt <= CHECK_PAIR_MS;

		// Fold a nibbling sell offer into ONE flip: if the newest flip is the same
		// item, closed moments ago, at the same sell unit price and on the same
		// side of profit, grow it rather than add a new +Xk row per unit. That flip
		// was already counted, so only the running gp totals move here; no total
		// changes, the log just stops spamming one line per fill.
		final Flip prev = data.flips.isEmpty() ? null : data.flips.get(data.flips.size() - 1);
		final boolean mergeInto = prev != null && prev.itemId == f.itemId && prev.qty > 0
			&& !prev.check && !isCheck
			&& f.ts - prev.closedAt <= FLIP_MERGE_MS
			&& prev.sellGross / prev.qty == sellGross / matched
			&& (prev.profit > 0) == (profit > 0);
		if (mergeInto)
		{
			prev.qty += matched;
			prev.buyGross += buyShare;
			prev.sellGross += sellGross;
			prev.tax += tax;
			prev.profit += profit;
			prev.closedAt = f.ts;
			// The flip grew after its last sync. Mark it unsynced so syncBatch
			// re-sends it: the server upserts by (userId, clientFlipId), so the
			// merged totals replace the stale pre-merge row instead of being
			// dropped. Without this the web portfolio/leaderboard undercount.
			prev.synced = false;
			final long op = openedAt == Long.MAX_VALUE ? f.ts : openedAt;
			if (op < prev.openedAt)
			{
				prev.openedAt = op;
			}
			data.allProfit += profit;
			data.allTax += tax;
			if (liveFill)
			{
				sessionProfit += profit;
			}
			return;
		}

		final Flip flip = new Flip();
		flip.id = f.id + ":fl";
		flip.itemId = f.itemId;
		flip.name = name;
		flip.qty = matched;
		flip.buyGross = buyShare;
		flip.sellGross = sellGross;
		flip.tax = tax;
		flip.profit = profit;
		flip.openedAt = openedAt == Long.MAX_VALUE ? f.ts : openedAt;
		flip.closedAt = f.ts;
		flip.check = isCheck;
		data.flips.add(flip);
		while (data.flips.size() > MAX_FLIPS_KEPT)
		{
			data.flips.remove(0);
		}

		data.allProfit += flip.profit;
		data.allTax += flip.tax;
		if (flip.check)
		{
			data.checks++;
		}
		else
		{
			data.allFlips++;
			if (flip.profit > 0)
			{
				data.allWins++;
			}
		}
		if (liveFill)
		{
			sessionProfit += flip.profit;
		}
	}

	// ── panel snapshot ──

	synchronized Summary summary()
	{
		final Summary s = new Summary();
		final long now = System.currentTimeMillis();
		long dayStart = now - (now % 86_400_000L);
		long weekStart = now - 7 * 86_400_000L;
		for (int i = data.flips.size() - 1; i >= 0; i--)
		{
			final Flip f = data.flips.get(i);
			if (f.closedAt >= weekStart)
			{
				s.weekProfit += f.profit;
				if (f.closedAt >= dayStart)
				{
					s.todayProfit += f.profit;
				}
			}
			else
			{
				break;   // flips are time-ordered
			}
		}
		s.allProfit = data.allProfit;
		s.allTax = data.allTax;
		s.allFlips = data.allFlips;
		s.allWins = data.allWins;
		s.checks = data.checks;
		s.untrackedSells = data.untrackedSells;
		if (data.allFlips > 0)
		{
			s.winRatePct = Math.round(100f * data.allWins / data.allFlips);
		}
		long roiNum = 0;
		long roiDen = 0;
		for (final Flip f : data.flips)
		{
			if (!f.check && f.buyGross > 0)
			{
				roiNum += f.profit;
				roiDen += f.buyGross;
			}
		}
		if (roiDen > 0)
		{
			s.avgRoiPct = 100.0 * roiNum / roiDen;
		}
		s.sessionProfit = sessionProfit;
		final long active = activeMs + (lastEventMs > 0 ? Math.min(now - lastEventMs, ACTIVE_WINDOW_MS) : 0);
		if (active >= 5 * 60_000L)
		{
			s.sessionGpHr = sessionProfit * 3_600_000L / active;
		}
		s.openLots = copyLots(data.openLots);
		final int n = data.flips.size();
		s.recent = new ArrayList<>();
		for (int i = n - 1; i >= 0 && s.recent.size() < 50; i--)
		{
			s.recent.add(data.flips.get(i));
		}
		s.pendingSync = data.pendingFills.size();
		s.untracked = new ArrayList<>();
		for (int i = data.untracked.size() - 1; i >= 0 && s.untracked.size() < 20; i--)
		{
			s.untracked.add(data.untracked.get(i));
		}
		return s;
	}

	// ── sync drain (poller thread) ──

	static class SyncBatch
	{
		long accountHash;
		List<Fill> fills;
		List<Flip> flips;
		List<Lot> lots;
		List<SlotExport> slots;
		List<String> deletes;
		long lotsMutMs;   // stamp of the lots in this batch (this client's clock)
	}

	synchronized SyncBatch syncBatch()
	{
		if (accountHash == -1)
		{
			return null;
		}
		final List<Fill> fills = new ArrayList<>();
		for (int i = 0; i < data.pendingFills.size() && fills.size() < 120; i++)
		{
			fills.add(data.pendingFills.get(i));
		}
		final List<Flip> flips = new ArrayList<>();
		for (int i = data.flips.size() - 1; i >= 0 && flips.size() < 60; i--)
		{
			final Flip f = data.flips.get(i);
			if (!f.synced)
			{
				flips.add(f);
			}
		}
		// Slot state syncs even with nothing else pending: placements and
		// collections must reach the server for the next machine's handoff.
		if (fills.isEmpty() && flips.isEmpty() && !data.slotsDirty && data.pendingDeletes.isEmpty())
		{
			return null;
		}
		final SyncBatch b = new SyncBatch();
		b.accountHash = accountHash;
		b.fills = fills;
		b.flips = flips;
		b.deletes = new ArrayList<>(data.pendingDeletes);
		b.lots = copyLots(data.openLots);
		b.lotsMutMs = data.lotsMutMs;
		b.slots = new ArrayList<>();
		for (int i = 0; i < SLOTS; i++)
		{
			final SlotSnap s = data.slots[i];
			if (s == null)
			{
				continue;
			}
			final SlotExport e = new SlotExport();
			e.slot = i;
			e.itemId = s.itemId;
			e.qtySold = s.qtySold;
			e.total = s.total;
			e.price = s.price;
			e.spent = s.spent;
			e.state = s.state;
			e.placedMs = s.placedMs;
			e.updatedMs = s.updatedMs;
			b.slots.add(e);
		}
		return b;
	}

	// Lots are mutated in place as sells consume them; hand out value copies so
	// the panel and the sync serializer never observe a torn qty/cost pair.
	private static List<Lot> copyLots(List<Lot> src)
	{
		final List<Lot> out = new ArrayList<>(src.size());
		for (final Lot l : src)
		{
			final Lot c = new Lot();
			c.itemId = l.itemId;
			c.name = l.name;
			c.qty = l.qty;
			c.cost = l.cost;
			c.openedAt = l.openedAt;
			c.check = l.check;
			out.add(c);
		}
		return out;
	}

	synchronized void onSyncSuccess(SyncBatch b)
	{
		if (b == null)
		{
			return;
		}
		for (final Fill f : b.fills)
		{
			data.pendingFills.remove(f);
		}
		for (final Flip f : b.flips)
		{
			f.synced = true;
		}
		if (b.deletes != null)
		{
			data.pendingDeletes.removeAll(b.deletes);
		}
		if (b.lotsMutMs > data.lotsSyncedMutMs)
		{
			data.lotsSyncedMutMs = b.lotsMutMs;
		}
		data.slotsDirty = false;
		save();
	}

	// ── persistence: atomic write on every mutation ──

	private File fileFor(long hash)
	{
		return new File(dir, "flips-" + hash + ".json");
	}

	private Data load()
	{
		Data d = read(fileFor(accountHash));
		if (d == null)
		{
			// Main file unreadable: quarantine it and fall back to the daily
			// backup before ever starting fresh.
			try
			{
				Files.move(fileFor(accountHash).toPath(), new File(dir, "flips-" + accountHash + ".bad.json").toPath(),
					StandardCopyOption.REPLACE_EXISTING);
			}
			catch (IOException ignored)
			{
			}
			d = read(backupFor(accountHash));
			if (d != null)
			{
				log.warn("flip log restored from daily backup");
			}
		}
		return d != null ? d : new Data();
	}

	private Data read(File f)
	{
		try
		{
			if (!f.exists())
			{
				return null;
			}
			final Data d = gson.fromJson(new String(Files.readAllBytes(f.toPath()), StandardCharsets.UTF_8), Data.class);
			if (d == null)
			{
				return null;
			}
			if (d.slots == null || d.slots.length != SLOTS)
			{
				d.slots = new SlotSnap[SLOTS];
			}
			if (d.openLots == null)
			{
				d.openLots = new ArrayList<>();
			}
			if (d.flips == null)
			{
				d.flips = new ArrayList<>();
			}
			if (d.pendingFills == null)
			{
				d.pendingFills = new ArrayList<>();
			}
			if (d.fillKeys == null)
			{
				d.fillKeys = new ArrayList<>();
			}
			if (d.deletedFlipIds == null)
			{
				d.deletedFlipIds = new ArrayList<>();
			}
			if (d.pendingDeletes == null)
			{
				d.pendingDeletes = new ArrayList<>();
			}
			if (d.untracked == null)
			{
				d.untracked = new ArrayList<>();
			}
			return d;
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("flip log read failed: {}", f.getName(), e);
			return null;
		}
	}

	private File backupFor(long hash)
	{
		return new File(dir, "flips-" + hash + ".bak.json");
	}

	private void save()
	{
		try
		{
			if (!dir.exists() && !dir.mkdirs())
			{
				return;
			}
			final byte[] json = gson.toJson(data).getBytes(StandardCharsets.UTF_8);
			final Path tmp = new File(dir, "flips-" + accountHash + ".tmp").toPath();
			Files.write(tmp, json);
			Files.move(tmp, fileFor(accountHash).toPath(), StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
			// Rolling daily backup: a logic bug that corrupts state can only
			// cost a day, not the ledger.
			final long now = System.currentTimeMillis();
			if (now - data.lastBackupMs > 86_400_000L)
			{
				data.lastBackupMs = now;
				Files.write(backupFor(accountHash).toPath(), json);
			}
		}
		catch (IOException | RuntimeException e)
		{
			log.warn("flip log save failed", e);
		}
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.KeyCode;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The active-offers board, docked to the right of the open Grand Exchange grid.
 * One two-line block per relevant offer: a B/S chip, the item, the live verdict,
 * then your price, how close it sits to a real fill, the last trade on your side,
 * and the coarse pressure lean. Overview only; the mini-cards own the slot and
 * set-up screens. Painted by hand like the advisor box so it matches the
 * plugin's look, and the painter is a static function over plain rows so the
 * headless preview can render it without a Client.
 *
 * Visibility is decided by one order-independent predicate on the plugin
 * (geOffersPanelVisible): the mini-cards read the same predicate to yield the
 * right column, so the two never fight over the same dock.
 */
class GeOffersPanelOverlay extends Overlay
{
	static final int W = 250;
	private static final int PAD = 9;
	private static final Color BAR_TRACK = new Color(0xff, 0xff, 0xff, 24);

	private static final Color FRAME = new Color(0xe6, 0xc6, 0x67, 62);
	private static final Color RULE = new Color(0xe6, 0xc6, 0x67, 38);
	private static final Color NAME = new Color(0xde, 0xd8, 0xc8);
	private static final Color SHADOW = new Color(0, 0, 0, 180);
	private static final Color CHIP_BUY = new Color(0x49, 0xc9, 0x7f);
	private static final Color CHIP_SELL = new Color(0xd9, 0x5c, 0x5e);
	private static final Color CHIP_INK = new Color(0x9a, 0x91, 0x7c);
	private static final Color CHIP_TEXT = new Color(0x12, 0x0e, 0x08);

	private static final int BTN = 14;
	private static final String COLLAPSED_KEY = "offersPanelCollapsed";

	private final Client client;
	private final PriceCheckPlugin plugin;
	private final ConfigManager configManager;

	// Written on the mouse thread, read on the render thread (same as the advisor
	// box). collapsed persists across sessions; toggleBounds is the canvas-space
	// hit box for the [-]/[+] button, valid only while Shift shows it.
	private volatile boolean collapsed;
	private volatile Rectangle toggleBounds;

	GeOffersPanelOverlay(Client client, PriceCheckPlugin plugin, ConfigManager configManager)
	{
		super(plugin);
		this.client = client;
		this.plugin = plugin;
		this.configManager = configManager;
		this.collapsed = Boolean.parseBoolean(configManager.getConfiguration(PriceCheckConfig.GROUP, COLLAPSED_KEY));
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Mouse hook from the plugin: collapse/expand when the Shift-only button is
	 *  clicked. Mirrors OfferAdvisorOverlay.handleClick. */
	boolean handleClick(Point p, boolean shiftHeld)
	{
		final Rectangle t = toggleBounds;
		if (!shiftHeld || t == null || p == null || !t.contains(p))
		{
			return false;
		}
		collapsed = !collapsed;
		configManager.setConfiguration(PriceCheckConfig.GROUP, COLLAPSED_KEY, collapsed);
		return true;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		toggleBounds = null;
		plugin.noteBlotterBottom(-1);
		if (!plugin.geOffersPanelEnabled())
		{
			return null;
		}
		// During offer set-up the terminal ORDER ticket owns the right dock.
		if (plugin.terminalDesk() && plugin.setupScreenOpen())
		{
			return null;
		}
		final List<Row> rows = buildRows();
		if (rows.isEmpty())
		{
			return null;
		}
		// Overnight overlay mode draws the board larger; the dock reserves the
		// scaled width so it still never overlaps the GE.
		final double scale = plugin.overlayScale();
		final boolean term = plugin.terminalOffers();
		final int effW = (int) Math.round((term ? TERM_W : W) * scale);
		final int y = 8;
		final int x;
		if (plugin.isGrandExchangeOpen())
		{
			// GE open (overview OR a slot/offer-status screen): dock to the right
			// of the GE window so the board never vanishes when you open a slot.
			// On the overview the mini-cards yield this column via
			// geOffersPanelVisible; the single item card anchors left, so no
			// overlap on a slot screen either.
			final Rectangle b = plugin.geGridBounds();
			if (b == null)
			{
				return null;
			}
			x = b.x + b.width + 8;
			if (x + effW > client.getCanvasWidth() - 4)
			{
				return null;   // no room to the right; never overlap the GE
			}
		}
		else
		{
			// GE closed: float in the top-right so the board stays up like the
			// advisor box does on the left.
			x = client.getCanvasWidth() - effW - 8;
			if (x < 4)
			{
				return null;
			}
		}
		final boolean shift = client.isKeyPressed(KeyCode.KC_SHIFT);
		final java.awt.geom.AffineTransform save = g.getTransform();
		g.translate(x, y);
		g.scale(scale, scale);
		final Result r = term ? paintTerminal(g, rows, collapsed, shift) : paint(g, rows, collapsed, shift);
		g.setTransform(save);
		if (r.size != null)
		{
			plugin.noteDeskRect("blotter", x, y,
				(int) Math.round(r.size.width * scale), (int) Math.round(r.size.height * scale));
		}
		if (r.button != null)
		{
			toggleBounds = new Rectangle(
				x + (int) Math.round(r.button.x * scale),
				y + (int) Math.round(r.button.y * scale),
				(int) Math.round(r.button.width * scale),
				(int) Math.round(r.button.height * scale));
		}
		// Publish the bottom edge (GE-open right dock only) so the recent-flips
		// panel stacks directly beneath the blotter instead of pinning to the floor.
		if (plugin.isGrandExchangeOpen())
		{
			plugin.noteBlotterBottom(y + (int) Math.round(r.size.height * scale));
		}
		return null;
	}

	private List<Row> buildRows()
	{
		final List<Row> rows = new ArrayList<>();
		final List<OfferAdvice> advice = plugin.getAdvice();
		final long nowSec = System.currentTimeMillis() / 1000L;
		for (int slot = 0; slot < 8; slot++)
		{
			final TrackedOffer t = plugin.trackedAt(slot);
			if (t == null || !t.isRelevant())
			{
				continue;
			}
			rows.add(buildRow(t, adviceForSlot(advice, slot), nowSec));
		}
		return rows;
	}

	private Row buildRow(TrackedOffer t, OfferAdvice a, long nowSec)
	{
		final Row r = new Row();
		final int itemId = t.getItemId();
		final FlipData live = plugin.liveFor(itemId);
		// Margin/whole-flip profit follow the selected chart timeframe; the closeness
		// edge and last-trade fallback below stay on the live quote (they answer
		// "will this fill soon", which is inherently about the live market).
		final FlipData view = plugin.viewFor(itemId);
		final boolean sell = t.getState() == GrandExchangeOfferState.SELLING
			|| t.getState() == GrandExchangeOfferState.SOLD;

		r.chip = sell ? "S" : "B";
		r.chipColor = t.isDone() ? CHIP_INK : (sell ? CHIP_SELL : CHIP_BUY);

		String name = a != null ? a.getItemName() : null;
		if (name == null || name.isEmpty() || name.startsWith("Item "))
		{
			name = live != null && live.getName() != null ? live.getName() : "#" + itemId;
		}
		r.name = name;

		if (a != null && a.getKind() != OfferAdvice.Kind.NO_DATA && a.getShortText() != null && !a.getShortText().isEmpty())
		{
			r.verdict = I18n.verdict(a.getShortText());
			r.verdictColor = a.getColor();
		}
		else
		{
			r.verdict = "";
			r.verdictColor = Palette.SUBTLE_CANVAS;
		}

		r.price = t.getPrice();
		r.liveMargin = view != null ? view.getProfit() : 0;
		r.totalQty = Math.max(0, t.getTotalQty());
		r.soldQty = Math.max(0, Math.min(r.totalQty, t.getSoldQty()));
		r.unfilledQty = t.isActive() ? Math.max(0, r.totalQty - r.soldQty) : 0;
		r.posProfit = r.liveMargin * r.totalQty;

		final PriceCheckApiClient.SeriesData sd = plugin.cardSeriesFor(itemId);
		final long[] cl = closeness(t, sd, live);
		r.closenessGp = cl[0];
		r.seated = cl[1] == 1;
		r.trend = gapTrend(sell, sd);

		r.lastTrade = lastTrade(itemId, sell, live, nowSec);

		r.pressure = pressureLean(sd, nowSec);
		if ("sell".equals(r.pressure))
		{
			r.pressureColor = Palette.RED;
		}
		else if ("buy".equals(r.pressure))
		{
			r.pressureColor = Palette.GREEN;
		}
		else
		{
			r.pressureColor = Palette.SUBTLE_CANVAS;
		}
		return r;
	}

	private static OfferAdvice adviceForSlot(List<OfferAdvice> advice, int slot)
	{
		for (final OfferAdvice a : advice)
		{
			if (a.getSlot() == slot)
			{
				return a;
			}
		}
		return null;
	}

	/** Last trade on the side that would fill this offer, "@price age"; falls
	 *  back to the live edge quote (no age) when no matching print is on tape. */
	private String lastTrade(int itemId, boolean sell, FlipData live, long nowSec)
	{
		final List<GeItemInfoPainter.Print> prints = plugin.cardPrintsFor(itemId);
		for (int i = prints.size() - 1; i >= 0; i--)
		{
			final GeItemInfoPainter.Print p = prints.get(i);
			// A SELL fills as buyers print UP (buySide=true); a BUY fills as
			// sellers print DOWN (buySide=false).
			if (p.price > 0 && p.buySide == sell)
			{
				return "@" + Fmt.compact(p.price) + " " + ageShort(Math.max(0, nowSec - p.ts));
			}
		}
		final long edge = sell
			? (live != null ? live.getSell() : 0)
			: (live != null ? live.getBuy() : 0);
		return edge > 0 ? "@" + Fmt.compact(edge) : null;
	}

	/** {gpGap, seated 1/0}; gpGap -1 unknown, 0 seated, else the exact gp your
	 *  price sits from the fill edge. Edge is the LIVE quote when present
	 *  (consistent with liveMargin), the series only as a fallback. */
	private static long[] closeness(TrackedOffer o, PriceCheckApiClient.SeriesData s, FlipData live)
	{
		final long price = o.getPrice();
		if (price <= 0)
		{
			return new long[]{-1, 0};
		}
		final boolean sell = o.getState() == GrandExchangeOfferState.SELLING
			|| o.getState() == GrandExchangeOfferState.SOLD;
		final long edge = sell
			? (live != null && live.getSell() > 0 ? live.getSell() : lastNonZero(s == null ? null : s.ah))
			: (live != null && live.getBuy() > 0 ? live.getBuy() : lastNonZero(s == null ? null : s.al));
		if (edge <= 0)
		{
			return new long[]{-1, 0};
		}
		final boolean seated = sell ? price <= edge : price >= edge;
		if (seated)
		{
			return new long[]{0, 1};   // at/through the fill edge: fills now
		}
		// The exact gp to a real fill - how far to move to head the queue. The
		// colour carries near/far so the raw gp still reads as close or distant.
		final long dist = sell ? (price - edge) : (edge - price);
		return new long[]{Math.max(1, dist), 0};
	}

	/** Is the fill-side market price moving TOWARD our resting offer (so a fill
	 *  is coming) or away from it? +1 closing, -1 drifting, 0 flat/unknown. A
	 *  SELL fills as the insta-buy (high) rises to our ask; a BUY fills as the
	 *  insta-sell (low) falls to our bid. Compares the newest real print on that
	 *  side to one roughly half an hour earlier. */
	private static int gapTrend(boolean sell, PriceCheckApiClient.SeriesData s)
	{
		if (s == null || s.ts == null)
		{
			return 0;
		}
		final long[] side = sell ? s.ah : s.al;
		final int[] vol = sell ? s.hv : s.lv;
		if (side == null)
		{
			return 0;
		}
		long now = 0;
		long prev = 0;
		int seen = 0;
		for (int i = side.length - 1; i >= 0 && seen < 8; i--)
		{
			if (side[i] > 0 && (vol == null || i >= vol.length || vol[i] > 0))
			{
				if (now == 0)
				{
					now = side[i];
				}
				prev = side[i];
				seen++;
			}
		}
		if (now <= 0 || prev <= 0 || seen < 3)
		{
			return 0;
		}
		if (Math.abs(now - prev) * 1000 < now)
		{
			return 0;   // under ~0.1% of drift either way reads as flat
		}
		final boolean closing = sell ? now > prev : now < prev;
		return closing ? 1 : -1;
	}

	private static long lastNonZero(long[] arr)
	{
		if (arr == null)
		{
			return 0;
		}
		for (int i = arr.length - 1; i >= 0; i--)
		{
			if (arr[i] > 0)
			{
				return arr[i];
			}
		}
		return 0;
	}

	/** Coarse trade-pressure lean over the freshest window with enough volume:
	 *  "sell" when insta-sells dominate (downward), "buy" when insta-buys do,
	 *  "flat" otherwise. Null when no window carries enough trades. A rough
	 *  reflection of GeItemInfoPainter's pressure read, never a probability. */
	private static String pressureLean(PriceCheckApiClient.SeriesData s, long nowSec)
	{
		if (s == null || s.ts == null || s.ts.length == 0)
		{
			return null;
		}
		for (final int hrs : new int[]{4, 8, 24})
		{
			final long cut = nowSec - hrs * 3600L;
			long hv = 0;
			long lv = 0;
			for (int i = s.ts.length - 1; i >= 0 && s.ts[i] >= cut; i--)
			{
				hv += s.hv != null && i < s.hv.length && s.hv[i] > 0 ? s.hv[i] : 0;
				lv += s.lv != null && i < s.lv.length && s.lv[i] > 0 ? s.lv[i] : 0;
			}
			final long total = hv + lv;
			if (total >= 12 || (hrs == 24 && total >= 6))
			{
				final long lvPct = Math.round(100.0 * lv / total);
				if (lvPct >= 58)
				{
					return "sell";
				}
				if (lvPct <= 42)
				{
					return "buy";
				}
				return "flat";
			}
		}
		return null;
	}

	private static String ageShort(long secs)
	{
		if (secs < 60)
		{
			return secs + "s";
		}
		final long m = secs / 60;
		if (m < 60)
		{
			return m + "m";
		}
		final long h = m / 60;
		if (h < 24)
		{
			return h + "h";
		}
		return (h / 24) + "d";
	}

	/** One board row: everything two lines need, all plain data. */
	static final class Row
	{
		String chip;
		Color chipColor;
		String name;
		String verdict;
		Color verdictColor;
		long price;
		long liveMargin;    // per-unit live margin, advisor's notion
		long unfilledQty;   // open units on this offer (0 when done)
		long soldQty;       // units already bought/sold on this offer
		long totalQty;      // full offer size
		long posProfit;     // whole-flip profit at the live margin (margin x totalQty)
		long closenessGp;   // exact gp the market must still move to fill us; -1 unknown, 0 seated
		int trend;          // +1 the fill edge is moving toward us (fills soon), -1 drifting away, 0 flat
		boolean seated;
		String lastTrade;   // "@price age" or "@edge", null when none
		String pressure;    // "buy" | "sell" | "flat" | null
		Color pressureColor;
	}

	// ── Terminal (trading-terminal) blotter ───────────────────────────────
	// Same rows as the classic board, re-skinned amber-on-black to sit under the
	// terminal status bar. Routed here from render() when config.terminalOffers().
	static final int TERM_W = 292;

	static Result paintTerminal(Graphics2D g, List<Row> rows, boolean collapsed, boolean shiftHeld)
	{
		TerminalKit.hints(g);
		if (collapsed)
		{
			g.setFont(TerminalKit.monoB(11));
			final String t = "POSITIONS  " + rows.size();
			final int cw = 12 + g.getFontMetrics().stringWidth(t) + (shiftHeld ? BTN + 6 : 0) + 12;
			final int h = 22;
			g.setColor(TerminalKit.PANEL); g.fillRect(0, 0, cw, h);
			g.setColor(TerminalKit.BORDER); g.drawRect(0, 0, cw, h);
			g.setColor(TerminalKit.AMBERHI); TerminalKit.str(g, t, 12, 15);
			return new Result(new Dimension(cw, h), shiftHeld ? drawToggle(g, cw, true) : null);
		}
		final int w = TERM_W;
		final int rowH = 30;
		final int headerH = 18;
		final int footerH = 18;
		final int h = headerH + rows.size() * rowH + footerH + 4;
		g.setColor(TerminalKit.PANEL); g.fillRect(0, 0, w, h);
		g.setColor(TerminalKit.BORDER); g.drawRect(0, 0, w, h);
		// header
		g.setColor(TerminalKit.TITLEBG); g.fillRect(1, 1, w - 2, 16);
		g.setFont(TerminalKit.monoB(10)); g.setColor(TerminalKit.AMBERHI);
		TerminalKit.str(g, I18n.t("POSITIONS"), 8, 12);
		g.setColor(TerminalKit.LABEL);
		TerminalKit.str(g, "· " + rows.size() + I18n.t(" OFFERS"),
			8 + TerminalKit.width(g, I18n.t("POSITIONS")) + 6, 12);
		final Rectangle btn = shiftHeld ? drawToggle(g, w, false) : null;
		g.setColor(TerminalKit.GRID); g.drawLine(1, 18, w - 1, 18);
		// rows
		int y = headerH + 4;
		int seated = 0;
		long total = 0;
		for (final Row r : rows)
		{
			if (r.seated) { seated++; }
			total += r.posProfit;
			paintTermRow(g, w, y, r);
			y += rowH;
		}
		// footer
		g.setColor(TerminalKit.TITLEBG); g.fillRect(1, h - footerH, w - 2, footerH - 1);
		g.setColor(TerminalKit.GRID); g.drawLine(1, h - footerH, w - 1, h - footerH);
		g.setFont(TerminalKit.monoB(10));
		g.setColor(rows.size() > 0 && seated == rows.size() ? TerminalKit.GREEN : TerminalKit.AMBER);
		TerminalKit.str(g, I18n.f("%d/%d SEATED", seated, rows.size()), 8, h - 5);
		g.setColor(total >= 0 ? TerminalKit.GREEN : TerminalKit.RED);
		TerminalKit.rt(g, I18n.t("NET ") + (total >= 0 ? "+" : "") + Fmt.compact(total), w - 8, h - 5);
		return new Result(new Dimension(w, h), btn);
	}

	private static void paintTermRow(Graphics2D g, int w, int top, Row r)
	{
		final int base1 = top + 11;
		final int base2 = top + 24;
		// side chip + name (line 1), verdict right-aligned
		int nameX = 8;
		if (r.chip != null && !r.chip.isEmpty())
		{
			g.setFont(TerminalKit.monoB(11));
			g.setColor(r.chipColor != null ? r.chipColor : TerminalKit.AMBER);
			g.drawString(r.chip, 8, base1);
			nameX = 8 + g.getFontMetrics().stringWidth(r.chip) + 6;
		}
		g.setFont(TerminalKit.monoB(11));
		final FontMetrics fm = g.getFontMetrics();
		int verdW = 0;
		if (r.verdict != null)
		{
			g.setColor(r.verdictColor != null ? r.verdictColor : TerminalKit.AMBER);
			verdW = TerminalKit.width(g, r.verdict);
			TerminalKit.rt(g, r.verdict, w - 8, base1);
		}
		g.setColor(TerminalKit.AMBERHI);
		g.drawString(ellipsize(r.name, fm, w - 8 - verdW - 8 - nameX), nameX, base1);
		// line 2: qty @ price | closeness/drift | uP&L
		g.setFont(TerminalKit.mono(10));
		g.setColor(TerminalKit.LABEL);
		final long q = r.totalQty > 0 ? r.totalQty : r.unfilledQty;
		g.drawString(q + " @ " + Fmt.compact(r.price), 8, base2);
		final String mid;
		final Color midC;
		if (r.seated) { mid = I18n.t("seated"); midC = TerminalKit.GREEN; }
		else if (r.closenessGp > 0)
		{
			mid = I18n.f(r.trend > 0 ? "%s closing" : r.trend < 0 ? "%s drifting" : "%s away", Fmt.compact(r.closenessGp));
			midC = r.trend > 0 ? TerminalKit.GREEN : r.trend < 0 ? TerminalKit.RED : TerminalKit.LABEL;
		}
		else { mid = ""; midC = TerminalKit.LABEL; }
		g.setColor(midC);
		TerminalKit.str(g, mid, 8 + 96, base2);
		g.setFont(TerminalKit.monoB(11));
		g.setColor(r.posProfit >= 0 ? TerminalKit.GREEN : TerminalKit.RED);
		TerminalKit.rt(g, (r.posProfit >= 0 ? "+" : "") + Fmt.compact(r.posProfit), w - 8, base2);
		g.setColor(TerminalKit.GRID);
		g.drawLine(4, top + 28, w - 4, top + 28);
	}

	/** Draws the board (or a collapsed title pill) at 0,0 and reports its size
	 *  plus the Shift-only toggle's local hit box. Pure over its inputs. */
	static Result paint(Graphics2D g, List<Row> rows, boolean collapsed, boolean shiftHeld)
	{
		final Font font = FontManager.getRunescapeSmallFont();
		g.setFont(font);
		final FontMetrics fm = g.getFontMetrics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		// The pixel font must stay crisp: no text antialiasing.
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);

		final int lineH = fm.getHeight();
		final int headerH = fm.getHeight() + 5;
		final int baseline = 3 + fm.getAscent();
		final String title = "Active offers";
		final String count = " · " + rows.size();

		if (collapsed)
		{
			// A pill hugging the title, with room for the button on Shift.
			final int w = PAD + fm.stringWidth(title + count) + (shiftHeld ? BTN + 6 : 0) + PAD;
			final int h = headerH + 3;
			g.setColor(Palette.INK);
			g.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);
			g.setColor(FRAME);
			g.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);
			shadowed(g, title, PAD, baseline, Palette.GOLD);
			shadowed(g, count, PAD + fm.stringWidth(title), baseline, Palette.SUBTLE_CANVAS);
			return new Result(new Dimension(w, h), shiftHeld ? drawToggle(g, w, true) : null);
		}

		final int rowH = 2 * lineH + 8;   // two text lines + a hairline fill bar
		final int footerH = lineH + 6;
		final int w = W;
		final int h = headerH + 4 + rows.size() * rowH + 5 + footerH + PAD - 4;

		g.setColor(Palette.INK);
		g.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);
		g.setColor(FRAME);
		g.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);

		shadowed(g, title, PAD, baseline, Palette.GOLD);
		shadowed(g, count, PAD + fm.stringWidth(title), baseline, Palette.SUBTLE_CANVAS);
		final Rectangle btn = shiftHeld ? drawToggle(g, w, false) : null;

		g.setColor(RULE);
		g.drawLine(PAD - 2, headerH, w - PAD + 2, headerH);

		int y = headerH + 4;
		int seatedCount = 0;
		long flipTotal = 0;
		for (final Row r : rows)
		{
			paintRow(g, fm, w, y, r);
			if (r.seated)
			{
				seatedCount++;
			}
			flipTotal += r.posProfit;
			y += rowH;
		}

		final int footY = y + 3;
		g.setColor(RULE);
		g.drawLine(PAD - 2, footY, w - PAD + 2, footY);
		final int fb = footY + 2 + fm.getAscent();
		final String left = seatedCount + "/" + rows.size() + " seated";
		shadowed(g, left, PAD, fb, Palette.SUBTLE_CANVAS);
		// Whole-board profit if every offer completes at the live margin.
		final String right = "all " + (flipTotal >= 0 ? "+" : "-") + Fmt.compact(Math.abs(flipTotal));
		final int rw = fm.stringWidth(right);
		shadowed(g, right, w - PAD - rw, fb, flipTotal >= 0 ? Palette.GREEN : Palette.RED);

		return new Result(new Dimension(w, h), btn);
	}

	/** The Shift-only [-]/[+] toggle at the header's top-right; returns its local
	 *  hit box. Same glyphs as the advisor box so the two read alike. */
	private static Rectangle drawToggle(Graphics2D g, int w, boolean collapsed)
	{
		final Rectangle btn = new Rectangle(w - BTN - 4, 2, BTN, BTN);
		final int cx = btn.x + BTN / 2;
		final int cy = btn.y + BTN / 2;
		g.setColor(SHADOW);
		g.drawLine(cx - 3 + 1, cy + 1, cx + 3 + 1, cy + 1);
		g.setColor(Palette.GOLD);
		g.drawLine(cx - 3, cy, cx + 3, cy);   // minus
		if (collapsed)
		{
			g.setColor(SHADOW);
			g.drawLine(cx + 1, cy - 3 + 1, cx + 1, cy + 3 + 1);
			g.setColor(Palette.GOLD);
			g.drawLine(cx, cy - 3, cx, cy + 3);   // vertical stroke turns it into a plus
		}
		return btn;
	}

	/** What one paint produced: the box size + the toggle's local hit box (null
	 *  unless Shift drew it). */
	static final class Result
	{
		final Dimension size;
		final Rectangle button;

		Result(Dimension size, Rectangle button)
		{
			this.size = size;
			this.button = button;
		}
	}

	private static void paintRow(Graphics2D g, FontMetrics fm, int w, int top, Row r)
	{
		final int lineH = fm.getHeight();
		final int base1 = top + fm.getAscent();

		// Line 1: chip pill, name, verdict on the right.
		int nameX = PAD;
		if (r.chip != null && !r.chip.isEmpty())
		{
			final int cw = fm.stringWidth(r.chip) + 8;
			g.setColor(SHADOW);
			g.fillRoundRect(PAD + 1, top + 1, cw, lineH - 1, 5, 5);
			g.setColor(r.chipColor);
			g.fillRoundRect(PAD, top, cw, lineH - 1, 5, 5);
			g.setColor(CHIP_TEXT);
			g.drawString(r.chip, PAD + 4, base1);
			nameX = PAD + cw + 5;
		}

		final String verdict = r.verdict == null ? "" : r.verdict;
		final int vw = fm.stringWidth(verdict);
		if (!verdict.isEmpty())
		{
			shadowed(g, verdict, w - PAD - vw, base1, r.verdictColor);
		}

		final int nameMax = w - PAD - (verdict.isEmpty() ? 0 : vw + 6) - nameX;
		shadowed(g, ellipsize(r.name, fm, nameMax), nameX, base1, NAME);

		// Line 2: price [x qty] | closeness | whole-flip profit | last trade |
		// lean. Floors are the price and closeness; the rest drop back-to-front
		// (lean, then last trade) so the whole-flip profit survives longest.
		final int base2 = top + lineH + fm.getAscent();
		final int maxW = w - 2 * PAD;
		final List<String> segs = new ArrayList<>();
		final List<Color> cols = new ArrayList<>();
		segs.add(Fmt.compact(r.price) + (r.totalQty > 1 ? " x" + r.totalQty : ""));
		cols.add(Palette.LIGHT);
		if (r.seated)
		{
			segs.add("at mkt");
			cols.add(Palette.GREEN);
		}
		else if (r.closenessGp > 0)
		{
			// How far the market must still move to fill us, and whether it is
			// coming (closing -> fills soon) or drifting off. The point is to
			// watch the offer fill, not to reprice it.
			final String word = r.trend > 0 ? "closing" : r.trend < 0 ? "drifting" : "away";
			segs.add(Fmt.compact(r.closenessGp) + " " + word);
			cols.add(r.trend > 0 ? Palette.GREEN : r.trend < 0 ? Palette.RED : Palette.SUBTLE_CANVAS);
		}
		final List<String> opt = new ArrayList<>();
		final List<Color> optc = new ArrayList<>();
		// Whole-flip profit (margin x full size) - the number that actually
		// matters, which the per-unit verdict never shows. Only when qty > 1
		// adds information (for a single unit it equals the verdict).
		if (r.totalQty > 1 && r.posProfit != 0)
		{
			opt.add((r.posProfit >= 0 ? "+" : "-") + Fmt.compact(Math.abs(r.posProfit)));
			optc.add(r.posProfit >= 0 ? Palette.GREEN : Palette.RED);
		}
		if (r.lastTrade != null)
		{
			opt.add(r.lastTrade);
			optc.add(Palette.SUBTLE_CANVAS);
		}
		if (r.pressure != null)
		{
			opt.add(r.pressure);
			optc.add(r.pressureColor);
		}

		final String sep = "  ";
		List<String> pick = segs;
		List<Color> pickC = cols;
		for (int take = opt.size(); take >= 0; take--)
		{
			final List<String> s = new ArrayList<>(segs);
			final List<Color> c = new ArrayList<>(cols);
			for (int i = 0; i < take; i++)
			{
				s.add(opt.get(i));
				c.add(optc.get(i));
			}
			int tot = 0;
			for (int i = 0; i < s.size(); i++)
			{
				tot += fm.stringWidth(s.get(i));
				if (i > 0)
				{
					tot += fm.stringWidth(sep);
				}
			}
			if (tot <= maxW || take == 0)
			{
				pick = s;
				pickC = c;
				break;
			}
		}
		int x = PAD;
		for (int i = 0; i < pick.size(); i++)
		{
			if (i > 0)
			{
				x += fm.stringWidth(sep);
			}
			shadowed(g, pick.get(i), x, base2, pickC.get(i));
			x += fm.stringWidth(pick.get(i));
		}

		// Hairline fill bar at the row foot: the bought/sold fraction, in the
		// offer's side colour over a dim track, so progress reads across the
		// whole board at a glance without opening each slot.
		if (r.totalQty > 1)
		{
			final int barY = top + 2 * lineH + 3;
			g.setColor(BAR_TRACK);
			g.fillRect(PAD, barY, maxW, 2);
			final int fw = (int) Math.max(0, Math.min(maxW, maxW * r.soldQty / Math.max(1, r.totalQty)));
			if (fw > 0)
			{
				g.setColor(r.chipColor);
				g.fillRect(PAD, barY, fw, 2);
			}
		}
	}

	private static void shadowed(Graphics2D g, String s, int x, int y, Color c)
	{
		final java.awt.Font sb = g.getFont();
		final java.awt.Font su = I18n.fit(sb, s);
		if (su != sb) { g.setFont(su); }
		g.setColor(SHADOW);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
		if (su != sb) { g.setFont(sb); }
	}

	private static String ellipsize(String s, FontMetrics fm, int max)
	{
		if (s == null)
		{
			return "";
		}
		if (fm.stringWidth(s) <= max)
		{
			return s;
		}
		String t = s;
		while (t.length() > 1 && fm.stringWidth(t + "..") > max)
		{
			t = t.substring(0, t.length() - 1);
		}
		return t + "..";
	}
}

package gg.pricecheck.runelite;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;

@ConfigGroup(PriceCheckConfig.GROUP)
public interface PriceCheckConfig extends Config
{
	String GROUP = "pricecheck";

	/** How often the PriceCheck Discord bot may DM you about your open offers. */
	enum AlertCadence
	{
		OFF("off"),
		INSTANT("instant"),
		EVERY_5_MIN("m5"),
		EVERY_15_MIN("m15"),
		HOURLY("hourly");

		private final String wire;
		AlertCadence(String wire) { this.wire = wire; }
		String wire() { return wire; }

		@Override
		public String toString()
		{
			switch (this)
			{
				case INSTANT: return "Instant";
				case EVERY_5_MIN: return "Every 5 min";
				case EVERY_15_MIN: return "Every 15 min";
				case HOURLY: return "Hourly digest";
				default: return "Off";
			}
		}
	}

	/** The whole GE desk in one control. AUTO measures the space around the
	 *  open Grand Exchange every frame and shows the biggest layout that fits,
	 *  so any window size gets a clean desk instead of overlapping panels. The
	 *  fixed tiers force a maximum; panels still never overlap when the window
	 *  is too small for the pick. */
	enum DeskMode
	{
		AUTO,
		FULL,
		COMPACT,
		MINIMAL,
		OFF;

		@Override
		public String toString()
		{
			switch (this)
			{
				case FULL: return "Full desk";
				case COMPACT: return "Compact (card + blotter)";
				case MINIMAL: return "Minimal (card only)";
				case OFF: return "Off";
				default: return "Auto (fit my window)";
			}
		}
	}

	/** Plugin language. English is the source text; anything without a
	 *  translation stays English rather than going blank. */
	enum Language
	{
		ENGLISH,
		JAPANESE;

		@Override
		public String toString()
		{
			// ASCII only: RuneLite's settings UI draws this label in a font with
			// no Japanese glyphs, so a native label renders as an empty box.
			return this == JAPANESE ? "Japanese" : "English";
		}
	}

	@ConfigItem(
		keyName = "apiKey",
		name = "Plugin key",
		description = "Your PriceCheck plugin key (starts with pck_). Generate it free at pricecheck.gg (Discord login). "
			+ "Requests made with a key send your IP address to PriceCheck's servers, which are not controlled or verified by the RuneLite Developers. "
			+ "While a PriceCheck trial is active on your key, an anonymous per-account identifier (never your RSN) is sent once per game account to bind the trial to it. "
			+ "Your RSN and game credentials are never sent.",
		secret = true,
		position = 1
	)
	default String apiKey()
	{
		return "";
	}

	@ConfigItem(
		keyName = "deskMode",
		name = "Terminal desk",
		description = "The trading-terminal style desk around the open Grand Exchange: status bar, item card with the live chart and tape, "
			+ "offers blotter, opportunity radar, held positions, session flow, fills and ticker. "
			+ "Auto fits the layout to your window size; the fixed tiers cap how much draws; Off hides the desk entirely. "
			+ "Market data needs Trader ($1/mo) or a trial; the flip log works without.",
		position = 2
	)
	default DeskMode deskMode()
	{
		return DeskMode.AUTO;
	}

	@ConfigItem(
		keyName = "language",
		name = "Language",
		description = "Language for the PriceCheck panel and the Grand Exchange desk. Applies straight away. "
			+ "Item names, prices and the text filled into the game stay as the game gives them, because the client's own font "
			+ "cannot draw Japanese. If no Japanese font is installed the plugin stays in English.",
		position = 3
	)
	default Language language()
	{
		return Language.ENGLISH;
	}

	@ConfigItem(
		keyName = "minEvPerHrK",
		name = "Min EV/hr (k)",
		description = "Hide flips whose expected value per hour is below this many thousand gp.",
		position = 4
	)
	default int minEvPerHrK()
	{
		return 0;
	}

	@ConfigItem(
		keyName = "geAssists",
		name = "GE fill assists",
		description = "One-click helpers inside the GE: clickable price lines when setting an offer (our live buy/sell, your break-even "
			+ "when selling a tracked position), your remaining 4h buy limit on the quantity box, and tracked positions plus the "
			+ "best flips as clickable results while the item search is empty. Pre-fill only; you always press Enter yourself.",
		position = 5
	)
	default boolean geAssists()
	{
		return true;
	}

	@ConfigItem(
		keyName = "geAutofillHotkey",
		name = "GE autofill hotkey",
		description = "Press this while a GE buy or sell price box is open to fill PriceCheck's recommended price for that item; press it on the quantity box of a buy offer to fill your remaining 4h buy limit. You still press Enter to place the offer. Unbound by default.",
		position = 6
	)
	default Keybind geAutofillHotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "discordOfferAlerts",
		name = "Discord offer alerts",
		description = "Get a PriceCheck Discord DM when one of your open GE offers is undercut, outbid, or probably filled while you were offline. Trader Pro only. Pick how often you want to hear from the bot.",
		position = 7
	)
	default AlertCadence discordOfferAlerts()
	{
		return AlertCadence.OFF;
	}

	@ConfigItem(
		keyName = "syncFlipLog",
		name = "Sync flip log (backup + web portfolio)",
		description = "Back up your flip log to your PriceCheck account and show it at flipping.pricecheck.gg/portfolio. "
			+ "Also keeps the log consistent when you flip on more than one computer.",
		warning = "Enabling this submits your Grand Exchange trades (item, price, quantity, tax, profit, timestamps), open positions, "
			+ "offer-slot snapshots, an anonymous per-account identifier (never your RSN), and your IP address to PriceCheck's servers, "
			+ "which are not controlled or verified by the RuneLite Developers. Continue?",
		position = 8
	)
	default boolean syncFlipLog()
	{
		return false;
	}

	@ConfigItem(
		keyName = "contributeData",
		name = "Contribute market data",
		description = "Report your own GE offer fills to PriceCheck toward a measured fill-time model. Only offer details (the item, your price and quantity, how much has filled, which GE slot, and the time) are sent, never your RSN or anything about your account.",
		warning = "Enabling this submits your Grand Exchange offer details (the item, your price and quantity, how much has filled, which GE slot, and the time it happened) and your IP address "
			+ "to PriceCheck's servers, which are not controlled or verified by the RuneLite Developers. Continue?",
		position = 9
	)
	default boolean contributeData()
	{
		return false;
	}

	@ConfigItem(
		keyName = "showPanel",
		name = "Show side panel",
		description = "Show the PriceCheck flip panel in the RuneLite sidebar.",
		position = 10
	)
	default boolean showPanel()
	{
		return true;
	}

}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.util.ArrayList;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Your trades, docked below the Grand Exchange window. The item's own buy/sell
 * history (from the flip log) is drawn in the empty floor space under the GE,
 * above the chatbox, so it never crowds the interface. Holding Shift reveals
 * page arrows when the history runs longer than the space. Also detects the
 * item being priced so the evidence card renders on the set-up screen.
 */
class OfferSetupOverlay extends Overlay
{
	private static final int GE_GROUP = 465;
	private static final int[] SETUP_PANELS = { 15, 26 };
	private static final int COINS_ITEM = 995;

	private static final Color INK = new Color(0x08, 0x07, 0x05, 238);
	private static final Color FRAME = new Color(0xe6, 0xc6, 0x67, 70);
	private static final Color RULE = new Color(0xe6, 0xc6, 0x67, 38);
	private static final Color NAME = new Color(0xde, 0xd8, 0xc8);
	private static final Color SHADOW = new Color(0, 0, 0, 180);
	private static final int PAD = 8;
	private static final int ROW_H = 14;

	private final Client client;
	private final PriceCheckPlugin plugin;
	private final PriceCheckConfig config;

	private int page;
	// {Rectangle, Integer delta} page arrows, canvas space, only while Shift is held.
	private volatile List<Object[]> navHits = java.util.Collections.emptyList();

	OfferSetupOverlay(Client client, PriceCheckPlugin plugin, PriceCheckConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	/** Shift-click a page arrow to turn the page. Returns true when it handled the click. */
	boolean handleClick(Point p, boolean shiftHeld)
	{
		if (p == null || !shiftHeld)
		{
			return false;
		}
		for (final Object[] b : navHits)
		{
			if (((Rectangle) b[0]).contains(p))
			{
				page += (int) b[1];
				return true;
			}
		}
		return false;
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		navHits = java.util.Collections.emptyList();

		// Keep feeding the set-up item to the card even when the panel is off.
		final Widget setupPanel = setupPanel();
		if (setupPanel != null)
		{
			for (final Widget c : allChildren(setupPanel))
			{
				if (c == null)
				{
					continue;
				}
				final int item = c.getItemId();
				if (item > 0 && item != COINS_ITEM)
				{
					plugin.noteSetupItem(item);
					break;
				}
			}
		}

		// The classic "Your trades" log is retired: the terminal ORDER panel
		// covers the FULL tier and the card's own-trades tape covers the rest.
		// This overlay's remaining job is the setup-item feed above, which the
		// chart card and the GE prefills read.
		return null;
	}

	private static int rowWidth(FontMetrics fm, long[] t)
	{
		final boolean buy = t[3] == 1;
		String label = Fmt.full(t[1]);
		if (t[2] > 1)
		{
			label += " x" + Fmt.full(t[2]);
		}
		final String mid = buy ? (t[4] == 1 ? "holding" : "") : signed(t[5]);
		return 14 + fm.stringWidth(label) + 18 + fm.stringWidth(mid) + 18 + fm.stringWidth("00h ago");
	}

	private void paintRow(Graphics2D g, FontMetrics fm, int x, int top, int w, long[] t, long nowSec)
	{
		final boolean buy = t[3] == 1;
		final int ty = top + fm.getAscent();
		final Path2D tri = new Path2D.Float();
		final int tx = x + PAD;
		if (buy)
		{
			tri.moveTo(tx, ty - 1);
			tri.lineTo(tx + 7, ty - 1);
			tri.lineTo(tx + 3.5, ty - 7);
		}
		else
		{
			tri.moveTo(tx, ty - 7);
			tri.lineTo(tx + 7, ty - 7);
			tri.lineTo(tx + 3.5, ty - 1);
		}
		tri.closePath();
		g.setColor(SHADOW);
		g.translate(1, 1);
		g.fill(tri);
		g.translate(-1, -1);
		g.setColor(buy ? Palette.GREEN : Palette.GOLD);
		g.fill(tri);

		String label = Fmt.full(t[1]);
		if (t[2] > 1)
		{
			label += " x" + Fmt.full(t[2]);
		}
		shadowed(g, label, x + PAD + 12, ty, NAME);

		final String mid;
		final Color midCol;
		if (buy)
		{
			mid = t[4] == 1 ? "holding" : "";
			midCol = Palette.SUBTLE;
		}
		else
		{
			mid = signed(t[5]);
			midCol = t[5] >= 0 ? Palette.GREEN : Palette.RED;
		}
		if (!mid.isEmpty())
		{
			shadowed(g, mid, x + w / 2 + 6, ty, midCol);
		}

		final long ago = Math.max(0, nowSec - t[0] / 1000L);
		final String age = ago < 60 ? ago + "s ago"
			: ago < 5400 ? (ago / 60) + "m ago"
			: ago < 172800 ? (ago / 3600) + "h ago" : (ago / 86400) + "d ago";
		shadowed(g, age, x + w - PAD - fm.stringWidth(age), ty, Palette.SUBTLE);
	}

	private static String signed(long v)
	{
		return v == 0 ? "" : (v >= 0 ? "+" : "") + Fmt.compact(v);
	}

	private void arrow(Graphics2D g, Rectangle r, boolean right)
	{
		final int cx = r.x + r.width / 2;
		final int cy = r.y + r.height / 2;
		final Path2D p = new Path2D.Float();
		if (right)
		{
			p.moveTo(cx - 2, cy - 4);
			p.lineTo(cx + 3, cy);
			p.lineTo(cx - 2, cy + 4);
		}
		else
		{
			p.moveTo(cx + 2, cy - 4);
			p.lineTo(cx - 3, cy);
			p.lineTo(cx + 2, cy + 4);
		}
		p.closePath();
		g.setColor(SHADOW);
		g.translate(1, 1);
		g.fill(p);
		g.translate(-1, -1);
		g.setColor(Palette.GOLD);
		g.fill(p);
	}

	private Widget setupPanel()
	{
		for (final int child : SETUP_PANELS)
		{
			final Widget w = client.getWidget(GE_GROUP, child);
			if (w != null && !w.isHidden())
			{
				return w;
			}
		}
		return null;
	}

	private static void shadowed(Graphics2D g, String s, int x, int y, Color c)
	{
		g.setColor(SHADOW);
		g.drawString(s, x + 1, y + 1);
		g.setColor(c);
		g.drawString(s, x, y);
	}

	private static Widget[] allChildren(Widget panel)
	{
		final Widget[] stat = panel.getStaticChildren();
		final Widget[] dyn = panel.getDynamicChildren();
		final int sl = stat == null ? 0 : stat.length;
		final int dl = dyn == null ? 0 : dyn.length;
		final Widget[] all = new Widget[sl + dl];
		if (sl > 0)
		{
			System.arraycopy(stat, 0, all, 0, sl);
		}
		if (dl > 0)
		{
			System.arraycopy(dyn, 0, all, sl, dl);
		}
		return all;
	}
}

package gg.pricecheck.runelite;

import lombok.Value;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Immutable snapshot of one Grand Exchange slot, captured on the client thread in
 * the offer-changed handler so the advisor (which runs on a background poller and
 * the overlay render thread) can read it without touching the live client object.
 */
@Value
class TrackedOffer
{
	int slot;
	int itemId;
	long price;   // per-item price the player set
	int totalQty;
	int soldQty;
	GrandExchangeOfferState state;

	static TrackedOffer of(int slot, GrandExchangeOffer o)
	{
		return new TrackedOffer(slot, o.getItemId(), o.getPrice(), o.getTotalQuantity(), o.getQuantitySold(), o.getState());
	}

	boolean isBuying()
	{
		return state == GrandExchangeOfferState.BUYING;
	}

	boolean isSelling()
	{
		return state == GrandExchangeOfferState.SELLING;
	}

	boolean isActive()
	{
		return isBuying() || isSelling();
	}

	boolean isDone()
	{
		return state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.SOLD;
	}

	boolean isRelevant()
	{
		return isActive() || isDone();
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The desk's WATCHLIST, docked in the top-centre box above the Grand Exchange: the
 * entry targets you're tracking (your watch price + how close the market is), then
 * the board's top picks by EV/hr to fill. Content-sized and anchored to the top of
 * the held panel so it always connects to the centre column with no dead space. If
 * you track more favourites than fit, hold/press Shift to page through them (the
 * plugin's shift-to-reveal convention). Opt-in via config.terminalDesk().
 */
class TerminalWatchlistOverlay extends Overlay
{
	private static final int TOP_Y = 8;
	private static final int ROW = 16;
	private static final int TITLE_H = 32;
	private static final int DIVIDER_H = 20;
	private static final int MIN_H = 58;

	/** A tracked entry target. state: 2 = at/below target (buy), 1 = near, 0 = wait. */
	static final class Watch
	{
		final String name;
		final long target;
		final int state;
		Watch(String name, long target, int state) { this.name = name; this.target = target; this.state = state; }
	}

	/** A board pick to fill the list. */
	static final class Pick
	{
		final String name;
		final long buy;
		final long evPerHr;
		Pick(String name, long buy, long evPerHr) { this.name = name; this.buy = buy; this.evPerHr = evPerHr; }
	}

	private final Client client;
	private final PriceCheckPlugin plugin;
	// Shift-paging state for a long favourites list.
	private boolean lastShift;
	private int favPage;

	TerminalWatchlistOverlay(Client client, PriceCheckPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.terminalDesk() || !plugin.marketDataOk() || !plugin.isGrandExchangeOpen())
		{
			return null;
		}
		final Rectangle ge = plugin.geGridBounds();
		if (ge == null)
		{
			return null;
		}
		final List<Watch> watch = buildWatch();
		final List<Pick> picks = buildPicks(watch);
		if (watch.isEmpty() && picks.isEmpty())
		{
			return null;
		}
		// Box bottom = the held panel's top (flush), else the status band.
		final int heldTop = plugin.heldTopY();
		final int boxBottom = heldTop > 0 ? heldTop - 4 : ge.y - 44;
		final int maxH = boxBottom - TOP_Y;
		if (maxH < MIN_H)
		{
			return null;
		}
		final int availRows = Math.max(1, (maxH - TITLE_H - 6) / ROW);

		// Advance the favourites page on each Shift press (edge-triggered).
		final boolean shift = client.isKeyPressed(KeyCode.KC_SHIFT);
		final boolean pressed = shift && !lastShift;
		lastShift = shift;

		// Decide the layout: favourites page (they don't fit) vs favourites + picks.
		final List<Watch> watchPage;
		final List<Pick> showPicks;
		int pageCount = 1;
		final boolean picksWanted = !picks.isEmpty();
		if (!watch.isEmpty() && watch.size() > availRows - (picksWanted ? 2 : 0))
		{
			final int perPage = availRows;
			pageCount = (watch.size() + perPage - 1) / perPage;
			if (pressed) { favPage++; }
			favPage = ((favPage % pageCount) + pageCount) % pageCount;
			final int from = favPage * perPage;
			watchPage = new ArrayList<>(watch.subList(from, Math.min(from + perPage, watch.size())));
			showPicks = Collections.emptyList();
		}
		else
		{
			favPage = 0;
			watchPage = watch;
			final int remain = availRows - watch.size();
			showPicks = picksWanted && remain >= 2
				? new ArrayList<>(picks.subList(0, Math.min(remain - 1, picks.size())))
				: Collections.<Pick>emptyList();
		}

		final int contentH = TITLE_H
			+ watchPage.size() * ROW
			+ (showPicks.isEmpty() ? 0 : DIVIDER_H + showPicks.size() * ROW)
			+ 6;
		final int h = Math.min(contentH, maxH);
		final int y = boxBottom - h;   // bottom-anchored, flush against the held panel
		final int x = ge.x;
		final int fp = favPage;
		final int pc = pageCount;

		final Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Object taa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		final int painted;
		g.translate(x, y);
		try
		{
			painted = paintWatchlist(g, ge.width, h, watchPage, showPicks, fp, pc);
		}
		finally
		{
			g.translate(-x, -y);
			if (aa != null) { g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa); }
			if (taa != null) { g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, taa); }
		}
		plugin.noteDeskRect("watchlist", x, y, ge.width, painted);
		return new Dimension(ge.width, h);
	}

	/** Watch targets: tracked items you don't hold yet, at-target first. */
	private List<Watch> buildWatch()
	{
		final List<Watch> out = new ArrayList<>();
		for (final TrackedItem t : plugin.trackedItems())
		{
			if (t == null || t.isHeld() || t.getWatchBuy() <= 0)
			{
				continue;
			}
			final FlipData live = plugin.liveFor(t.getGeId());
			final long marketBuy = live != null ? live.getBuy() : 0;
			int state = 0;
			if (marketBuy > 0)
			{
				if (marketBuy <= t.getWatchBuy()) { state = 2; }
				else if (marketBuy <= t.getWatchBuy() * 1.02) { state = 1; }
			}
			out.add(new Watch(t.getName() == null ? "#" + t.getGeId() : t.getName(), t.getWatchBuy(), state));
		}
		out.sort(Comparator.comparingInt((Watch wch) -> -wch.state));
		return out;
	}

	/** Top board picks by EV, excluding anything already on the watch list. */
	private List<Pick> buildPicks(List<Watch> watch)
	{
		final java.util.Set<String> have = new java.util.HashSet<>();
		for (final Watch w : watch)
		{
			have.add(w.name);
		}
		final List<Pick> out = new ArrayList<>();
		for (final FlipData f : plugin.boardFlips())
		{
			final String nm = f.getName() == null ? "#" + f.getGeId() : f.getName();
			if (have.contains(nm))
			{
				continue;
			}
			out.add(new Pick(nm, f.getBuy(), f.getEvPerHr()));
		}
		return out;
	}

	/** Pure drawing (0,0-origin) so the preview harness can render it headless. Returns the painted height. */
	static int paintWatchlist(Graphics2D g, int w, int h, List<Watch> watch, List<Pick> picks, int favPage, int pageCount)
	{
		TerminalKit.hints(g);
		int cy = TerminalKit.panel(g, 0, 0, w, h, I18n.t("WATCHLIST  ·  YOUR TARGETS"));
		// Page indicator on the title strip when the favourites span multiple pages.
		if (pageCount > 1)
		{
			g.setFont(TerminalKit.mono(9)); g.setColor(TerminalKit.LABEL);
			TerminalKit.rt(g, "▸ " + (favPage + 1) + "/" + pageCount + "  shift", w - 8, 13);
		}
		final FontMetrics fm = g.getFontMetrics(TerminalKit.mono(11));
		final int nameClip = w - 8 - 150;
		final int buyXr = w - 92;
		final int tagXr = w - 10;

		for (final Watch wc : watch)
		{
			final Color sc = wc.state == 2 ? TerminalKit.GREEN : wc.state == 1 ? TerminalKit.AMBER : TerminalKit.DIM;
			g.setFont(TerminalKit.monoB(11)); g.setColor(sc);
			g.drawString("◆", 8, cy);
			g.setFont(TerminalKit.mono(11)); g.setColor(TerminalKit.AMBER);
			g.drawString(clip(wc.name, fm, nameClip - 16), 24, cy);
			g.setFont(TerminalKit.mono(10)); g.setColor(TerminalKit.LABEL);
			TerminalKit.rt(g, I18n.f("buy %s", TerminalKit.gp(wc.target)), buyXr, cy);
			g.setFont(TerminalKit.monoB(9)); g.setColor(sc);
			TerminalKit.rt(g, wc.state == 2 ? I18n.t("BUY") : wc.state == 1 ? I18n.t("NEAR") : I18n.t("WAIT"), tagXr, cy);
			cy += ROW;
		}

		if (!picks.isEmpty())
		{
			g.setColor(TerminalKit.GRID); g.drawLine(8, cy - 4, w - 8, cy - 4);
			g.setFont(TerminalKit.mono(8)); g.setColor(TerminalKit.DIM);
			g.drawString(watch.isEmpty() ? I18n.t("TOP PICKS  ·  EV/HR") : I18n.t("TOP PICKS  ·  BY EV/HR"), 8, cy + 8);
			TerminalKit.rt(g, I18n.t("EV/HR"), tagXr, cy + 8);
			cy += DIVIDER_H;
			for (final Pick p : picks)
			{
				g.setFont(TerminalKit.mono(11)); g.setColor(TerminalKit.AMBER);
				g.drawString(clip(p.name, fm, nameClip), 8, cy);
				g.setFont(TerminalKit.mono(10)); g.setColor(TerminalKit.LABEL);
				TerminalKit.rt(g, I18n.f("buy %s", TerminalKit.gp(p.buy)), buyXr, cy);
				g.setFont(TerminalKit.monoB(11)); g.setColor(TerminalKit.AMBERHI);
				TerminalKit.rt(g, TerminalKit.gp(p.evPerHr), tagXr, cy);
				cy += ROW;
			}
		}
		return h;
	}

	private static String clip(String s, FontMetrics fm, int maxW)
	{
		if (s == null) { return ""; }
		if (fm.stringWidth(s) <= maxW) { return s; }
		int n = s.length();
		while (n > 0 && fm.stringWidth(s.substring(0, n) + "…") > maxW) { n--; }
		return s.substring(0, n) + "…";
	}
}

package gg.pricecheck.runelite;

import com.google.gson.Gson;
import java.util.HashMap;
import java.util.Map;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.client.config.ConfigManager;

/**
 * Tracks the player's own GE buy-fill quantity per item over the current 4h buy
 * window, so the terminal card can show LIMIT remaining + a RESET countdown and
 * the quantity autofill can cap a buy to what's left.
 *
 * Window model (matches the game, and RuneLite's own GE limit tracker): the 4h
 * timer starts at your FIRST buy of an item and every buy inside that window
 * counts; once 4h pass from that first buy the counter resets fully to zero and
 * the next buy opens a fresh window. A fixed window anchored at the first buy,
 * NOT a rolling per-fill window.
 *
 * Counting: a GE offer's quantitySold is cumulative for that offer, so a fill is
 * the GROWTH in quantitySold. We keep a per-slot cursor (the item + last counted
 * quantitySold) and only add the growth to the item's window.
 *
 * Login / world-hop / restart safety: the client blanks every slot to EMPTY and
 * replays the live offers after a login or hop. We must not re-count a replayed
 * offer. So the cursor is PERSISTED and is NOT cleared on an EMPTY/non-buy event
 * - a replayed offer arrives with the same item and the same quantitySold, so its
 * growth is zero. A genuinely new offer is recognised by its item changing or its
 * quantitySold dropping below the cursor (a fresh offer restarts at zero), which
 * reseeds the cursor and counts nothing on first sight. All state is per account.
 */
class BuyLimitTracker
{
	static final long WINDOW_MS = 4L * 60 * 60 * 1000;
	private static final int SLOTS = 8;
	private static final String KEY = "buylimit";

	/** Persisted snapshot: windows + per-slot cursor, all for one account. */
	private static final class Snapshot
	{
		Map<Integer, long[]> byItem;   // geId -> {windowStartMs, boughtInWindow}
		int[] slotItem;                // per slot: item the cursor is bound to
		long[] slotSold;               // per slot: last counted quantitySold
	}

	private final Gson gson;
	private final ConfigManager configManager;
	private final Map<Integer, long[]> byItem = new HashMap<>();
	private final long[] slotSold = new long[SLOTS];
	private final int[] slotItem = new int[SLOTS];
	private long account = -1;

	BuyLimitTracker(Gson gson, ConfigManager configManager)
	{
		this.gson = gson;
		this.configManager = configManager;
	}

	private static boolean isBuy(GrandExchangeOfferState s)
	{
		return s == GrandExchangeOfferState.BUYING
			|| s == GrandExchangeOfferState.BOUGHT
			|| s == GrandExchangeOfferState.CANCELLED_BUY;
	}

	private static boolean expired(long[] w, long nowMs)
	{
		return w == null || nowMs >= w[0] + WINDOW_MS;
	}

	synchronized void setAccount(long acc)
	{
		if (acc == account || acc == -1)
		{
			return;
		}
		account = acc;
		byItem.clear();
		for (int i = 0; i < SLOTS; i++)
		{
			slotSold[i] = 0;
			slotItem[i] = 0;
		}
		load();
	}

	/** Feed a live GE offer change; the growth in bought quantity is a buy fill. */
	synchronized void onOffer(int slot, GrandExchangeOffer o, long nowMs)
	{
		if (slot < 0 || slot >= SLOTS || o == null)
		{
			return;
		}
		final int itemId = o.getItemId();
		if (!isBuy(o.getState()) || itemId <= 0)
		{
			// EMPTY blank, a sell, or a collected slot. Leave the cursor alone: a
			// login/hop replays live offers right after blanking every slot, and
			// clearing here would make the replay look like fresh fills.
			return;
		}
		final long sold = o.getQuantitySold();
		if (slotItem[slot] != itemId || sold < slotSold[slot])
		{
			// A different item now occupies this slot, or quantitySold dropped (the
			// old offer was collected/cancelled and a new one of the same item
			// started): a new offer. Seed the cursor to its current progress and
			// count nothing on first sight - a fresh offer starts at zero, and any
			// pre-existing fill was already counted in the session that saw it.
			slotItem[slot] = itemId;
			slotSold[slot] = sold;
			save();
			return;
		}
		final long delta = sold - slotSold[slot];
		slotSold[slot] = sold;
		if (delta <= 0)
		{
			return;
		}
		long[] w = byItem.get(itemId);
		if (expired(w, nowMs))
		{
			// First buy of a new window: anchor it here and start counting.
			w = new long[]{nowMs, 0};
			byItem.put(itemId, w);
		}
		w[1] += delta;
		save();
	}

	/** Units of this item bought within the current 4h window (0 once it resets). */
	synchronized long boughtIn4h(int geId, long nowMs)
	{
		final long[] w = byItem.get(geId);
		return expired(w, nowMs) ? 0 : w[1];
	}

	/** Epoch ms when the current window resets the limit to zero, 0 if none active. */
	synchronized long resetAt(int geId, long nowMs)
	{
		final long[] w = byItem.get(geId);
		return expired(w, nowMs) ? 0 : w[0] + WINDOW_MS;
	}

	private void load()
	{
		try
		{
			final String json = configManager.getConfiguration(PriceCheckConfig.GROUP, KEY + "_" + account);
			if (json == null || json.isEmpty())
			{
				return;
			}
			final Snapshot snap = gson.fromJson(json, Snapshot.class);
			if (snap == null)
			{
				return;
			}
			final long now = System.currentTimeMillis();
			if (snap.byItem != null)
			{
				snap.byItem.forEach((k, v) ->
				{
					if (v != null && v.length == 2 && !expired(v, now))
					{
						byItem.put(k, v);
					}
				});
			}
			if (snap.slotItem != null && snap.slotSold != null
				&& snap.slotItem.length == SLOTS && snap.slotSold.length == SLOTS)
			{
				System.arraycopy(snap.slotItem, 0, slotItem, 0, SLOTS);
				System.arraycopy(snap.slotSold, 0, slotSold, 0, SLOTS);
			}
		}
		catch (RuntimeException ignored)
		{
		}
	}

	private void save()
	{
		try
		{
			final long now = System.currentTimeMillis();
			byItem.entrySet().removeIf(e -> expired(e.getValue(), now));
			final Snapshot snap = new Snapshot();
			snap.byItem = byItem;
			snap.slotItem = slotItem;
			snap.slotSold = slotSold;
			configManager.setConfiguration(PriceCheckConfig.GROUP, KEY + "_" + account, gson.toJson(snap));
		}
		catch (RuntimeException ignored)
		{
		}
	}
}

package gg.pricecheck.runelite;

import java.util.List;
import lombok.Data;

/**
 * One live "mover": a price dump the board is tracking for a possible catch,
 * served as the {@code movers} sibling array on GET /api/plugin/flips. Field
 * names match the server's trimmed shape so Gson maps them directly.
 *
 * Honesty contract: pReversion, target and expHoldMin are trial-measured only
 * when {@code measured} is true; otherwise they are conservative estimates and
 * the surfaces say so. pReversion is a Wilson LOWER-bounded historical base
 * rate (only ever discounted by live flow, never inflated). target is an
 * explicit conservative, taxed, half-recovery projection contingent on the
 * reversion actually happening; it is never presented as guaranteed. A row
 * with too few trials hides its "bounces N/10" fraction and shows the sample
 * count, and a still-falling dump reads "FALLING KNIFE - skip", never a catch.
 */
@Data
public class CatchData
{
	private int geId;
	private String name;
	private String dir;            // "up" | "down"
	private double pctMove;        // signed displacement from the reference, %
	private int minutesRunning;    // how long the move has been running
	private String state;          // catchable | knife | watch | recovering | faded
	private double pReversion;     // Wilson lower-bound base rate [0,1], measured only when `measured`
	private int baseRateN;         // excursion trials behind pReversion (0 = heuristic/none)
	private int pReversionN;       // server alias for the same trial count
	private boolean knife;         // still falling: not catchable
	private boolean catchable;     // engine says a catch is on the table
	private boolean measured;      // pReversion/target/expHoldMin are trial-measured, not estimated
	private int expHoldMin;        // measured median recovery minutes; 0 when unmeasured
	private List<String> reasons;  // short board notes behind the read
	private long bid;              // live insta-buy entry
	private long target;           // conservative taxed half-recovery level
	private double roi;            // projected ROI at the target
	private int catchQty;          // suggested catch size
	private int rating;            // engine rank score (higher = stronger)
	private boolean thinEvidence;  // small sample: hide the fraction, show the count

	/** The excursion trial count behind the base rate, under either wire name. */
	int trialsN()
	{
		return Math.max(baseRateN, pReversionN);
	}

	/**
	 * True only when the loud CATCH read is earned: the row is trial-measured,
	 * catchable, not a knife, has enough excursion trials, a valid base rate,
	 * and that rate clears the caller's bar. Everything else stays a quiet watch.
	 */
	boolean loudEligible(int barPercent)
	{
		return measured && catchable && !knife
			&& trialsN() >= 20
			&& pReversion >= 0.0 && pReversion <= 1.0
			&& pReversion * 100.0 >= barPercent;
	}

	/**
	 * The reversion read. A measured, non-thin row shows the Wilson fraction and
	 * its sample count; a measured-but-thin row shows just the count; anything
	 * heuristic or under 20 trials reads "displaced" with no invented odds.
	 */
	String bouncesText()
	{
		if (!measured || trialsN() < 20)
		{
			return I18n.t("displaced");
		}
		if (thinEvidence)
		{
			return "n=" + trialsN();
		}
		final int hits = (int) Math.round(Math.max(0.0, Math.min(1.0, pReversion)) * 10);
		return I18n.f("bounces %d/10 (n=%d)", hits, trialsN());
	}

	/** Measured median recovery time, or an honest "est." placeholder. */
	String holdText()
	{
		return (measured && expHoldMin > 0) ? "~" + expHoldMin + "m" : I18n.t("est.");
	}
}

package gg.pricecheck.runelite;

import java.util.Locale;

/** gp formatting shared everywhere. Lowercase compact (1.5b / 200m / 50.9k) to
 * match pricecheck.gg, and exact comma-grouped for the figures you type/read. */
final class Fmt
{
	private Fmt() {}

	static String compact(long n)
	{
		final long a = Math.abs(n);
		if (a >= 1_000_000_000L) return trim(n / 1e9) + "b";
		if (a >= 1_000_000L) return trim(n / 1e6) + "m";
		if (a >= 1_000L) return trim(n / 1e3) + "k";
		return String.valueOf(n);
	}

	static String full(long n)
	{
		return String.format(Locale.ROOT, "%,d", n);
	}

	/** Compact time-remaining: 2h04m / 43m / 58s. Sub-second floors to 1s; the
	 *  "already elapsed" case is the caller's to label (e.g. "ready"). */
	static String duration(long ms)
	{
		final long s = Math.max(0, ms) / 1000;
		final long h = s / 3600, m = (s % 3600) / 60;
		if (h > 0)
		{
			return h + "h" + String.format(Locale.ROOT, "%02d", m) + "m";
		}
		if (m > 0)
		{
			return m + "m";
		}
		return Math.max(1, s) + "s";
	}

	/** Parse a gp amount the way players type it: 25m, 1.2b, 800k, 25,000,000.
	 *  Returns -1 when it isn't one. */
	static long parseGp(String s)
	{
		if (s == null)
		{
			return -1;
		}
		s = s.trim().toLowerCase(Locale.ROOT).replace(",", "");
		if (s.isEmpty())
		{
			return -1;
		}
		double mult = 1;
		final char last = s.charAt(s.length() - 1);
		if (last == 'k') { mult = 1e3; s = s.substring(0, s.length() - 1); }
		else if (last == 'm') { mult = 1e6; s = s.substring(0, s.length() - 1); }
		else if (last == 'b') { mult = 1e9; s = s.substring(0, s.length() - 1); }
		try
		{
			final double v = Double.parseDouble(s);
			if (v < 0 || v * mult > 9e15)
			{
				return -1;
			}
			return (long) Math.floor(v * mult);
		}
		catch (NumberFormatException e)
		{
			return -1;
		}
	}

	private static String trim(double d)
	{
		String s = String.format(Locale.ROOT, "%.2f", d);
		if (s.contains("."))
		{
			s = s.replaceAll("0+$", "").replaceAll("\\.$", "");
		}
		return s;
	}
}

package gg.pricecheck.runelite;

import java.awt.Component;
import java.awt.Container;
import java.awt.Font;
import java.awt.GraphicsEnvironment;
import java.util.Arrays;
import java.util.HashMap;
import java.util.HashSet;
import java.util.Map;
import java.util.Set;
import lombok.extern.slf4j.Slf4j;

/**
 * Plugin language. English is the source text AND the key, so an untranslated
 * string simply stays English instead of showing a placeholder: nothing can
 * render blank because a phrase was missed.
 *
 * The font is the real constraint. RuneLite's bitmap faces (and the game's own)
 * carry no Japanese glyphs, so drawing Japanese in them paints empty boxes.
 * Three rules keep that from happening:
 *   1. Japanese only switches on when a font that can actually draw it is
 *      installed - otherwise the plugin stays English and says so in the log.
 *   2. fit() hands back a Japanese-capable face ONLY for the strings that need
 *      one, so prices and the tabular mono columns keep the face they were
 *      tuned for.
 *   3. Text drawn INTO the game (the GE price and quantity prefills) is never
 *      translated: those render in the client's own font, which has no
 *      Japanese glyphs at any size.
 */
@Slf4j
final class I18n
{
	/** A glyph any usable Japanese face must carry. */
	private static final char PROBE = '価';   // 価

	private static volatile boolean jp;
	private static volatile String cjk;
	private static volatile boolean probed;
	private static final Map<String, Font> SUBST = new java.util.concurrent.ConcurrentHashMap<>();

	private I18n() { }

	static boolean japanese()
	{
		return jp;
	}

	/** Client thread / EDT. Silently stays English when no Japanese font exists. */
	static void setLanguage(PriceCheckConfig.Language lang)
	{
		if (lang != PriceCheckConfig.Language.JAPANESE)
		{
			jp = false;
			return;
		}
		if (!probed)
		{
			cjk = findJapaneseFamily();
			probed = true;   // set AFTER the scan it guards
			if (cjk == null)
			{
				log.warn("PriceCheck: no font on this machine can draw Japanese, staying in English");
			}
			else
			{
				log.debug("PriceCheck: Japanese font resolved to {}", cjk);
			}
		}
		jp = cjk != null;
	}

	/** The translation, or the English source when there isn't one. */
	static String t(String en)
	{
		if (!jp || en == null)
		{
			return en;
		}
		final String s = JA.get(en);
		return s != null ? s : en;
	}

	/**
	 * Translate a pattern, then fill it. Composed labels ("31 FLIPS · BY EV/HR")
	 * must translate as ONE pattern, never as glued fragments: Japanese puts the
	 * pieces in a different order and needs no plural forms.
	 */
	static String f(String pattern, Object... args)
	{
		try
		{
			return String.format(t(pattern), args);
		}
		catch (Exception e)
		{
			return String.format(pattern, args);   // a bad translation never breaks a label
		}
	}

	/**
	 * A verdict like "OK +26.2k" or "RAISE +12.9k" is a word plus a number. The
	 * word translates; the number is left exactly as the engine produced it.
	 */
	static String verdict(String s)
	{
		if (!jp || s == null || s.isEmpty())
		{
			return s;
		}
		final int sp = s.indexOf(' ');
		if (sp < 0)
		{
			return t(s);
		}
		final String head = t(s.substring(0, sp));
		return head + s.substring(sp);
	}

	/**
	 * The face to draw `text` in: the caller's own font whenever it can render
	 * the string, else the Japanese face at the same size and style. Latin
	 * strings therefore keep the mono/pixel face the layout was built around.
	 */
	static Font fit(Font base, String text)
	{
		if (!jp || cjk == null || base == null || text == null || text.isEmpty())
		{
			return base;
		}
		if (!hasJapanese(text))
		{
			return base;   // pure Latin keeps the mono face the columns were measured in
		}
		return font(base);
	}

	/**
	 * The Japanese stand-in for a font, matched on RENDERED LINE HEIGHT rather
	 * than nominal size. RuneLite's "size 16" pixel faces are 12px tall, so
	 * substituting at the same point size doubles every label and bursts the
	 * layout - this picks the size that occupies the same line instead.
	 */
	static Font font(Font base)
	{
		if (!jp || cjk == null || base == null || cjk.equals(base.getFamily()))
		{
			return base;
		}
		return SUBST.computeIfAbsent(base.getFamily() + "|" + base.getStyle() + "|" + base.getSize(),
			k -> matchHeight(base));
	}

	private static Font matchHeight(Font base)
	{
		final java.awt.Graphics2D g = metrics();
		// +2px: kanji carry far more detail than Latin at the same height, so
		// an exact match reads as squinting-small. Two pixels stays inside the
		// line spacing the panel lays out with.
		final int want = g.getFontMetrics(base).getHeight() + 2;
		for (int size = 6; size <= 40; size++)
		{
			final Font f = new Font(cjk, base.getStyle(), size);
			if (g.getFontMetrics(f).getHeight() >= want)
			{
				return f;
			}
		}
		return new Font(cjk, base.getStyle(), base.getSize());
	}

	private static volatile java.awt.Graphics2D probeG;

	/** Synchronised: reachable from the client thread (overlays) and the EDT
	 *  (panel build) both. Only ever called on a cache miss. */
	private static synchronized java.awt.Graphics2D metrics()
	{
		if (probeG == null)
		{
			probeG = new java.awt.image.BufferedImage(1, 1, java.awt.image.BufferedImage.TYPE_INT_ARGB)
				.createGraphics();
		}
		return probeG;
	}

	/**
	 * Swing: give every component in the tree a face that can draw Japanese.
	 * Called after the side panel is built and after each list refresh, so
	 * rows added later are covered too. No-op in English.
	 */
	static void applyFonts(Component root)
	{
		if (!jp || cjk == null || root == null)
		{
			return;
		}
		final Font f = root.getFont();
		if (f != null && !cjk.equals(f.getFamily()))
		{
			// Unconditional: RuneLite's pixel faces have no kana at all, and the
			// logical ones cannot be trusted to draw a mixed row.
			root.setFont(font(f));
		}
		if (root instanceof Container)
		{
			for (final Component kid : ((Container) root).getComponents())
			{
				applyFonts(kid);
			}
		}
	}

	/**
	 * Keep a whole panel in the right face for as long as it lives: every
	 * component added to the tree from now on gets the substitution too. Without
	 * this, a tab built the first time it is opened renders its Japanese as
	 * empty boxes, because the one-shot sweep already ran.
	 */
	static void installFontWatcher(Container root)
	{
		if (!jp || cjk == null || root == null)
		{
			return;
		}
		applyFonts(root);
		attach(root);
	}

	private static final java.awt.event.ContainerListener WATCHER = new java.awt.event.ContainerAdapter()
	{
		@Override
		public void componentAdded(java.awt.event.ContainerEvent e)
		{
			applyFonts(e.getChild());
			attach(e.getChild());
		}
	};

	private static void attach(Component c)
	{
		if (!(c instanceof Container))
		{
			return;
		}
		final Container k = (Container) c;
		k.removeContainerListener(WATCHER);   // never stack duplicates
		k.addContainerListener(WATCHER);
		for (final Component kid : k.getComponents())
		{
			attach(kid);
		}
	}

	/** Kana, CJK ideographs and the fullwidth forms - anything the plugin's own
	 *  faces cannot draw. */
	private static boolean hasJapanese(String s)
	{
		for (int i = 0; i < s.length(); i++)
		{
			if (s.charAt(i) >= 0x2E80)
			{
				return true;
			}
		}
		return false;
	}

	/** Preferred faces first (Windows, macOS, Linux), then anything that fits. */
	private static String findJapaneseFamily()
	{
		final String[] prefer = {
			"Noto Sans CJK JP", "Noto Sans JP", "Source Han Sans JP",
			"Hiragino Sans", "Hiragino Kaku Gothic ProN", "Osaka",
			"Yu Gothic", "Meiryo", "MS Gothic", "MS PGothic",
			"IPAGothic", "IPAPGothic", "TakaoGothic", "VL Gothic", "Droid Sans Japanese",
		};
		String[] installed;
		try
		{
			installed = GraphicsEnvironment.getLocalGraphicsEnvironment().getAvailableFontFamilyNames();
		}
		catch (Exception e)
		{
			return null;
		}
		final Set<String> have = new HashSet<>(Arrays.asList(installed));
		for (final String f : prefer)
		{
			if (have.contains(f) && canShow(f))
			{
				return f;
			}
		}
		// Any installed PHYSICAL face that can draw kana. Logical faces
		// (Monospaced, SansSerif, Dialog) are deliberately excluded: they claim
		// they can draw Japanese, then render a mixed Japanese + Latin string
		// with the Latin run missing entirely.
		for (final String f : installed)
		{
			if (!isLogical(f) && canShow(f))
			{
				return f;
			}
		}
		return null;
	}

	private static boolean isLogical(String family)
	{
		return Font.MONOSPACED.equalsIgnoreCase(family) || Font.SANS_SERIF.equalsIgnoreCase(family)
			|| Font.SERIF.equalsIgnoreCase(family) || Font.DIALOG.equalsIgnoreCase(family)
			|| Font.DIALOG_INPUT.equalsIgnoreCase(family);
	}

	private static boolean canShow(String family)
	{
		try
		{
			return new Font(family, Font.PLAIN, 12).canDisplay(PROBE);
		}
		catch (Exception e)
		{
			return false;
		}
	}

