package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The desk's RECENT FLIPS panel, docked to the lower-right of the Grand Exchange
 * (opposite the top-right blotter): your most recently closed flips with their
 * realised profit and age, from your own flip log. Opt-in via config.terminalDesk();
 * look from TerminalKit.
 */
class TerminalFillsOverlay extends Overlay
{
	static final int W = 292;
	private static final int ROW = 16;
	private static final int MAX_ROWS = 8;

	private final Client client;
	private final PriceCheckPlugin plugin;

	TerminalFillsOverlay(Client client, PriceCheckPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		plugin.noteFillsBottom(-1);
		if (!plugin.terminalDesk() || !plugin.isGrandExchangeOpen())
		{
			return null;
		}
		final Rectangle ge = plugin.geGridBounds();
		final FlipLogEngine.Summary s = plugin.flipSummary();
		if (ge == null || s == null || s.recent == null || s.recent.isEmpty())
		{
			return null;
		}
		final int x = ge.x + ge.width + 8;
		if (x + W > client.getCanvasWidth() - 4)
		{
			return null;   // no room to the right
		}
		// Stack directly under the blotter to form one tight right column; if the
		// blotter isn't docked right this frame (e.g. during set-up, where it yields
		// to the order ticket), top-align so recent-flips leads the column.
		final int bb = plugin.blotterBottomY();
		final int y = bb > 0 ? bb + 8 : 8;
		// Grow downward, but stop above the ticker and the chat box.
		int floorY = client.getCanvasHeight() - TerminalTickerOverlay.H - 8;
		final Rectangle cb = plugin.chatboxBounds();
		if (cb != null && cb.height > 0)
		{
			floorY = Math.min(floorY, cb.y - TerminalTickerOverlay.H - 8);
		}
		final int maxH = floorY - y;
		int rowN = Math.min(s.recent.size(), MAX_ROWS);
		while (rowN > 0 && 32 + rowN * ROW + 6 > maxH)
		{
			rowN--;
		}
		if (rowN <= 0)
		{
			return null;
		}
		final long now = System.currentTimeMillis();
		final int h = 32 + rowN * ROW + 6;

		final Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Object taa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		g.translate(x, y);
		final int ph;
		try
		{
			ph = paintFills(g, W, s.recent, rowN, now);
		}
		finally
		{
			g.translate(-x, -y);
			if (aa != null) { g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa); }
			if (taa != null) { g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, taa); }
		}
		plugin.noteFillsBottom(y + h);
		plugin.noteDeskRect("fills", x, y, W, ph);
		return new Dimension(W, h);
	}

	/** Pure drawing (0,0-origin) so the preview harness can render it headless; returns the painted height. */
	static int paintFills(Graphics2D g, int w, List<FlipLogEngine.Flip> recent, int rowN, long nowMs)
	{
		TerminalKit.hints(g);
		final int h = 32 + rowN * ROW + 6;
		int cy = TerminalKit.panel(g, 0, 0, w, h, I18n.t("RECENT FLIPS  ·  CLOSED"));
		final FontMetrics fm = g.getFontMetrics();
		for (int i = 0; i < rowN; i++)
		{
			final FlipLogEngine.Flip f = recent.get(i);
			final boolean up = f.profit >= 0;
			final Color c = up ? TerminalKit.GREEN : TerminalKit.RED;
			g.setFont(TerminalKit.monoB(11)); g.setColor(c);
			g.drawString(up ? "▲" : "▼", 8, cy);
			g.setFont(TerminalKit.mono(11)); g.setColor(TerminalKit.AMBER);
			g.drawString(clip(f.name == null ? ("#" + f.itemId) : f.name, fm, 150), 24, cy);
			g.setFont(TerminalKit.monoB(11)); g.setColor(c);
			TerminalKit.rt(g, (up ? "+" : "-") + TerminalKit.gp(Math.abs(f.profit)), w - 46, cy);
			g.setFont(TerminalKit.mono(9)); g.setColor(TerminalKit.DIM);
			TerminalKit.rt(g, age(nowMs - f.closedAt), w - 10, cy);
			cy += ROW;
		}
		return h;
	}

	private static String age(long ms)
	{
		final long s = Math.max(0, ms) / 1000;
		if (s < 60) { return s + "s"; }
		if (s < 3600) { return (s / 60) + "m"; }
		if (s < 86400) { return (s / 3600) + "h"; }
		return (s / 86400) + "d";
	}

	private static String clip(String s, FontMetrics fm, int maxW)
	{
		if (s == null) { return ""; }
		if (fm.stringWidth(s) <= maxW) { return s; }
		int n = s.length();
		while (n > 0 && fm.stringWidth(s.substring(0, n) + "…") > maxW) { n--; }
		return s.substring(0, n) + "…";
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.GeneralPath;

/**
 * Shared draw-kit for the "terminal" (trading-terminal style) Grand Exchange overlays:
 * an amber-on-black palette, a monospace font, and panel / cell / chip / sparkline
 * / right-align primitives. Promoted from the approved trading-terminalCardPreview and
 * trading-terminalDeskPreview mocks so every terminal panel reads as one instrument.
 *
 * IMPORTANT: the terminal uses a Monospaced TrueType font, so any panel that draws
 * with it MUST enable text antialiasing via hints(g). The plugin's other overlays
 * deliberately set TEXT_ANTIALIASING = OFF to keep the RuneScape pixel bitmap font
 * crisp; inheriting that convention makes the mono terminal text look jagged.
 */
final class TerminalKit
{
	static final Color BG      = new Color(0x08, 0x08, 0x0a);
	static final Color PANEL   = new Color(0x0d, 0x0d, 0x10);
	static final Color TITLEBG = new Color(0x16, 0x13, 0x0a);
	static final Color BORDER  = new Color(0x3a, 0x33, 0x1c);
	static final Color AMBER   = new Color(0xe8, 0xb8, 0x4b);
	static final Color AMBERHI = new Color(0xf6, 0xc9, 0x52);
	static final Color LABEL   = new Color(0x93, 0x8b, 0x68);
	static final Color DIM     = new Color(0x59, 0x54, 0x3f);
	static final Color GREEN   = new Color(0x55, 0xc4, 0x6a);
	static final Color RED     = new Color(0xf0, 0x56, 0x3f);
	static final Color GRID    = new Color(0x1c, 0x1b, 0x13);
	static final Color FLASH   = new Color(0x1e, 0x3a, 0x22);

	private TerminalKit() { }

	static Font mono(int s)  { return new Font(Font.MONOSPACED, Font.PLAIN, s); }
	static Font monoB(int s) { return new Font(Font.MONOSPACED, Font.BOLD, s); }

	/** Enable shape + TEXT antialiasing - required for the mono font to read clean. */
	static void hints(Graphics2D g)
	{
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
	}

	/** Draw s so its right edge ends at xr (tabular right-align). */
	static void rt(Graphics2D g, String text, int xr, int y)
	{
		// Translate at the primitive, so a label held in a variable (verdicts,
		// catch states) is covered as well as a literal. Item names, prices and
		// anything else with no entry pass straight through.
		final String s = I18n.t(text);
		final Font base = g.getFont();
		final Font use = I18n.fit(base, s);   // identity for Latin, so numbers keep the mono face
		if (use != base) { g.setFont(use); }
		g.drawString(s, xr - g.getFontMetrics().stringWidth(s), y);
		if (use != base) { g.setFont(base); }
	}

	/** Width of s in the face it will actually draw in (not the caller's, which
	 *  may be about to be swapped for a Japanese-capable one). */
	static int width(Graphics2D g, String text)
	{
		final String s = I18n.t(text);
		final Font use = I18n.fit(g.getFont(), s);
		return g.getFontMetrics(use).stringWidth(s);
	}

	/** drawString for text that may be translated: borrows a Japanese-capable
	 *  face only when the current one cannot draw the string, then puts the
	 *  caller's font back. */
	static void str(Graphics2D g, String text, int x, int y)
	{
		final String s = I18n.t(text);
		final Font base = g.getFont();
		final Font use = I18n.fit(base, s);
		if (use == base) { g.drawString(s, x, y); return; }
		g.setFont(use);
		g.drawString(s, x, y);
		g.setFont(base);
	}

	/** Panel frame + amber title strip; returns the content-start y. */
	static int panel(Graphics2D g, int x, int y, int w, int h, String title)
	{
		g.setColor(PANEL); g.fillRect(x, y, w, h);
		g.setColor(BORDER); g.setStroke(new BasicStroke(1f)); g.drawRect(x, y, w, h);
		g.setColor(TITLEBG); g.fillRect(x + 1, y + 1, w - 2, 17);
		final String ti = I18n.t(title);
		g.setFont(monoB(10)); g.setColor(AMBERHI); str(g, ti, x + 8, y + 13);
		g.setColor(GRID); g.drawLine(x + 1, y + 18, x + w - 1, y + 18);
		return y + 32;
	}

	/** Dim uppercase label with a right-aligned value below it. */
	static void cell(Graphics2D g, int x, int w, int y, String label, String value, Color vc)
	{
		// The label translates; the VALUE never does (prices and counts keep the
		// mono face the columns were measured in).
		final String lb = I18n.t(label);
		g.setFont(mono(9)); g.setColor(LABEL); str(g, lb, x, y);
		g.setFont(monoB(13)); g.setColor(vc); rt(g, value, x + w, y + 15);
	}

	static void chip(Graphics2D g, int x, int y, String label, Color fg)
	{
		final String s = I18n.t(label);
		g.setFont(monoB(10));
		final int w = width(g, s) + 10;
		g.setColor(new Color(0x20, 0x1a, 0x10)); g.fillRect(x, y - 10, w, 14);
		g.setColor(fg); str(g, s, x + 5, y);
	}

	static void spark(Graphics2D g, int x, int y, int w, int h, int seed, Color c)
	{
		final GeneralPath p = new GeneralPath();
		for (int i = 0; i <= 16; i++)
		{
			final double v = Math.sin((i + seed) / 2.3) * 0.5 + Math.sin((i + seed) / 5.7) * 0.5;
			final int px = x + i * w / 16, py = y + (int) ((0.5 - v / 2) * h);
			if (i == 0) { p.moveTo(px, py); } else { p.lineTo(px, py); }
		}
		g.setStroke(new BasicStroke(1.2f)); g.setColor(c); g.draw(p);
	}

	/** 4,266,644,991 - grouped, for the full cash readout. */
	static String commas(long v) { return String.format("%,d", v); }

	/** 4.27b / 805m / 41.0k - compact gp for tight columns. */
	static String gp(long v)
	{
		final long a = Math.abs(v);
		final String sign = v < 0 ? "-" : "";
		if (a >= 1_000_000_000L) { return sign + trim(a / 1e9) + "b"; }
		if (a >= 1_000_000L)     { return sign + trim(a / 1e6) + "m"; }
		if (a >= 1_000L)         { return sign + trim(a / 1e3) + "k"; }
		return Long.toString(v);
	}

	private static String trim(double d)
	{
		final String s = String.format("%.1f", d);
		return s.endsWith(".0") ? s.substring(0, s.length() - 2) : s;
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import java.util.List;

/**
 * The GE-anchored item intelligence card: painted to the left of the open
 * Grand Exchange offer interface while an item is selected. A tight window of
 * the traded corridor with your offer drawn on it, the live prints the plugin
 * has observed arriving (each poll where the insta price moved is a print),
 * and the measured read: fill odds at your price, after-tax outcome. Pure
 * painter over plain data so the headless harness renders it; the overlay
 * class feeds it live state and anchors it to the GE widget.
 */
final class GeItemInfoPainter
{
	/** One observed print: an insta price moving between polls. */
	static final class Print
	{
		long ts;          // epoch seconds
		long price;
		boolean buySide;  // true = insta-buy (high) moved, false = insta-sell (low)
		boolean yours;    // matched to one of your own logged fills
		boolean yoursBuy; // the matched fill's side (your sell offer being taken
		                  // surfaces as an insta-buy, so this is not buySide)

		Print(long ts, long price, boolean buySide)
		{
			this(ts, price, buySide, false, false);
		}

		Print(long ts, long price, boolean buySide, boolean yours, boolean yoursBuy)
		{
			this.ts = ts;
			this.price = price;
			this.buySide = buySide;
			this.yours = yours;
			this.yoursBuy = yoursBuy;
		}
	}

	/** Everything the card needs, as plain data. */
	static final class Context
	{
		String itemName;
		long[] youBuys = {};   // your active buy offer prices
		long[] youSells = {};  // your active sell offer prices
		String stateText;      // e.g. "B OK +26.2k"
		Color stateColor;
		String stateText2;     // second verdict when both sides are live
		Color stateColor2;
		ItemChart.Series series;
		String chartLabel;         // active timeframe tag drawn on the chart, e.g. "24h"
		List<Print> prints;        // newest last
		int tradeDepth = 10;       // how many recent prints the tape shows
		int tradesChartN = 0;      // >0: draw the last-N-trades tick chart instead of the corridor
		// Low/high (with timestamps) for the selected chart view, shown as the range
		// read: {highPrice, highTsSec, lowPrice, lowTsSec}. Null = not shown. The
		// view label reuses chartLabel (+ tradesChartN>0 for a trades view).
		long[] rangeRow;
		int fillPct = -1;          // measured odds at the board's prices, -1 unknown
		// Buy-limit read (terminal card LIMIT/RESET cells). total -1 = no published limit.
		long limitBought = -1;
		long limitTotal = -1;
		long limitResetMs = 0;     // epoch ms the 4h window's earliest buy rolls off
		// Hard ceiling for the terminal card's drawn height (canvas px), 0 = unbounded.
		// The card clamps its trade tape so it never draws over the chat input box.
		int maxHeight = 0;
		// Chart band height inside the terminal card. Short windows compress it
		// (down to 80) so the card still fits instead of losing the terminal skin.
		int chartH = 132;
		String outcomeText;        // bottom line, prebuilt by the caller
		Color outcomeColor;
		String outcomeText2;       // whole-offer line under it (qty math)
		Color outcomeColor2;
		long nowTs;
		// Your open position from the flip log: what you hold and paid.
		long lotQty;
		long lotCost;              // total gp paid
		long lotOpenedAtMs;
		// The individual lots behind those totals, oldest first: {qty, unit
		// cost, openedAt ms}. When they differ in price the holding line
		// itemises them instead of pretending one blended entry.
		long[][] lotEntries;

		long refSell()
		{
			return youSells.length > 0 ? youSells[0] : 0;
		}

		long refBuy()
		{
			return youBuys.length > 0 ? youBuys[0] : 0;
		}
	}

