/**
 * The two Grand Exchange chatbox integrations:
 *
 * 1) PRICE FILL: when the "Set a price for each item:" input opens, inject
 *    clickable lines with our engine's queue-jumping price for that side (and
 *    your break-even floor when selling a tracked position). A click pre-fills
 *    the input exactly as if typed: the user still presses Enter, so it stays
 *    one input action per click (the accepted pattern from approved Hub
 *    plugins: pre-fill via the mes-layer input varcstr, never submit).
 *
 * 2) SEARCH SUGGESTIONS: while the GE item search is EMPTY, feed our tracked
 *    items + top live flips into the client's native search-result buffer
 *    (GrandExchangeSearched consume + setGeSearchResultIds). The game renders
 *    them as ordinary clickable result rows and selecting one is 100% vanilla
 *    behavior. The moment the player types, we stand down and normal search
 *    takes over; clearing the input brings the suggestions back.
 *
 * Everything here runs on the client thread (the events arrive there; widget
 * injection is deferred one tick so the client finishes building the layer).
 */
class GeChatboxHelper
{
	private static final int VARC_INPUT_TYPE = 5;        // VarClientID.MESLAYERMODE
	private static final int VARC_INPUT_TEXT = 359;      // VarClientID.MESLAYERINPUT
	private static final int INPUT_TYPE_NUMERIC = 7;     // GE qty/price input
	private static final int INPUT_TYPE_GE_SEARCH = 14;  // GE item search
	private static final int SCRIPT_GE_SEARCHBOX_BUILT = 750;
	private static final int SETUP_SIDE_CHILD = 20;      // "Buy offer" / "Sell offer"
	private static final int MAX_SUGGESTIONS = 60;

	// The GE search proc only fires its searched event with a non-empty input,
	// so suggestions ride a sentinel search string (Quest Helper's technique).
	private static final String SENTINEL = "pc-flips";

	// Chatbox parchment is light: dark ink reads, gold does not (device-tested).
	private static final int INK = 0x800000;
	private static final int INK_HOVER = 0x11128e;

	private final Client client;
	private final ClientThread clientThread;
	private final PriceCheckConfig config;
	private final PriceCheckPlugin plugin;

	// Latest board + positions, pushed by the plugin's poller.
	private volatile List<FlipData> flips = Collections.emptyList();
	private volatile List<TrackedItem> tracked = Collections.emptyList();

	GeChatboxHelper(Client client, ClientThread clientThread, PriceCheckConfig config, PriceCheckPlugin plugin)
	{
		this.client = client;
		this.clientThread = clientThread;
		this.config = config;
		this.plugin = plugin;
	}

	void update(List<FlipData> flips, List<TrackedItem> tracked)
	{
		if (flips != null)
		{
			this.flips = flips;
		}
		if (tracked != null)
		{
			this.tracked = tracked;
		}
	}

	// ── 1) price fill ──

	void onVarClientIntChanged(VarClientIntChanged e)
	{
		if (e.getIndex() != VARC_INPUT_TYPE)
		{
			return;
		}
		// Search closed (item picked, escape, interface change): restore what the
		// suggestions mode touched. MES_TEXT and MES_TEXT2 are static widgets,
		// so a hidden flag would otherwise leak into the next thing that uses
		// the chatbox.
		if (suggestActive && client.getVarcIntValue(VARC_INPUT_TYPE) != INPUT_TYPE_GE_SEARCH)
		{
			standDown(false);
		}
		if (!config.geAssists())
		{
			return;
		}
		if (client.getVarcIntValue(VARC_INPUT_TYPE) != INPUT_TYPE_NUMERIC
			|| client.getWidget(InterfaceID.Chatbox.MES_TEXT) == null
			|| client.getWidget(InterfaceID.GeOffers.SETUP_DESC) == null)
		{
			return;
		}
		clientThread.invokeLater(this::injectGeInput);
	}

	private static final String PRICE_PROMPT = "Set a price for each item:";

	/** A GE-setup numeric box is open: the price box (matched by its prompt) or,
	 *  by elimination, the quantity box. Each injector self-guards, so only the
	 *  matching one draws. */
	private void injectGeInput()
	{
		injectPriceLines();
		injectQtyLine();
	}

	private static final java.util.regex.Pattern TRADED_PAT =
		java.util.regex.Pattern.compile("Actively traded price:\\s*([0-9,]+)");

	/** Clickable price lines in the "Set a price" input: the engine's pick + the
	 *  actively-traded price, then the low/high of the chart's selected view. Two
	 *  compact rows at the top so they sit above the game's centred prompt. Dark
	 *  ink; pre-fill only, the player still presses Enter. */
	private void injectPriceLines()
	{
		final Widget parent = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		final Widget prompt = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		final Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (parent == null || prompt == null || setup == null
			|| !PRICE_PROMPT.equals(prompt.getText()))
		{
			return;
		}
		final Widget side = setup.getChild(SETUP_SIDE_CHILD);
		final boolean isBuy = side != null && "Buy offer".equals(side.getText());
		final boolean isSell = side != null && "Sell offer".equals(side.getText());
		if (!isBuy && !isSell)
		{
			return;
		}
		final int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return;
		}
		final FlipData live = plugin.viewFor(itemId);
		final long rec = live == null ? -1 : (isBuy ? live.getBuy() : live.getSell());
		final long[] vr = plugin.viewRangeFor(itemId);
		if (rec <= 0 && vr == null)
		{
			return;
		}
		final int colR = 250;
		final int colW = 235;
		if (rec > 0)
		{
			addLine(parent, 10, 3, colW, I18n.f(isBuy ? "rec buy: %s" : "rec sell: %s", Fmt.full(rec)), rec);
		}
		final long traded = scanTraded(setup, 0);
		if (traded > 0)
		{
			addLine(parent, colR, 3, colW, I18n.f("traded: %s", Fmt.full(traded)), traded);
		}
		if (vr != null)
		{
			final PriceCheckPlugin.ChartTf tf = plugin.chartTf();
			final String vl = tf.label + (tf.isTrades() ? " trades" : "");
			if (vr[2] > 0)
			{
				addLine(parent, 10, 18, colW, I18n.f("%s low: %s", vl, Fmt.full(vr[2])), vr[2]);
			}
			if (vr[0] > 0)
			{
				addLine(parent, colR, 18, colW, I18n.f("%s high: %s", vl, Fmt.full(vr[0])), vr[0]);
			}
		}
	}

	private long scanTraded(Widget w, int depth)
	{
		if (w == null || depth > 6)
		{
			return 0;
		}
		final String t = w.getText();
		if (t != null)
		{
			final java.util.regex.Matcher m = TRADED_PAT.matcher(t);
			if (m.find())
			{
				try
				{
					return Long.parseLong(m.group(1).replace(",", ""));
				}
				catch (NumberFormatException ignored)
				{
					// keep scanning
				}
			}
		}
		for (final Widget[] set : new Widget[][]{w.getStaticChildren(), w.getDynamicChildren(), w.getNestedChildren()})
		{
			if (set == null)
			{
				continue;
			}
			for (final Widget c : set)
			{
				final long v = scanTraded(c, depth + 1);
				if (v > 0)
				{
					return v;
				}
			}
		}
		return 0;
	}

	/**
	 * Put our text on a GE widget. Japanese cannot go INTO the widget - the
	 * client's fonts have no kana, so it would render as nothing - so the widget
	 * is left blank (it keeps its bounds, action and hover) and GeLabelOverlay
	 * paints the line over it instead.
	 */
	private void setLabel(Widget w, String text)
	{
		if (I18n.japanese())
		{
			w.setText("");
			GeLabelOverlay.note(w, text);
			return;
		}
		w.setText(text);
	}

	private void addLine(Widget parent, int x, int y, int width, String label, long value)
	{
		addLine(parent, x, y, width, label, value, "Set price");
	}

	private void addLine(Widget parent, int x, int y, int width, String label, long value, String action)
	{
		final Widget w = parent.createChild(-1, WidgetType.TEXT);
		setLabel(w, label);
		w.setTextColor(INK);
		w.setFontId(FontID.VERDANA_11_BOLD);
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(15);
		w.setXTextAlignment(WidgetTextAlignment.LEFT);
		w.setHasListener(true);
		w.setAction(0, action);
		w.setOnOpListener((JavaScriptCallback) ev -> fillInput(value));
		w.setOnMouseRepeatListener((JavaScriptCallback) ev -> w.setTextColor(INK_HOVER));
		w.setOnMouseLeaveListener((JavaScriptCallback) ev -> w.setTextColor(INK));
		w.revalidate();
	}

	/** A non-clickable info line (e.g. "limit reached"); dark ink, no listener. */
	private void addNote(Widget parent, int x, int y, int width, String label)
	{
		final Widget w = parent.createChild(-1, WidgetType.TEXT);
		setLabel(w, label);
		w.setTextColor(INK);
		w.setFontId(FontID.VERDANA_11_BOLD);
		w.setOriginalX(x);
		w.setOriginalY(y);
		w.setOriginalWidth(width);
		w.setOriginalHeight(15);
		w.setXTextAlignment(WidgetTextAlignment.LEFT);
		w.revalidate();
	}

	/** Clickable "buy limit: N left" in the GE quantity box on a buy offer, so one
	 *  click fills your remaining 4h buy limit (you still press Enter). When the
	 *  limit is spent it shows a non-clickable note with the reset countdown. Only
	 *  the quantity box reaches here (the price box is matched first); buy side and
	 *  a published limit are both required. */
	private void injectQtyLine()
	{
		final Widget parent = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		final Widget prompt = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		final Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (parent == null || prompt == null || setup == null || PRICE_PROMPT.equals(prompt.getText()))
		{
			return;
		}
		final Widget side = setup.getChild(SETUP_SIDE_CHILD);
		if (side == null || !"Buy offer".equals(side.getText()))
		{
			return;   // buy limits only bind when buying
		}
		final int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return;
		}
		final long[] lim = plugin.buyLimitInfo(itemId);
		if (lim == null || lim[1] <= 0)
		{
			return;   // no published buy limit for this item: nothing to cap
		}
		final long total = lim[1];
		final long bought = Math.max(0, lim[0]);
		final long remaining = Math.max(0, total - bought);
		if (remaining > 0)
		{
			addLine(parent, 10, 3, 300,
				I18n.f("buy limit: %s left of %s", Fmt.full(remaining), Fmt.full(total)), remaining, "Set quantity");
		}
		else
		{
			final long left = lim[2] > 0 ? lim[2] - System.currentTimeMillis() : 0;
			addNote(parent, 10, 3, 300,
				left > 0 ? I18n.f("4h buy limit reached - resets in %s", Fmt.duration(left))
					: I18n.t("4h buy limit reached"));
		}
	}

	// Pre-fill only: write the digits into the input buffer + its on-screen echo
	// (the '*' is the client's fake caret). The user presses Enter to submit.
	private void fillInput(long price)
	{
		final Widget echo = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (echo != null)
		{
			echo.setText(price + "*");
		}
		client.setVarcStrValue(VARC_INPUT_TEXT, String.valueOf(price));
	}

	/**
	 * Hotkey entry: pre-fill the context-appropriate value into an open GE input,
	 * pre-fill-only (the player still presses Enter), client thread only.
	 *   - price box: our recommended price for that side.
	 *   - quantity box on a buy: your remaining 4h buy limit, so one press never
	 *     queues more than you can actually buy.
	 * Returns true when it filled something, false otherwise.
	 */
	boolean fillRecommended()
	{
		if (client.getVarcIntValue(VARC_INPUT_TYPE) != INPUT_TYPE_NUMERIC)
		{
			return false;   // no numeric input open
		}
		final Widget prompt = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		final Widget setup = client.getWidget(InterfaceID.GeOffers.SETUP);
		if (prompt == null || setup == null)
		{
			return false;   // not a GE offer-setup input
		}
		final Widget side = setup.getChild(SETUP_SIDE_CHILD);
		final boolean isBuy = side != null && "Buy offer".equals(side.getText());
		final boolean isSell = side != null && "Sell offer".equals(side.getText());
		if (!isBuy && !isSell)
		{
			return false;
		}
		final int itemId = client.getVarpValue(VarPlayerID.TRADINGPOST_SEARCH);
		if (itemId <= 0)
		{
			return false;
		}
		if (PRICE_PROMPT.equals(prompt.getText()))
		{
			final FlipData live = plugin.viewFor(itemId);
			final long price = live == null ? -1 : (isBuy ? live.getBuy() : live.getSell());
			if (price <= 0)
			{
				return false;   // no live data yet: fill nothing rather than a wrong price
			}
			fillInput(price);
			return true;
		}
		// Quantity box (by elimination). Only the buy side has a limit to cap.
		if (!isBuy)
		{
			return false;
		}
		final long[] lim = plugin.buyLimitInfo(itemId);
		if (lim == null || lim[1] <= 0)
		{
			return false;   // no published limit
		}
		final long remaining = Math.max(0, lim[1] - Math.max(0, lim[0]));
		if (remaining <= 0)
		{
			return false;   // limit spent: don't fill 0
		}
		fillInput(remaining);
		return true;
	}

	private TrackedItem trackedFor(int geId)
	{
		for (TrackedItem t : tracked)
		{
			if (t.getGeId() == geId)
			{
				return t;
			}
		}
		return null;
	}

	// ── 2) search suggestions ──
	//
	// The search proc only fires GrandExchangeSearched when the input is
	// non-empty (device-confirmed), so a fresh-open auto-populate needs a
	// sentinel search string: on open we put SENTINEL in the input buffer,
	// hide the input echo (the player shouldn't see "pc-flips*"), replay the
	// box's own key listener to run the search, and consume the event to feed
	// our ids into the client's native result buffer. A dark-ink line under
	// the title hands back to normal typing on click.

	private boolean suggestActive = false;
	private Widget banner;

	void onScriptPostFired(ScriptPostFired e)
	{
		if (e.getScriptId() != SCRIPT_GE_SEARCHBOX_BUILT || !config.geAssists())
		{
			return;
		}
		// Defer one tick so the freshly built search layer is complete.
		clientThread.invokeLater(this::activateSuggestions);
	}

	private void activateSuggestions()
	{
		if (client.getVarcIntValue(VARC_INPUT_TYPE) != INPUT_TYPE_GE_SEARCH)
		{
			return;
		}
		if (nativePreviousSearchShown())
		{
			// The game's own "Previous search" panel (the Show-last-searched
			// setting) owns the empty-input layout; drawing over it garbles
			// both. Yield, and hand back everything we took: banner, title,
			// echo, and the sentinel if it is ours.
			standDown(SENTINEL.equals(client.getVarcStrValue(VARC_INPUT_TEXT)));
			return;
		}
		final String cur = client.getVarcStrValue(VARC_INPUT_TEXT);
		if (cur != null && !cur.isEmpty() && !cur.equals(SENTINEL))
		{
			// A real search is in the buffer: don't hijack it, and if we were
			// active a moment ago make sure nothing of ours lingers over it.
			if (suggestActive || banner != null)
			{
				standDown(false);
			}
			return;
		}
		if (suggestionIds().length == 0)
		{
			if (suggestActive || banner != null)
			{
				standDown(false);
			}
			return;   // nothing to show yet (no key / board still loading)
		}
		client.setVarcStrValue(VARC_INPUT_TEXT, SENTINEL);
		suggestActive = true;
		// The banner owns the title row while we are active: hide BOTH native
		// occupants (the "What would you like to buy?" title and the input
		// echo), or whichever one the game draws bleeds through our text.
		final Widget title = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (title != null)
		{
			title.setHidden(true);
		}
		final Widget echo = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (echo != null)
		{
			echo.setHidden(true);
		}
		injectSearchBanner();
		replaySearch();
	}

	/**
	 * Give the title row back to the game: banner gone, title and echo
	 * restored, and the sentinel cleared when asked. Safe to call in any
	 * state; every path that stops suggesting funnels through here so no
	 * combination of rebuilds can leave our banner over native text.
	 */
	private void standDown(boolean clearSentinel)
	{
		suggestActive = false;
		if (banner != null)
		{
			banner.setHidden(true);
			banner = null;
		}
		final Widget title = client.getWidget(InterfaceID.Chatbox.MES_TEXT);
		if (title != null)
		{
			title.setHidden(false);
		}
		final Widget echo = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (echo != null)
		{
			echo.setHidden(false);
		}
		if (clearSentinel)
		{
			final String cur = client.getVarcStrValue(VARC_INPUT_TEXT);
			if (cur != null && cur.startsWith(SENTINEL))
			{
				client.setVarcStrValue(VARC_INPUT_TEXT, cur.substring(SENTINEL.length()));
			}
		}
	}

	/** Plugin disable: put the chatbox back exactly as the client expects it.
	 *  Without this, a hidden input echo and the sentinel string survive into
	 *  vanilla GE search until the interface is rebuilt. */
	void shutdown()
	{
		clientThread.invoke(() ->
		{
			if (!suggestActive)
			{
				return;
			}
			standDown(true);
			replaySearch();
		});
	}

	// Back to vanilla: clear the sentinel, unhide the input, rerun the search
	// so the normal "start typing" panel returns.
	private void deactivateSuggestions()
	{
		standDown(true);
		client.setVarcStrValue(VARC_INPUT_TEXT, "");
		final Widget echo = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (echo != null)
		{
			echo.setText("*");
		}
		replaySearch();
	}

	/** True when the chatbox is showing the game's previous-search panel. */
	private boolean nativePreviousSearchShown()
	{
		final Widget layer = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		if (layer == null)
		{
			return false;
		}
		final Widget[][] sets = { layer.getStaticChildren(), layer.getDynamicChildren(), layer.getNestedChildren() };
		for (final Widget[] set : sets)
		{
			if (set == null)
			{
				continue;
			}
			for (final Widget w : set)
			{
				if (w == null || w.isHidden())
				{
					continue;
				}
				final String t = w.getText();
				if (t != null && (t.contains("Previous search") || t.contains("Show last searched")))
				{
					return true;
				}
			}
		}
		return false;
	}

	private void injectSearchBanner()
	{
		final Widget parent = client.getWidget(InterfaceID.Chatbox.MES_LAYER);
		if (parent == null)
		{
			return;
		}
		// One banner at a time: a rebuild can re-activate before the old child
		// is torn down, and a second copy doubles the text.
		if (banner != null)
		{
			banner.setHidden(true);
		}
		final Widget w = parent.createChild(-1, WidgetType.TEXT);
		banner = w;
		setLabel(w, I18n.t("Your tracked items + best flips, ranked. Click here to type a search instead."));
		w.setTextColor(INK);
		w.setFontId(FontID.VERDANA_11_BOLD);
		w.setOriginalX(10);
		w.setOriginalY(4);
		w.setOriginalHeight(15);
		w.setXTextAlignment(WidgetTextAlignment.LEFT);
		w.setWidthMode(WidgetSizeMode.MINUS);
		w.setHasListener(true);
		w.setAction(0, "Search normally");
		w.setOnOpListener((JavaScriptCallback) ev -> deactivateSuggestions());
		w.setOnMouseRepeatListener((JavaScriptCallback) ev -> w.setTextColor(INK_HOVER));
		w.setOnMouseLeaveListener((JavaScriptCallback) ev -> w.setTextColor(INK));
		w.revalidate();
	}

	private void replaySearch()
	{
		if (client.getVarcIntValue(VARC_INPUT_TYPE) != INPUT_TYPE_GE_SEARCH)
		{
			return;
		}
		final Widget box = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
		if (box == null)
		{
			return;
		}
		final Object[] onKey = box.getOnKeyListener();
		if (onKey == null)
		{
			return;
		}
		client.runScript(onKey);
	}

	void onGrandExchangeSearched(GrandExchangeSearched e)
	{
		if (!config.geAssists() || e.isConsumed())
		{
			return;   // another plugin (bank tags etc.) got there first
		}
		final String input = client.getVarcStrValue(VARC_INPUT_TEXT);
		if (SENTINEL.equals(input))
		{
			final short[] ids = suggestionIds();
			if (ids.length == 0)
			{
				return;
			}
			e.consume();
			client.setGeSearchResultIndex(0);
			client.setGeSearchResultCount(ids.length);
			client.setGeSearchResultIds(ids);
			return;
		}
		// If keystrokes reach the hidden input while suggestions are up, the
		// buffer becomes "pc-flipsX". Strip the sentinel, restore the echo, and
		// rerun so the player lands in a normal search for exactly what they
		// typed (one repaint behind, corrected on the replay).
		if (suggestActive && input != null && input.startsWith(SENTINEL))
		{
			final String typed = input.substring(SENTINEL.length());
			suggestActive = false;
			client.setVarcStrValue(VARC_INPUT_TEXT, typed);
			final Widget echo = client.getWidget(InterfaceID.Chatbox.MES_TEXT2);
			if (echo != null)
			{
				echo.setText(typed + "*");
				echo.setHidden(false);
			}
			clientThread.invokeLater(this::replaySearch);
		}
	}

	// Tracked positions first (you manage those), then the board by EV. The
	// result buffer takes shorts: ids above that range can't be suggested.
	private short[] suggestionIds()
	{
		final Set<Integer> out = new LinkedHashSet<>();
		for (TrackedItem t : tracked)
		{
			if (t.getGeId() > 0 && t.getGeId() <= Short.MAX_VALUE)
			{
				out.add(t.getGeId());
			}
		}
		for (FlipData f : flips)
		{
			if (out.size() >= MAX_SUGGESTIONS)
			{
				break;
			}
			if (f.getGeId() > 0 && f.getGeId() <= Short.MAX_VALUE)
			{
				out.add(f.getGeId());
			}
		}
		final short[] arr = new short[out.size()];
		int i = 0;
		for (int id : out)
		{
			arr[i++] = (short) id;
		}
		return arr;
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.geom.Path2D;
import java.util.Arrays;

/**
 * Shared display pipeline for the evidence charts. Raw 5m windows on a busy
 * commodity render as a picket fence, so everything drawn goes through
 * volume-weighted BUCKETS first: each bucket averages its windows' high and
 * low with their side volumes as weights, keeps its extremes for the wick
 * envelope, and remembers whether the average after-tax spread paid. The
 * painters stay dumb; this owns aggregation, scale, and the corridor.
 */
final class ChartKit
{
	static final Color CORRIDOR = new Color(255, 255, 255, 26);
	static final Color CORRIDOR_PAID = new Color(0xe6, 0xc6, 0x67, 78);
	static final Color ENVELOPE = new Color(255, 255, 255, 12);
	static final Color LINE_HIGH = new Color(0x5d, 0xf2, 0x9a, 185);
	static final Color LINE_LOW = new Color(0xf2, 0x6b, 0x6d, 185);
	static final Color GRID = new Color(255, 255, 255, 14);
	static final Color FILL_CELL = new Color(0xe6, 0xc6, 0x67, 150);
	static final Color FILL_BUY = new Color(0x5d, 0xf2, 0x9a, 150);
	static final Color FILL_SELL = new Color(0xf2, 0x6b, 0x6d, 150);
	static final Color GUIDE_HIGH = new Color(0x5d, 0xf2, 0x9a, 64);
	static final Color GUIDE_LOW = new Color(0xf2, 0x6b, 0x6d, 64);

	/** Bucketed, paint-ready view of a Series. */
	static final class Display
	{
		int n;
		long[] ts;        // bucket midpoint, epoch seconds
		double[] hi;      // volume-weighted avg insta-buy print
		double[] lo;      // volume-weighted avg insta-sell print
		double[] hiMax;   // wick extremes
		double[] loMin;
		long[] vol;       // traded units in the bucket, both sides
		long[] volHi;     // insta-buy side units (aggressive buyers)
		long[] volLo;     // insta-sell side units (aggressive sellers)
		boolean[] paid;   // avg after-tax spread positive
		long tMin;
		long tMax;
		long pMin;        // robust drawn price range
		long pMax;
		long volMax;
		// The newest print on each side, straight from the raw windows: the
		// live market edges a trader adjusts against.
		long lastHigh;
		long lastHighTs;
		long lastLow;
		long lastLowTs;
	}

	private ChartKit()
	{
	}

	/** Bucket a series for a plot of the given pixel width (one bucket ~3px).
	 * extraPrices (your offer, quotes) are folded into the scale. */
	static Display build(ItemChart.Series s, int plotW, long... extraPrices)
	{
		if (s == null || s.ts == null || s.ts.length < 2)
		{
			return null;
		}
		final int nB = Math.max(24, Math.min(96, plotW / 3));
		final int len = s.ts.length;
		final Display d = new Display();
		d.n = nB;
		d.ts = new long[nB];
		d.hi = new double[nB];
		d.lo = new double[nB];
		d.hiMax = new double[nB];
		d.loMin = new double[nB];
		d.vol = new long[nB];
		d.volHi = new long[nB];
		d.volLo = new long[nB];
		d.paid = new boolean[nB];
		d.tMin = s.ts[0];
		d.tMax = s.ts[len - 1];
		final double span = Math.max(1, d.tMax - d.tMin);

		final double[] wHi = new double[nB];
		final double[] wLo = new double[nB];
		for (int i = 0; i < len; i++)
		{
			final int b = (int) Math.min(nB - 1, (s.ts[i] - d.tMin) / span * nB);
			final long hv = s.hvol != null ? Math.max(s.hvol[i], 0) : 0;
			final long lv = s.lvol != null ? Math.max(s.lvol[i], 0) : 0;
			if (s.high[i] > 0)
			{
				final double w = hv + 1;
				d.hi[b] += s.high[i] * w;
				wHi[b] += w;
				d.hiMax[b] = Math.max(d.hiMax[b], s.high[i]);
			}
			if (s.low[i] > 0)
			{
				final double w = lv + 1;
				d.lo[b] += s.low[i] * w;
				wLo[b] += w;
				d.loMin[b] = d.loMin[b] == 0 ? s.low[i] : Math.min(d.loMin[b], s.low[i]);
			}
			d.vol[b] += hv + lv;
			d.volHi[b] += hv;
			d.volLo[b] += lv;
		}
		for (int b = 0; b < nB; b++)
		{
			d.ts[b] = d.tMin + (long) ((b + 0.5) / nB * span);
			d.hi[b] = wHi[b] > 0 ? d.hi[b] / wHi[b] : 0;
			d.lo[b] = wLo[b] > 0 ? d.lo[b] / wLo[b] : 0;
			d.paid[b] = d.hi[b] > 0 && d.lo[b] > 0
				&& GeTax.net((long) d.lo[b] + 1, (long) d.hi[b] - 1) > 0;
			d.volMax = Math.max(d.volMax, d.vol[b]);
		}
		for (int i = len - 1; i >= 0; i--)
		{
			if (d.lastHigh == 0 && s.high[i] > 0)
			{
				d.lastHigh = s.high[i];
				d.lastHighTs = s.ts[i];
			}
			if (d.lastLow == 0 && s.low[i] > 0)
			{
				d.lastLow = s.low[i];
				d.lastLowTs = s.ts[i];
			}
			if (d.lastHigh != 0 && d.lastLow != 0)
			{
				break;
			}
		}

		// Robust scale: 2nd..98th percentile of drawn values, then widened to
		// admit the caller's price lines. One spiked window cannot crush the
		// whole day into a ribbon.
		final double[] vals = new double[nB * 2];
		int nv = 0;
		for (int b = 0; b < nB; b++)
		{
			if (d.hi[b] > 0) { vals[nv++] = d.hi[b]; }
			if (d.lo[b] > 0) { vals[nv++] = d.lo[b]; }
		}
		if (nv < 2)
		{
			return null;
		}
		final double[] used = Arrays.copyOf(vals, nv);
		Arrays.sort(used);
		long lo = (long) used[(int) (nv * 0.02)];
		long hi = (long) used[Math.min(nv - 1, (int) (nv * 0.98))];
		for (final long p : extraPrices)
		{
			if (p > 0)
			{
				lo = Math.min(lo, p);
				hi = Math.max(hi, p);
			}
		}
		if (lo >= hi)
		{
			lo = hi - 1;
		}
		final long pad = Math.max(1, (hi - lo) / 10);
		d.pMin = lo - pad;
		d.pMax = hi + pad;
		return d;
	}

	static float x(Display d, long ts, int x0, int w)
	{
		return x0 + (ts - d.tMin) / (float) Math.max(1, d.tMax - d.tMin) * w;
	}

	static float y(Display d, double price, int y0, int h)
	{
		final double f = (price - d.pMin) / (double) Math.max(1, d.pMax - d.pMin);
		return (float) (y0 + h - Math.max(0, Math.min(1, f)) * h);
	}

	/** The corridor, wick envelope, and edge lines. Quiet buckets BRIDGE: the
	 * shape carries across them from traded bucket to traded bucket instead of
	 * shattering into a picket fence on sparse items. The volume strip is what
	 * says where trading actually paused. */
	static void paintCorridor(Graphics2D g2, Display d, int x0, int y0, int w, int h)
	{
		// The traded buckets, in order; every segment joins two of them.
		final int[] tb = new int[d.n];
		int nt = 0;
		for (int b = 0; b < d.n; b++)
		{
			if (traded(d, b))
			{
				tb[nt++] = b;
			}
		}
		if (nt < 2)
		{
			return;
		}
		// Wick envelope first, faintest layer.
		for (int i = 0; i < nt - 1; i++)
		{
			final int a = tb[i];
			final int b = tb[i + 1];
			final Path2D env = new Path2D.Float();
			env.moveTo(x(d, d.ts[a], x0, w), y(d, d.hiMax[a], y0, h));
			env.lineTo(x(d, d.ts[b], x0, w), y(d, d.hiMax[b], y0, h));
			env.lineTo(x(d, d.ts[b], x0, w), y(d, d.loMin[b], y0, h));
			env.lineTo(x(d, d.ts[a], x0, w), y(d, d.loMin[a], y0, h));
			env.closePath();
			g2.setColor(ENVELOPE);
			g2.fill(env);
		}
		// The corridor between the weighted averages, gold where it paid.
		for (int i = 0; i < nt - 1; i++)
		{
			final int a = tb[i];
			final int b = tb[i + 1];
			final Path2D p = new Path2D.Float();
			p.moveTo(x(d, d.ts[a], x0, w), y(d, d.hi[a], y0, h));
			p.lineTo(x(d, d.ts[b], x0, w), y(d, d.hi[b], y0, h));
			p.lineTo(x(d, d.ts[b], x0, w), y(d, d.lo[b], y0, h));
			p.lineTo(x(d, d.ts[a], x0, w), y(d, d.lo[a], y0, h));
			p.closePath();
			g2.setColor(d.paid[a] && d.paid[b] ? CORRIDOR_PAID : CORRIDOR);
			g2.fill(p);
		}
		g2.setStroke(new BasicStroke(1.2f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
		paintEdge(g2, d, true, LINE_HIGH, x0, y0, w, h);
		paintEdge(g2, d, false, LINE_LOW, x0, y0, w, h);
	}

	private static boolean traded(Display d, int b)
	{
		return d.hi[b] > 0 && d.lo[b] > 0;
	}

	private static void paintEdge(Graphics2D g2, Display d, boolean high, Color c, int x0, int y0, int w, int h)
	{
		// One continuous line through every traded bucket; quiet buckets are
		// bridged, not broken, matching the corridor fill.
		g2.setColor(c);
		Path2D p = null;
		for (int b = 0; b < d.n; b++)
		{
			final double v = high ? d.hi[b] : d.lo[b];
			if (v <= 0)
			{
				continue;
			}
			final float px = x(d, d.ts[b], x0, w);
			final float py = y(d, v, y0, h);
			if (p == null) { p = new Path2D.Float(); p.moveTo(px, py); }
			else { p.lineTo(px, py); }
		}
		if (p != null)
		{
			g2.draw(p);
		}
	}

	/** Three labeled price gridlines in the right gutter. */
	static void paintPriceGrid(Graphics2D g2, Display d, FontMetrics fm, int x0, int y0, int w, int h, Color labelColor)
	{
		for (int i = 0; i < 3; i++)
		{
			// i: 0 = bottom, 1 = middle, 2 = top of the range.
			final long p = d.pMin + (d.pMax - d.pMin) * i / 2;
			final int yy = Math.round(y(d, p, y0, h));
			g2.setColor(GRID);
			g2.drawLine(x0, yy, x0 + w, yy);
			g2.setColor(labelColor);
			// Clamp so the top label never clips above the chart.
			g2.drawString(Fmt.compact(p), x0 + w + 4, Math.max(y0 + fm.getAscent() - 2, yy + 4));
		}
	}

	/** Per-bucket traded-volume strip: brightness is relative volume, colour is
	 * who was aggressing. Green = insta-buys dominated the bucket, red =
	 * insta-sells did, gold = balanced. The day's pressure reads left to right. */
	static void paintFillStrip(Graphics2D g2, Display d, int x0, int y, int w, int cellH)
	{
		if (d.volMax <= 0)
		{
			return;
		}
		final float bw = w / (float) d.n;
		for (int b = 0; b < d.n; b++)
		{
			if (d.vol[b] <= 0)
			{
				continue;
			}
			final Color base = d.volHi[b] > d.volLo[b] * 1.5 ? FILL_BUY
				: d.volLo[b] > d.volHi[b] * 1.5 ? FILL_SELL : FILL_CELL;
			final int a = 40 + (int) (115 * Math.min(1.0, d.vol[b] / (double) d.volMax));
			g2.setColor(new Color(base.getRed(), base.getGreen(), base.getBlue(), a));
			g2.fillRect(Math.round(x0 + b * bw), y, Math.max(1, Math.round(bw) - 1), cellH);
		}
	}

	/** Stacked per-bucket volume bars: bar height carries how much traded
	 * (robust p95-based scale, so one dump cannot flatten the whole day) and
	 * the split carries who aggressed, green insta-buys under red insta-sells.
	 * Returns the units-per-full-bar scale so callers can label the pane. */
	static long paintVolumeBars(Graphics2D g2, Display d, int x0, int y, int w, int h)
	{
		if (d.volMax <= 0)
		{
			return 0;
		}
		final long[] nz = new long[d.n];
		int nv = 0;
		for (int b = 0; b < d.n; b++)
		{
			if (d.vol[b] > 0)
			{
				nz[nv++] = d.vol[b];
			}
		}
		final long[] used = Arrays.copyOf(nz, nv);
		Arrays.sort(used);
		final long p95 = used[Math.min(nv - 1, (int) (nv * 0.95))];
		final long cap = Math.max(1, Math.min(d.volMax, p95 * 2));
		final float bw = w / (float) d.n;
		g2.setColor(GRID);
		g2.drawLine(x0, y + h, x0 + w, y + h);
		for (int b = 0; b < d.n; b++)
		{
			if (d.vol[b] <= 0)
			{
				continue;
			}
			final int hb = Math.max(2, Math.round(h * Math.min(1f, d.vol[b] / (float) cap)));
			final int bx = Math.round(x0 + b * bw);
			final int bpx = Math.max(1, Math.round(bw) - 1);
			final long sides = d.volHi[b] + d.volLo[b];
			final int hg = sides > 0 ? Math.round(hb * (d.volHi[b] / (float) sides)) : hb / 2;
			if (hb - hg > 0)
			{
				g2.setColor(FILL_SELL);
				g2.fillRect(bx, y + h - hb, bpx, hb - hg);
			}
			if (hg > 0)
			{
				g2.setColor(FILL_BUY);
				g2.fillRect(bx, y + h - hg, bpx, hg);
			}
		}
		return cap;
	}

	/** Dotted full-width guides at the live market edges (the newest print on
	 * each side), so the whole day reads against where the market is NOW. */
	static void paintLevelGuides(Graphics2D g2, Display d, int x0, int y0, int w, int h)
	{
		final java.awt.Stroke prev = g2.getStroke();
		g2.setStroke(new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{1f, 3f}, 0f));
		if (d.lastHigh > d.pMin && d.lastHigh < d.pMax)
		{
			final int yy = Math.round(y(d, d.lastHigh, y0, h));
			g2.setColor(GUIDE_HIGH);
			g2.drawLine(x0, yy, x0 + w, yy);
		}
		if (d.lastLow > d.pMin && d.lastLow < d.pMax)
		{
			final int yy = Math.round(y(d, d.lastLow, y0, h));
			g2.setColor(GUIDE_LOW);
			g2.drawLine(x0, yy, x0 + w, yy);
		}
		g2.setStroke(prev);
	}

	/** Vertical rhythm lines at the six-hour UTC boundaries: time structure
	 * without labels, for surfaces too tight to carry an hour axis. */
	static void paintTimeGrid(Graphics2D g2, Display d, int x0, int y0, int w, int h)
	{
		g2.setColor(GRID);
		for (long t = ((d.tMin / 21600) + 1) * 21600; t < d.tMax; t += 21600)
		{
			final int xx = Math.round(x(d, t, x0, w));
			g2.drawLine(xx, y0, xx, y0 + h);
		}
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.awt.Stroke;
import java.util.List;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Paints each active offer's advice directly onto its Grand Exchange slot: a
 * status-coloured frame plus a bar across the bottom with the live status and
 * margin ("RAISE +12.9k", "OK +26.2k", "MARGIN DEAD"). The bar sits over the
 * slot's static offer-price caption, never the fill progress bar, so nothing
 * you actually watch is hidden. Attention hierarchy: DEAD greys the whole
 * slot, action states (RAISE/DROP/FALLING) get a bright frame + a direction
 * triangle, ON_TRACK stays dim with its margin quietly readable. Slot
 * geometry: widgets 465:7 .. 465:14, live only while 465:0 is up.
 */
class OfferAdvisorSlotOverlay extends Overlay
{
	private static final int GE_GROUP = 465;
	private static final int GE_WINDOW_CHILD = 0;
	private static final int FIRST_SLOT_CHILD = 7;
	private static final int SLOTS = 8;
	private static final int BAR_H = 15;

	private static final Stroke FRAME = new BasicStroke(2f);
	private static final Stroke HALO = new BasicStroke(4f);

	private final Client client;
	private final PriceCheckPlugin plugin;
	private final PriceCheckConfig config;

	OfferAdvisorSlotOverlay(Client client, PriceCheckPlugin plugin, PriceCheckConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.deskOn())
		{
			return null;
		}
		// Hold Shift to peek at the untouched slots (price captions included).
		if (client.isKeyPressed(KeyCode.KC_SHIFT))
		{
			return null;
		}
		final Widget window = client.getWidget(GE_GROUP, GE_WINDOW_CHILD);
		if (window == null || window.isHidden())
		{
			return null;
		}
		final List<OfferAdvice> advice = plugin.getAdvice();
		if (advice.isEmpty())
		{
			return null;
		}

		final OfferAdvice[] bySlot = new OfferAdvice[SLOTS];
		for (OfferAdvice a : advice)
		{
			final int s = a.getSlot();
			if (s >= 0 && s < SLOTS)
			{
				bySlot[s] = a;
			}
		}

		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = g.getFontMetrics();

		for (int i = 0; i < SLOTS; i++)
		{
			final OfferAdvice a = bySlot[i];
			if (a == null || a.getKind() == OfferAdvice.Kind.NO_DATA)
			{
				continue;
			}
			final String label = I18n.verdict(a.getShortText());
			if (label == null || label.isEmpty())
			{
				continue;
			}
			final Widget slot = client.getWidget(GE_GROUP, FIRST_SLOT_CHILD + i);
			if (slot == null || slot.isHidden())
			{
				continue;
			}
			final Rectangle b = slot.getBounds();
			if (b == null || b.width < 24 || b.height < 24)
			{
				continue;
			}
			// Proximity to a real fill: how far this offer's price sits from the
			// last DETECTED trade on the side that would take it, in tenths of a
			// percent. -1 == no real print to measure (never a fake 0).
			int closeTenths = -1;
			final TrackedOffer t = plugin.trackedAt(i);
			if (t != null && t.isActive() && a.getKind() != OfferAdvice.Kind.DEAD)
			{
				final PriceCheckApiClient.SeriesData sd = plugin.cardSeriesFor(t.getItemId());
				closeTenths = closenessTenths(t, sd);
			}
			final long quietMs = plugin.slotQuietMs(i);
			paintSlot(g, fm, b, a.getKind(), a.getColor(), label, closeTenths, quietMs);
		}
		return null;
	}

	private void paintSlot(Graphics2D g, FontMetrics fm, Rectangle b, OfferAdvice.Kind kind, Color col, String label, int closeTenths, long quietMs)
	{
		final boolean dead = kind == OfferAdvice.Kind.DEAD;
		final boolean onTrack = kind == OfferAdvice.Kind.ON_TRACK;
		final boolean collect = kind == OfferAdvice.Kind.COLLECT;
		// A patient HOLD needs no action, so it reads calm (dim frame) and, because
		// it is neither RAISE nor DROP/FALLING, draws no direction arrow.
		final boolean quiet = onTrack || collect || kind == OfferAdvice.Kind.HOLD;

		// DEAD greys the whole slot so it reads from across the room.
		if (dead)
		{
			g.setColor(new Color(0, 0, 0, 70));
			g.fillRoundRect(b.x + 2, b.y + 2, b.width - 4, b.height - 4, 8, 8);
		}

		// Frame: dark halo pass, then the colour pass (bright for action, dim for quiet).
		g.setStroke(HALO);
		g.setColor(new Color(0, 0, 0, 140));
		g.drawRoundRect(b.x + 1, b.y + 1, b.width - 3, b.height - 3, 8, 8);
		g.setStroke(FRAME);
		g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), quiet ? 120 : 230));
		g.drawRoundRect(b.x + 1, b.y + 1, b.width - 3, b.height - 3, 8, 8);

		// Status bar: rounded-bottom, square top to meet the frame flush. It
		// covers the static offer-price caption (recoverable by opening the
		// slot), not the progress bar above it.
		final int barX = b.x + 2;
		final int barY = b.y + b.height - BAR_H - 2;
		final int barW = b.width - 4;
		g.setColor(Palette.INK);
		g.fillRoundRect(barX, barY, barW, BAR_H, 6, 6);
		g.fillRect(barX, barY, barW, 6);
		// Closeness wash from the left edge: fuller the nearer the offer sits to
		// a real fill (seated fills the bar), fading out as the gap widens. The
		// same honest gap as the number, never a modelled probability.
		if (!dead && closeTenths >= 0)
		{
			final int cap = 30;   // a 3.0% gap or worse leaves no wash
			final int near = cap - Math.min(closeTenths, cap);
			if (near > 0)
			{
				g.setColor(new Color(col.getRed(), col.getGreen(), col.getBlue(), 26));
				final int washW = Math.max(4, barW * near / cap);
				g.fillRoundRect(barX, barY, washW, BAR_H, 6, 6);
			}
		}
		g.setColor(col);
		g.fillRect(barX, barY, barW, 2);   // signature coloured top edge

		// Direction triangle for the actionable states (drawn, not font glyphs).
		final boolean up = kind == OfferAdvice.Kind.RAISE_BUY;
		final boolean down = kind == OfferAdvice.Kind.DROP_SELL || kind == OfferAdvice.Kind.FALLING;
		final int triW = (up || down) ? 11 : 0;   // 7px glyph + 4px gap

		String text = label;
		final int maxTextW = barW - 4 - triW;
		if (fm.stringWidth(text) > maxTextW)
		{
			text = fitToWidth(fm, text, maxTextW);
		}
		final int totalW = triW + fm.stringWidth(text);
		int cx = barX + Math.max(1, (barW - totalW) / 2);
		final int midY = barY + 2 + (BAR_H - 2) / 2;

		if (up || down)
		{
			drawTriangle(g, cx, midY, up, col);
			cx += triW;
		}
		final int ty = barY + 2 + ((BAR_H - 2 - (fm.getAscent() + fm.getDescent())) / 2) + fm.getAscent();
		final java.awt.Font vb = g.getFont();
		final java.awt.Font vu = I18n.fit(vb, text);
		if (vu != vb) { g.setFont(vu); }
		g.setColor(new Color(0, 0, 0, 205));
		g.drawString(text, cx + 1, ty + 1);
		g.setColor(col);
		g.drawString(text, cx, ty);
		if (vu != vb) { g.setFont(vb); }

		// Right segment: proximity to a real fill. Never contradicts the centre
		// verdict - the seated "at mkt" shows only on non-action slots, and AMBER
		// stays reserved for the quiet-time caution. Nothing at all when there is
		// no real print to measure.
		String side = null;
		Color sideCol = Palette.SUBTLE_CANVAS;
		final boolean action = up || down;   // up/down are already computed above
		final String quietStr = (quiet && quietMs >= 10 * 60_000L) ? quietLabel(quietMs) : null;
		if (!dead && closeTenths > 0)
		{
			side = (closeTenths / 10) + "." + (closeTenths % 10) + "%";
			// grey -> gold as it nears a fill; AMBER is the caution colour, not "close".
			sideCol = closeTenths <= 10 ? Palette.GOLD : Palette.SUBTLE_CANVAS;
		}
		else if (!dead && closeTenths == 0 && !action)
		{
			// Seated: fills now. Only on non-action slots so green never fights a
			// RAISE/DROP/FALLING verdict. A seated-but-dry patient offer shows its wait.
			side = quietStr != null ? quietStr : "at mkt";
			sideCol = quietStr != null ? Palette.AMBER : Palette.GREEN;
		}
		else if (quietStr != null)
		{
			// No usable closeness (no print, DEAD, or a seated action slot): quiet time.
			side = quietStr;
			sideCol = Palette.AMBER;
		}
		if (side != null)
		{
			final int sw = fm.stringWidth(side);
			final int sx = barX + barW - sw - 5;
			if (sx > cx + fm.stringWidth(text) + 8)
			{
				g.setColor(new Color(0, 0, 0, 205));
				g.drawString(side, sx + 1, ty + 1);
				g.setColor(sideCol);
				g.drawString(side, sx, ty);
			}
		}
	}

	// 7x5 filled triangle, vertically centred on midY, with a shadow pass.
	private static void drawTriangle(Graphics2D g, int x, int midY, boolean up, Color col)
	{
		final int[] xs = { x, x + 3, x + 6 };
		final int[] ys = up ? new int[]{ midY + 3, midY - 3, midY + 3 } : new int[]{ midY - 3, midY + 3, midY - 3 };
		final int[] xsh = { x + 1, x + 4, x + 7 };
		final int[] ysh = up ? new int[]{ midY + 4, midY - 2, midY + 4 } : new int[]{ midY - 2, midY + 4, midY - 2 };
		g.setColor(new Color(0, 0, 0, 205));
		g.fillPolygon(xsh, ysh, 3);
		g.setColor(col);
		g.fillPolygon(xs, ys, 3);
	}

	private static String fitToWidth(FontMetrics fm, String s, int maxW)
	{
		if (fm.stringWidth(s) <= maxW)
		{
			return s;
		}
		while (s.length() > 1 && fm.stringWidth(s + "..") > maxW)
		{
			s = s.substring(0, s.length() - 1);
		}
		return s + "..";
	}

	// A fill-side print older than this in REAL time is treated as no live
	// reference. 24h keeps once-or-twice-a-day illiquid items readable (the card
	// seeds prints back a week for them) while suppressing genuinely dead sides.
	private static final long STALE_SECS = 24 * 3600L;

	/**
	 * How close an offer's price sits to the last DETECTED trade on the side that
	 * would fill it, in tenths of a percent of that trade. A SELL fills as buyers
	 * print UP at/through the ask -> measured against the last insta-buy print (ah
	 * at the newest window with hv&gt;0); a BUY fills as sellers print DOWN at/through
	 * the bid -> the last insta-sell print (al at the newest window with lv&gt;0).
	 * Returns: -1 unknown (no series/volume, unpriced offer, or too stale); 0
	 * seated (at/through the print, fills now); &gt;0 the gap in tenths of a percent
	 * (21 == 2.1%). A plain gap to a real print, never an invented probability.
	 */
	private static int closenessTenths(TrackedOffer t, PriceCheckApiClient.SeriesData sd)
	{
		if (t == null || sd == null)
		{
			return -1;
		}
		final long yourPrice = t.getPrice();
		if (yourPrice <= 0)
		{
			return -1;   // unpriced/returned offer deserializes to 0 - never a real gap
		}
		final boolean buying = t.isBuying();
		final int idx = buying ? lastPrintIdx(sd.al, sd.lv) : lastPrintIdx(sd.ah, sd.hv);
		if (idx < 0)
		{
			return -1;   // no observed trade on the side that would fill this offer
		}
		final long trade = buying ? sd.al[idx] : sd.ah[idx];
		if (trade <= 0)
		{
			return -1;
		}
		// Age the print against the wall clock (not the newest cached window) so a
		// globally stale cache cannot pass off an old print as live. If ts is
		// missing or mis-sized, freshness is unverifiable -> report unknown.
		if (sd.ts == null || idx >= sd.ts.length
			|| System.currentTimeMillis() / 1000L - sd.ts[idx] > STALE_SECS)
		{
			return -1;
		}
		// Seated (gap <= 0): the market already prints at/through your price.
		final long gap = buying ? (trade - yourPrice) : (yourPrice - trade);
		if (gap <= 0)
		{
			return 0;
		}
		return (int) Math.round(gap * 1000.0D / trade);
	}

	/** Newest index carrying a real trade: positive volume AND a real price. -1 if none. */
	private static int lastPrintIdx(long[] price, int[] vol)
	{
		if (price == null || vol == null)
		{
			return -1;
		}
		final int n = Math.min(price.length, vol.length);
		for (int i = n - 1; i >= 0; i--)
		{
			if (vol[i] > 0 && price[i] > 0)
			{
				return i;
			}
		}
		return -1;
	}

	private static String quietLabel(long quietMs)
	{
		final long m = quietMs / 60_000L;
		return m >= 60 ? (m / 60) + "h" + (m % 60 > 0 ? " " + (m % 60) + "m" : "") : m + "m";
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import java.time.LocalTime;
import java.time.format.DateTimeFormatter;
import net.runelite.api.Client;
import net.runelite.api.GrandExchangeOffer;
import net.runelite.api.GrandExchangeOfferState;
import net.runelite.api.InventoryID;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Terminal status bar - a thin trading-terminal command strip docked to the top edge of
 * the Grand Exchange window: brand, cash, used offer slots, world, and a live
 * clock. Opt-in via config.terminalStatusBar(). Uses only client-readable state
 * (no server call), so it works for free keys too. First panel of the terminal
 * desk; the shared look lives in TerminalKit.
 */
class TerminalStatusOverlay extends Overlay
{
	private static final int COINS_ID = 995;
	private static final int GAP = 6;
	private static final int BAR_H = 30;   // unscaled design height
	private static final DateTimeFormatter CLOCK = DateTimeFormatter.ofPattern("HH:mm:ss");

	private final Client client;
	private final PriceCheckPlugin plugin;
	private final PriceCheckConfig config;

	TerminalStatusOverlay(Client client, PriceCheckPlugin plugin, PriceCheckConfig config)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		if (!plugin.deskOn())
		{
			return null;
		}
		final Rectangle ge = plugin.geGridBounds();
		if (ge == null || !plugin.isGrandExchangeOpen())
		{
			return null;
		}

		// The status bar is a fixed-height header, not a data panel: it does NOT
		// follow overlayScale() (Large/big mode) - scaling it up shrinks the fit
		// width and squeezes out fields. It always spans the GE width at 1:1.
		final double scale = 1.0;
		final int h = (int) Math.round(BAR_H * scale);
		final int w = ge.width;                       // span the GE width
		final int x = ge.x;
		int y = ge.y - h - GAP;                        // dock to the TOP edge
		if (y < 4)
		{
			y = 4;
		}

		// Save the AA hints (the pixel-font overlays run with them OFF; we need ON
		// for the mono font, and we restore so we don't affect the next overlay).
		final Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Object taa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		g.translate(x, y);
		g.scale(scale, scale);
		try
		{
			final FlipLogEngine.Summary sum = plugin.flipSummary();
			paintBar(g, (int) Math.round(w / scale), BAR_H, cash(), usedSlots(),
				client.getWorld(), LocalTime.now().format(CLOCK),
				sum != null ? sum.todayProfit : Long.MIN_VALUE);
			// A fixed desk mode the window cannot hold explains itself instead
			// of silently downgrading: one amber line under the bar with the
			// real deficit and the fix.
			final String notice = plugin.deskNotice();
			if (notice != null)
			{
				TerminalKit.hints(g);
				g.setFont(TerminalKit.mono(10));
				final int tw = g.getFontMetrics().stringWidth(notice) + 14;
				final int ny = BAR_H + 3;
				g.setColor(TerminalKit.PANEL);
				g.fillRect(0, ny, Math.min(tw, (int) Math.round(w / scale)), 16);
				g.setColor(TerminalKit.BORDER);
				g.drawRect(0, ny, Math.min(tw, (int) Math.round(w / scale)), 16);
				g.setColor(TerminalKit.AMBERHI);
				g.drawString(notice, 7, ny + 12);
			}
		}
		finally
		{
			g.scale(1.0 / scale, 1.0 / scale);
			g.translate(-x, -y);
			if (aa != null) { g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa); }
			if (taa != null) { g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, taa); }
		}
		// The bar is a desk panel too: report it so the collision watchdog
		// sees the full composition (the notice line rides inside its rect).
		plugin.noteDeskRect("statusbar", x, y, w, h);
		return null;
	}

	/** Pure drawing (0,0-origin, w x h) so the preview harness can render it headless.
	 *  Fully metrics-driven and self-clamping: fields are only drawn if they fit
	 *  before the right-pinned LIVE/clock block, so it never overlaps on a narrow
	 *  (single-offer) GE window - it just shows fewer fields. */
	static void paintBar(Graphics2D g, int w, int h, long cash, int slots, int world, String clock, long pnlToday)
	{
		TerminalKit.hints(g);
		g.setColor(TerminalKit.PANEL);
		g.fillRect(0, 0, w, h);
		g.setColor(TerminalKit.BORDER);
		g.drawRect(0, 0, w, h);

		// brand
		g.setFont(TerminalKit.monoB(14));
		g.setColor(TerminalKit.AMBERHI);
		g.drawString("PRICECHECK", 12, 20);
		final int brandW = g.getFontMetrics().stringWidth("PRICECHECK");
		g.setFont(TerminalKit.mono(9));
		g.setColor(TerminalKit.DIM);
		TerminalKit.str(g, I18n.t("ENGINE"), 12 + brandW + 8, 20);
		final int engineW = TerminalKit.width(g, I18n.t("ENGINE"));

		// RIGHT block first: clock (right-pinned) + LIVE label + dot. Compute its
		// left edge so the flowing fields on the left can stop before it.
		g.setFont(TerminalKit.monoB(12));
		final int clockW = g.getFontMetrics().stringWidth(clock);
		g.setColor(TerminalKit.AMBER);
		g.drawString(clock, w - 12 - clockW, 20);
		g.setFont(TerminalKit.mono(10));
		final int liveW = TerminalKit.width(g, I18n.t("LIVE"));
		final int liveX = w - 12 - clockW - 10 - liveW;
		g.setColor(TerminalKit.LABEL);
		TerminalKit.str(g, I18n.t("LIVE"), liveX, 19);
		g.setColor(TerminalKit.GREEN);
		g.fillOval(liveX - 11, 9, 6, 6);
		final int rEdge = liveX - 11 - 14;   // fields must end before here

		// LEFT fields, left-flowing, clamped so they never cross rEdge.
		int fx = 12 + brandW + 8 + engineW + 22;
		fx = field(g, fx, rEdge, I18n.t("CASH"), TerminalKit.commas(cash), TerminalKit.AMBER);
		fx = field(g, fx, rEdge, I18n.t("SLOTS"), slots + "/8", slots >= 8 ? TerminalKit.RED : TerminalKit.AMBER);
		fx = field(g, fx, rEdge, I18n.t("WORLD"), Integer.toString(world), TerminalKit.AMBER);
		if (pnlToday != Long.MIN_VALUE)
		{
			fx = field(g, fx, rEdge, I18n.t("P&L TODAY"),
				(pnlToday >= 0 ? "+" : "-") + TerminalKit.gp(Math.abs(pnlToday)),
				pnlToday >= 0 ? TerminalKit.GREEN : TerminalKit.RED);
		}
	}

	private static int field(Graphics2D g, int x, int rEdge, String label, String value, Color vc)
	{
		g.setFont(I18n.fit(TerminalKit.mono(9), label));
		final int lw = g.getFontMetrics().stringWidth(label);
		g.setFont(TerminalKit.monoB(13));
		final int vw = g.getFontMetrics().stringWidth(value);
		final int fieldW = Math.max(lw, vw);
		if (x + fieldW > rEdge)
		{
			return x;   // no room on this window width - skip, never overlap
		}
		g.setFont(TerminalKit.mono(9));
		g.setColor(TerminalKit.LABEL);
		TerminalKit.str(g, label, x, 12);
		g.setFont(TerminalKit.monoB(13));
		g.setColor(vc);
		g.drawString(value, x, 25);
		return x + fieldW + 22;
	}

	private long cash()
	{
		final ItemContainer inv = client.getItemContainer(InventoryID.INVENTORY);
		if (inv == null)
		{
			return 0L;
		}
		long c = 0L;
		for (final Item it : inv.getItems())
		{
			if (it != null && it.getId() == COINS_ID)
			{
				c += it.getQuantity();
			}
		}
		return c;
	}

	private int usedSlots()
	{
		final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
		if (offers == null)
		{
			return 0;
		}
		int n = 0;
		for (final GrandExchangeOffer o : offers)
		{
			if (o != null && o.getState() != GrandExchangeOfferState.EMPTY)
			{
				n++;
			}
		}
		return n;
	}
}

