	private void renderCatches()
	{
		catchList.removeAll();
		if (false)
		{
			catchList.add(note("Dump catches are off. Enable “Show dump catches” in Setup to watch measured reversion plays here.", Palette.SUBTLE));
			catchList.add(Box.createVerticalGlue());
			I18n.applyFonts(catchList);
			catchList.revalidate();
			catchList.repaint();
			return;
		}
		// Rank strongest first; drop faded movers (no play left on them).
		final List<CatchData> rows = new ArrayList<>();
		for (final CatchData c : lastCatches)
		{
			if (c != null && !"faded".equals(c.getState()))
			{
				rows.add(c);
			}
		}
		rows.sort((a, b) -> Integer.compare(b.getRating(), a.getRating()));

		if (rows.isEmpty())
		{
			// Honest empty state: do not claim it is scanning-but-quiet when the
			// board simply is not sending movers.
			catchList.add(note("The dump-catch board comes online when the measured detector is live.", Palette.SUBTLE));
		}
		else
		{
			catchList.add(sectionHeader(I18n.f("Catches · %d", rows.size())));
			for (final CatchData c : rows)
			{
				catchList.add(catchRow(c));
				if (c.getGeId() == expandedCatchId)
				{
					catchList.add(gap(2));
					catchList.add(catchExpand(c));
				}
				catchList.add(gap(5));
			}
		}
		catchList.add(Box.createVerticalGlue());
		I18n.applyFonts(catchList);
		catchList.revalidate();
		catchList.repaint();
	}

	// ── catch row: icon | name + state chip / displaced + bid>target / read ──
	// Package-visible for the headless preview harness. Every measured claim is
	// gated: loud CATCH reads only when the row earns it, a still-falling dump
	// reads "FALLING KNIFE - skip", and the projected profit is an explicit,
	// taxed, contingent estimate, never a guarantee.
	JPanel catchRow(CatchData c)
	{
		final boolean loud = c.loudEligible(CATCH_BAR);
		final boolean knife = c.isKnife() || "knife".equals(c.getState());
		final boolean fresh = !c.isCatchable() && !knife
			&& (c.getMinutesRunning() > 0 && c.getMinutesRunning() < 5 || "watch".equals(c.getState()) && c.getMinutesRunning() < 5);

		final JPanel rowP = new JPanel(new BorderLayout(6, 0));
		rowP.setBackground(CARD);
		rowP.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		rowP.setAlignmentX(Component.LEFT_ALIGNMENT);
		if (c.getReasons() != null && !c.getReasons().isEmpty())
		{
			rowP.setToolTipText(escHtml(String.join(", ", c.getReasons())));
		}

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(28, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null) { itemManager.getImage(c.getGeId()).addTo(icon); }

		// Line 1: name + a state chip.
		final JLabel name = new JLabel("<html><body style='width:118px'><b>" + escHtml(c.getName()) + "</b></body></html>");
		name.setForeground(Color.WHITE);
		final String chipText;
		final Color chipCol;
		if (loud) { chipText = "CATCH"; chipCol = Palette.GREEN; }
		else if (knife) { chipText = "SKIP"; chipCol = Palette.RED; }
		else if (fresh) { chipText = "FORMING"; chipCol = Palette.AMBER; }
		else if ("recovering".equals(c.getState())) { chipText = "RECOVER"; chipCol = Palette.GOLD; }
		else { chipText = "WATCH"; chipCol = Palette.AMBER; }
		final JLabel chip = pill(chipText, chipCol);
		final JPanel line1 = row();
		line1.add(name, BorderLayout.CENTER);
		line1.add(chip, BorderLayout.EAST);

		// Line 2: the factual displacement, and (loud only) the entry->target.
		final JLabel displaced = mono(I18n.f("displaced %s", pctSigned(c.getPctMove())), Palette.LIGHT);
		final JPanel line2 = row();
		line2.add(displaced, BorderLayout.WEST);
		if (loud && c.getBid() > 0 && c.getTarget() > c.getBid())
		{
			final JPanel bt = new JPanel();
			bt.setLayout(new BoxLayout(bt, BoxLayout.X_AXIS));
			bt.setOpaque(false);
			bt.add(mono(Fmt.compact(c.getBid()), Palette.AMBER));
			bt.add(Box.createRigidArea(new Dimension(5, 0)));
			bt.add(new Chevron(Palette.SUBTLE));
			bt.add(Box.createRigidArea(new Dimension(5, 0)));
			bt.add(mono(Fmt.compact(c.getTarget()), Palette.GREEN));
			line2.add(bt, BorderLayout.EAST);
		}

		// Line 3: the honest read.
		final JPanel line3 = row();
		if (knife)
		{
			final JLabel skip = mono(I18n.t("FALLING KNIFE - skip"), Palette.RED);
			line3.add(skip, BorderLayout.WEST);
		}
		else if (loud)
		{
			// Measured, backed read: the Wilson fraction (or count) + hold time.
			line3.add(mono(c.bouncesText() + " · " + c.holdText(), Palette.SUBTLE), BorderLayout.WEST);
			// Conservative, taxed, contingent projection off the shown target.
			final long each = GeTax.net(c.getBid(), c.getTarget());
			if (each != 0 && c.getBid() > 0 && c.getTarget() > 0)
			{
				final long est = each * Math.max(1, c.getCatchQty());
				final JLabel profit = mono(I18n.f("%s est", signedGp(est)), est >= 0 ? Palette.GREEN : Palette.RED);
				profit.setHorizontalAlignment(SwingConstants.RIGHT);
				profit.setToolTipText(I18n.t("Conservative half-recovery target, taxed. Only if it reverts - never guaranteed."));
				line3.add(profit, BorderLayout.EAST);
			}
		}
		else
		{
			// Not backed: no measured claims, no invented odds.
			line3.add(mono(c.bouncesText() + " · " + c.holdText(), Palette.SUBTLE), BorderLayout.WEST);
		}

		final JPanel center = new JPanel(new BorderLayout());
		center.setOpaque(false);
		center.add(line1, BorderLayout.NORTH);
		final JPanel lower = new JPanel(new BorderLayout());
		lower.setOpaque(false);
		lower.add(line2, BorderLayout.NORTH);
		lower.add(line3, BorderLayout.SOUTH);
		center.add(lower, BorderLayout.SOUTH);

		rowP.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		rowP.addMouseListener(new MouseAdapter()
		{
			public void mouseEntered(MouseEvent e) { rowP.setBackground(CARD_HOVER); }
			public void mouseExited(MouseEvent e) { rowP.setBackground(CARD); }

			public void mousePressed(MouseEvent e)
			{
				// The row toggles its evidence chart. The state chip on the right
				// is a plain label, not a control, so it has nothing to consume;
				// any interactive mark added here later must keep its own listener
				// (see flipRow's track mark).
				expandedCatchId = expandedCatchId == c.getGeId() ? 0 : c.getGeId();
				renderCatches();
			}
		});

		rowP.add(icon, BorderLayout.WEST);
		rowP.add(center, BorderLayout.CENTER);
		rowP.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowP.getPreferredSize().height));
		return rowP;
	}

	/** The expanded evidence chart + read under a clicked catch row. */
	private JPanel catchExpand(CatchData c)
	{
		final JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(CARD);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);

		// Chart: same construction the flips chart uses; the supplier fetches and
		// caches on demand for any item, movers included.
		final PriceCheckApiClient.SeriesData sd = seriesSupplier != null ? seriesSupplier.apply(c.getGeId()) : null;
		if (sd == null || sd.ts == null || sd.ts.length < 2)
		{
			final JLabel wait = mono(I18n.t("Loading chart…"), Palette.SUBTLE);
			wait.setAlignmentX(Component.LEFT_ALIGNMENT);
			card.add(wait);
			// The supplier schedules the fetch; repaint shortly to pick it up.
			final javax.swing.Timer t = new javax.swing.Timer(1200, e -> renderCatches());
			t.setRepeats(false);
			t.start();
		}
		else
		{
			final ItemChart.Series s = new ItemChart.Series();
			s.ts = sd.ts;
			s.high = sd.ah;
			s.low = sd.al;
			s.hvol = sd.hv;
			s.lvol = sd.lv;
			// Paint the entry and (contingent) recovery target as the quote lines.
			s.quoteBuy = c.getBid();
			s.quoteSell = c.getTarget();
			s.fillPct = sd.fillPct;
			final ItemChart chart = new ItemChart(s, 206, 150);
			final JPanel chartWrap = new JPanel(new BorderLayout());
			chartWrap.setOpaque(false);
			chartWrap.setAlignmentX(Component.LEFT_ALIGNMENT);
			chartWrap.add(chart, BorderLayout.CENTER);
			chartWrap.setMaximumSize(new Dimension(Integer.MAX_VALUE, 156));
			card.add(chartWrap);
		}

		card.add(gap(4));
		card.add(hairline());
		card.add(gap(3));

		final boolean loud = c.loudEligible(CATCH_BAR);
		final boolean knife = c.isKnife() || "knife".equals(c.getState());

		// Factual displacement always.
		card.add(catchKv("Displaced", pctSigned(c.getPctMove()), Palette.LIGHT));
		if (c.getBid() > 0)
		{
			card.add(catchKv("Entry", Fmt.full(c.getBid()), Color.WHITE));
		}
		if (c.getTarget() > 0)
		{
			// Conservative, taxed, half-recovery level: contingent, never a promise.
			final JPanel t = catchKv("Recover to", Fmt.full(c.getTarget()), Palette.GREEN);
			t.setToolTipText(I18n.t("Conservative half-recovery target, taxed. Only if it reverts - never guaranteed."));
			card.add(t);
		}

		if (knife)
		{
			card.add(catchKv("Read", "FALLING KNIFE - skip", Palette.RED));
		}
		else if (loud && c.getBid() > 0 && c.getTarget() > 0)
		{
			// Taxed, contingent projection off the shown target - matches the row.
			final long each = GeTax.net(c.getBid(), c.getTarget());
			if (each != 0)
			{
				final long est = each * Math.max(1, c.getCatchQty());
				final JPanel p = catchKv("Est. profit", I18n.f("%s est", signedGp(est)), est >= 0 ? Palette.GREEN : Palette.RED);
				p.setToolTipText(I18n.t("Conservative half-recovery target, taxed. Only if it reverts - never guaranteed."));
				card.add(p);
			}
			if (c.getRoi() != 0)
			{
				card.add(catchKv("ROI", I18n.f("%s est", pctSigned(c.getRoi())), c.getRoi() >= 0 ? Palette.GREEN : Palette.RED));
			}
			if (c.getCatchQty() > 0)
			{
				card.add(catchKv("Suggested size", Fmt.full(c.getCatchQty()), Palette.SUBTLE));
			}
		}

		// Measured base rate + hold, honesty-gated by CatchData's own helpers:
		// only a measured, non-thin, 20+ trial row shows the Wilson fraction and a
		// real median hold; anything else reads "est." with no invented odds.
		card.add(catchKv("Reversion", (c.isMeasured() && c.trialsN() >= 20) ? c.bouncesText() : "est.", Palette.SUBTLE));
		card.add(catchKv("Exp. hold", c.holdText(), Palette.SUBTLE));

		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, card.getPreferredSize().height));
		return card;
	}

	/** A labelled read line for the catch expand: subtle key, coloured value. */
	private JPanel catchKv(String k, String v, Color col)
	{
		k = I18n.t(k);
		v = I18n.t(v);
		final JPanel p = row();
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		final JLabel kl = new JLabel(k);
		kl.setForeground(Palette.SUBTLE);
		kl.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		final JLabel vl = mono(v, col);
		vl.setHorizontalAlignment(SwingConstants.RIGHT);
		p.add(kl, BorderLayout.WEST);
		p.add(vl, BorderLayout.EAST);
		return p;
	}

	/** Signed compact gp: "+5k", "-12.4m". Never "+-5k". */
	private static String signedGp(long v)
	{
		return (v >= 0 ? "+" : "-") + Fmt.compact(Math.abs(v));
	}

