	void setAccount(AccountInfo acct)
	{
		SwingUtilities.invokeLater(() ->
		{
			if (acct == null)
			{
				return;   // keep the last good card on a blip
			}
			acctName.setText(acct.getUsername() != null ? acct.getUsername() : "PriceCheck member");
			final String plan = acct.getPlan() == null ? "" : acct.getPlan();
			final String pill = acct.isTrial() ? "TRIAL"
				: !acct.isPremium() ? "FREE"
				: ("pro".equals(plan) || "premium".equals(plan)) ? "TRADER PRO" : "TRADER";
			acctPlan.setText(" " + pill + " ");
			// License line: what the plan is doing and when it runs out. "Renews"
			// for a live subscription, "left" for comped/prepaid time, no date talk
			// for a lifetime grant. The watchlist count rides along at the end.
			String lic;
			if (acct.isTrial())
			{
				lic = I18n.f("Trial · day %d of %d · %dm left today", Math.max(1, acct.getTrialDay()),
					Math.max(1, acct.getTrialDays()), acct.getTrialRemainingMin());
			}
			else if (!acct.isPremium())
			{
				lic = I18n.t("Free plan");
			}
			else if (acct.getExpiresAt() == null || acct.getExpiresAt() <= 0)
			{
				lic = I18n.t("Lifetime license");
			}
			else
			{
				final long msLeft = acct.getExpiresAt() - System.currentTimeMillis();
				final long days = Math.max(0, (msLeft + 86_399_999L) / 86_400_000L);
				final boolean renews = "stripe".equals(acct.getSource());
				if (msLeft <= 0)
				{
					lic = I18n.t("License expired");
				}
				else if (msLeft < 48 * 3_600_000L)
				{
					// Short windows (trials) read in hours, not "1 day".
					final long hours = Math.max(1, msLeft / 3_600_000L);
					lic = renews ? I18n.f("Renews in %d hours", hours) : I18n.f("%d hours left", hours);
				}
				else
				{
					lic = renews ? I18n.f("Renews in %d days", days) : I18n.f("%d days left", days);
				}
			}
			final int n = acct.getTrackedCount();
			acctSub.setText(I18n.f("%s · watching %d items", lic, n));
			acctSub.setToolTipText(I18n.t("Watching = your tracked-margins watchlist (the + button on flip rows); live GE offers show on the Flips tab and the in-game overlays."));
			if (acct.getKeyPrefix() != null) { keyPrefixLabel.setText(acct.getKeyPrefix()); }
		});
	}

	// keep the config-dialog and the Settings tab consistent without write loops
	void syncSettings()
	{
		SwingUtilities.invokeLater(() ->
		{
			settingsMuted = true;
			if (syncToggle.isSelected() != config.syncFlipLog()) { syncToggle.setSelected(config.syncFlipLog()); }
			final boolean deskOnNow = config.deskMode() != PriceCheckConfig.DeskMode.OFF;
			if (advisorToggle.isSelected() != deskOnNow) { advisorToggle.setSelected(deskOnNow); }
			if (!minEvSpinner.getValue().equals(config.minEvPerHrK())) { minEvSpinner.setValue(config.minEvPerHrK()); }
			settingsMuted = false;
		});
	}

	private void setDot(Color c, String tip)
	{
		keyDot.setColor(c);
		keyDot.setToolTipText(tip);
