	// ── render the flips tab ──
	private void render()
	{
		list.removeAll();

		final Set<Integer> trackedIds = new HashSet<>();
		for (TrackedItem t : lastTracked) { trackedIds.add(t.getGeId()); }

		final String q = search.getText().trim();
		final boolean searching = q.length() >= 2;

		if (authState != PriceCheckApiClient.AuthState.OK && !searching)
		{
			list.add(emptyState());
			list.add(Box.createVerticalGlue());
			I18n.applyFonts(list);
			list.revalidate();
			list.repaint();
			return;
		}

		// Tracking section
		if (!searching && !lastTracked.isEmpty())
		{
			list.add(sectionHeader(I18n.f("Tracking · %d", lastTracked.size())));
			for (TrackedItem t : lastTracked) { list.add(trackingCard(t)); list.add(gap(6)); }
			list.add(gap(6));
		}

		// Flips / search
		final List<FlipData> shown = new ArrayList<>();
		boolean pending = false;
		if (searching)
		{
			if (q.equals(searchResultsQuery)) { shown.addAll(searchResults); }
			else { pending = true; }
		}
		else
		{
			for (FlipData f : lastFlips)
			{
				if (minEvPerHrK > 0 && f.getEvPerHr() < minEvPerHrK * 1000L) { continue; }
				shown.add(f);
			}
		}

		final String header = searching
			? (pending ? I18n.f("Searching \"%s\"…", q) : I18n.f("%d match \"%s\"", shown.size(), q))
			: (minEvPerHrK > 0 ? I18n.f("%d flips · %dk+/hr", shown.size(), minEvPerHrK)
				: I18n.f("%d flips · by EV/hr", shown.size()));
		list.add(sectionHeader(header));

		if (authState == PriceCheckApiClient.AuthState.ERROR)
		{
			list.add(note("Reconnecting…", Palette.AMBER));
		}

		if (pending)
		{
			// searching icon on the field; nothing else to show yet
		}
		else if (shown.isEmpty())
		{
			list.add(note(searching ? "No items match." : "No flips right now.", Palette.SUBTLE));
		}
		else
		{
			for (FlipData f : shown)
			{
				list.add(flipRow(f, trackedIds.contains(f.getGeId())));
				if (f.getGeId() == expandedChartId)
				{
					list.add(gap(2));
					list.add(chartCard(f));
				}
				list.add(gap(5));
			}
		}

		list.add(Box.createVerticalGlue());
		I18n.applyFonts(list);
		list.revalidate();
		list.repaint();
	}

	/** The expanded evidence chart under a clicked board row. */
	private JPanel chartCard(FlipData f)
	{
		final JPanel card = new JPanel(new BorderLayout());
		card.setBackground(CARD);
		card.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		final PriceCheckApiClient.SeriesData sd = seriesSupplier != null ? seriesSupplier.apply(f.getGeId()) : null;
		if (sd == null || sd.ts == null || sd.ts.length < 2)
		{
			final JLabel wait = new JLabel(I18n.t("Loading day chart…"));
			wait.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
			wait.setForeground(Palette.SUBTLE);
			card.add(wait, BorderLayout.CENTER);
			card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 34));
			// The supplier schedules the fetch; repaint shortly to pick it up.
			final javax.swing.Timer t = new javax.swing.Timer(1200, e -> render());
			t.setRepeats(false);
			t.start();
			return card;
		}
		final ItemChart.Series s = new ItemChart.Series();
		s.ts = sd.ts;
		s.high = sd.ah;
		s.low = sd.al;
		s.hvol = sd.hv;
		s.lvol = sd.lv;
		s.quoteBuy = f.getBuy();
		s.quoteSell = f.getSell();
		s.fillPct = sd.fillPct;
		// Your own logged fills on this item, exact prices from the flip log.
		final FlipLogEngine.Summary log = lastLogSummary;
		if (log != null && log.recent != null)
		{
			final java.util.List<long[]> marks = new ArrayList<>();
			for (final FlipLogEngine.Flip fl : log.recent)
			{
				if (fl.itemId != f.getGeId() || fl.qty <= 0)
				{
					continue;
				}
				marks.add(new long[]{fl.openedAt / 1000L, fl.buyGross / fl.qty, 1});
				marks.add(new long[]{fl.closedAt / 1000L, fl.sellGross / fl.qty, 0});
			}
			if (!marks.isEmpty())
			{
				s.markTs = new long[marks.size()];
				s.markPrice = new long[marks.size()];
				s.markBuy = new boolean[marks.size()];
				for (int i = 0; i < marks.size(); i++)
				{
					s.markTs[i] = marks.get(i)[0];
					s.markPrice[i] = marks.get(i)[1];
					s.markBuy[i] = marks.get(i)[2] == 1;
				}
			}
		}
		final ItemChart chart = new ItemChart(s, 206, 150);
		card.add(chart, BorderLayout.CENTER);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 168));
		return card;
	}

	// ── flip row: icon | name (wraps) / buy>sell+profit / EV | track toggle ──
	// Package-visible for the headless preview harness.
	JPanel flipRow(FlipData f, boolean tracked)
	{
		final JPanel rowP = new JPanel(new BorderLayout(6, 0));
		rowP.setBackground(CARD);
		rowP.setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
		rowP.setAlignmentX(Component.LEFT_ALIGNMENT);

		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(28, 32));
		icon.setHorizontalAlignment(SwingConstants.CENTER);
		if (itemManager != null) { itemManager.getImage(f.getGeId()).addTo(icon); }

		// The name gets the whole first line and wraps instead of truncating -
		// the fixed body width makes the HTML label report a real wrapped
		// preferred height, which plain labels in a BorderLayout won't.
		final JLabel name = new JLabel("<html><body style='width:126px'><b>" + escHtml(f.getName()) + "</b></body></html>");
		name.setForeground(Color.WHITE);
		final JPanel line1 = row();
		line1.add(name, BorderLayout.CENTER);

		// Buy-to-sell with a painted chevron: the RuneScape font has no arrow
		// glyph, so typing one renders a garbage box.
		final JPanel bs = new JPanel();
		bs.setLayout(new BoxLayout(bs, BoxLayout.X_AXIS));
		bs.setOpaque(false);
		bs.add(mono(Fmt.compact(f.getBuy()), Palette.LIGHT));
		bs.add(Box.createRigidArea(new Dimension(5, 0)));
		bs.add(new Chevron(Palette.SUBTLE));
		bs.add(Box.createRigidArea(new Dimension(5, 0)));
		bs.add(mono(Fmt.compact(f.getSell()), Palette.LIGHT));
		final JLabel profit = mono("+" + Fmt.compact(f.getProfit()), f.getProfit() >= 0 ? Palette.GREEN : Palette.RED);
		profit.setHorizontalAlignment(SwingConstants.RIGHT);
		final JPanel line2 = row();
		line2.add(bs, BorderLayout.CENTER);
		line2.add(profit, BorderLayout.EAST);

		final JLabel ev = mono(Fmt.compact(f.getEvPerHr()) + "/hr", Palette.GOLD);
		ev.setHorizontalAlignment(SwingConstants.RIGHT);
		final JPanel line3 = row();
		line3.add(ev, BorderLayout.EAST);

		if (f.riskLabel() != null)
		{
			// Risk-tier row: volume-confirmed margin that missed one quality bar.
			// The amber mark carries WHY so the row explains itself on hover.
			final JLabel dot = new JLabel("! ");
			dot.setForeground(Palette.AMBER);
			dot.setFont(I18n.font(dot.getFont().deriveFont(Font.BOLD)));
			dot.setToolTipText(I18n.f("Higher risk: %s. Margin is volume-confirmed but this missed one board quality bar.", I18n.t(f.riskLabel())));
			line1.add(dot, BorderLayout.WEST);
			final JLabel why = new JLabel(I18n.t(f.riskLabel()));
			why.setForeground(Palette.AMBER);
			why.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
			line3.add(why, BorderLayout.WEST);
		}
		else if (f.isConfirmed())
		{
			final Mark ok = new Mark(Mark.CHECK, Palette.GREEN, 13, 16);
			ok.setToolTipText(I18n.t("Margin confirmed across the 5m + 1h books"));
			line1.add(ok, BorderLayout.WEST);
		}

		final JPanel center = new JPanel(new BorderLayout());
		center.setOpaque(false);
		center.add(line1, BorderLayout.NORTH);
		final JPanel lower = new JPanel(new BorderLayout());
		lower.setOpaque(false);
		lower.add(line2, BorderLayout.NORTH);
		lower.add(line3, BorderLayout.SOUTH);
		center.add(lower, BorderLayout.SOUTH);

		final Mark trk = new Mark(tracked ? Mark.CHECK : Mark.PLUS, tracked ? Palette.GREEN : Palette.SUBTLE, 18, 34);
		trk.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		trk.setToolTipText(tracked ? "Tracking, click to stop" : "Track this position");
		final boolean[] fired = { false };
		trk.addMouseListener(new MouseAdapter()
		{
			public void mousePressed(MouseEvent e)
			{
				if (fired[0]) { return; }   // guard against double-fire before the next poll
				fired[0] = true;
				trk.set(tracked ? Mark.PLUS : Mark.CHECK, tracked ? Palette.SUBTLE : Palette.GREEN);
				if (tracked) { listener.onUntrack(f.getGeId()); } else { listener.onTrack(f); }
			}
		});
		rowP.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		rowP.addMouseListener(new MouseAdapter()
		{
			public void mouseEntered(MouseEvent e) { rowP.setBackground(CARD_HOVER); }
			public void mouseExited(MouseEvent e) { rowP.setBackground(CARD); }

			public void mousePressed(MouseEvent e)
			{
				// The row toggles its evidence chart; the track mark on the
				// right has its own listener and consumes its own clicks.
				expandedChartId = expandedChartId == f.getGeId() ? 0 : f.getGeId();
				render();
			}
		});

		rowP.add(icon, BorderLayout.WEST);
		rowP.add(center, BorderLayout.CENTER);
		rowP.add(trk, BorderLayout.EAST);
		// Height follows the (possibly wrapped) name; without this cap the
		// BoxLayout parent stretches rows to fill leftover space.
		rowP.setMaximumSize(new Dimension(Integer.MAX_VALUE, rowP.getPreferredSize().height));
		return rowP;
	}

	private static String escHtml(String s)
	{
		return s == null ? "" : s.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	// ── tracking card ──
	// Package-visible for the headless preview harness.
	JPanel trackingCard(TrackedItem t)
	{
		final JPanel card = new JPanel();
		card.setLayout(new BoxLayout(card, BoxLayout.Y_AXIS));
		card.setBackground(CARD);
		card.setBorder(BorderFactory.createEmptyBorder(8, 9, 8, 9));
		card.setAlignmentX(Component.LEFT_ALIGNMENT);
		card.setMaximumSize(new Dimension(Integer.MAX_VALUE, 140));

		final JPanel head = row();
		head.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		final JLabel icon = new JLabel();
		icon.setPreferredSize(new Dimension(24, 20));
		if (itemManager != null) { itemManager.getImage(t.getGeId()).addTo(icon); }
		final JLabel name = new JLabel(t.getName());
		name.setFont(I18n.font(name.getFont().deriveFont(Font.BOLD)));
		name.setForeground(Color.WHITE);
		final Mark rm = new Mark(Mark.CROSS, Palette.SUBTLE, 18, 20);
		rm.setToolTipText(I18n.t("Stop tracking"));
		rm.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		rm.addMouseListener(new MouseAdapter()
		{
			public void mousePressed(MouseEvent e) { listener.onUntrack(t.getGeId()); }
			public void mouseEntered(MouseEvent e) { rm.set(Mark.CROSS, Palette.RED); }
			public void mouseExited(MouseEvent e) { rm.set(Mark.CROSS, Palette.SUBTLE); }
		});
		final JPanel nameWrap = new JPanel(new BorderLayout(6, 0));
		nameWrap.setOpaque(false);
		nameWrap.add(icon, BorderLayout.WEST);
		nameWrap.add(name, BorderLayout.CENTER);
		head.add(nameWrap, BorderLayout.CENTER);
		head.add(rm, BorderLayout.EAST);
		card.add(head);

		final boolean held = t.isHeld();
		card.add(kv(held ? I18n.f("Held %s · avg", Fmt.full(t.getHeldQty())) : I18n.t("Watching at"), Fmt.full(t.getEntryBuy())));
		card.add(kv("Sell now", t.getSellNow() != null ? Fmt.full(t.getSellNow()) : "-"));
		card.add(Box.createVerticalStrut(5));
		card.add(hairline());
		card.add(Box.createVerticalStrut(2));

		final boolean nodata = "nodata".equals(t.getStatus());
		final boolean thin = "thin".equals(t.getStatus());
		final Color pnlCol = t.getPnl() > 0 ? Palette.GREEN : (t.getPnl() < 0 ? Palette.RED : Palette.SUBTLE);
		// Held stacks show the whole position, not just the per-item number.
		final String pnlText;
		if (held && t.getPnlTotal() != null && t.getHeldQty() > 1)
		{
			pnlText = (t.getPnl() > 0 ? "+" : "") + Fmt.compact(t.getPnl()) + "/ea · "
				+ (t.getPnlTotal() > 0 ? "+" : "") + Fmt.compact(t.getPnlTotal()) + " total if sold now";
		}
		else
		{
			pnlText = (t.getPnl() > 0 ? "+" : "") + Fmt.compact(t.getPnl())
				+ " · " + pctSigned(t.getRoi()) + " if sold now";
		}
		final JLabel pnl = new JLabel(pnlText);
		pnl.setForeground(pnlCol);
		pnl.setFont(I18n.font(pnl.getFont().deriveFont(Font.BOLD, 13f)));
		pnl.setAlignmentX(Component.LEFT_ALIGNMENT);
		pnl.setBorder(BorderFactory.createEmptyBorder(3, 0, 2, 0));
		pnl.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		card.add(pnl);

		// Verdict cluster: the pill and its plain-language reading sit together.
		// A watch row says so instead of pretending you hold the item.
		final JPanel st = row();
		st.setMaximumSize(new Dimension(Integer.MAX_VALUE, 20));
		final JPanel verdict = new JPanel();
		verdict.setLayout(new BoxLayout(verdict, BoxLayout.X_AXIS));
		verdict.setOpaque(false);
		verdict.add(pill(!held ? "watching" : (nodata ? "no data" : (thin ? "thin" : "healthy")),
			!held ? Palette.GOLD : (nodata ? Palette.SUBTLE : (thin ? Palette.RED : Palette.GREEN))));
		verdict.add(Box.createRigidArea(new Dimension(7, 0)));
		final JLabel hint = new JLabel(!held
			? (nodata ? "not held · not trading" : "not held · vs your watch price")
			: (nodata ? "not trading right now" : (thin ? "margin closing" : "good to hold")));
		hint.setForeground(Palette.LIGHT);
		hint.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		verdict.add(hint);
		st.add(verdict, BorderLayout.WEST);
		card.add(st);

		final JLabel floor = new JLabel(held
			? "Floor " + Fmt.full(t.getFloor()) + " · don't sell below"
			: "Would break even at " + Fmt.full(t.getFloor()));
		floor.setForeground(Palette.SUBTLE);
		floor.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		floor.setAlignmentX(Component.LEFT_ALIGNMENT);
		floor.setBorder(BorderFactory.createEmptyBorder(3, 0, 0, 0));
		floor.setMaximumSize(new Dimension(Integer.MAX_VALUE, 16));
		card.add(floor);
		return card;
	}

	// ── empty / auth state with an action ──
	private JPanel emptyState()
	{
		final JPanel p = new JPanel();
		p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
		p.setBorder(BorderFactory.createEmptyBorder(14, 4, 4, 4));
		String title, body;
		switch (authState)
		{
			case INVALID_KEY: title = "Key not recognised"; body = "Regenerate it at flipping.pricecheck.gg, then paste it in Settings."; break;
			case NO_SUBSCRIPTION: title = "Subscription inactive"; body = "Renew at flipping.pricecheck.gg to see live flips."; break;
			case PLAN_REQUIRED: title = "Trader Pro feature"; body = "The RuneLite plugin comes with Trader Pro. Upgrade at flipping.pricecheck.gg."; break;
			case ERROR: title = "Can't reach PriceCheck"; body = "Retrying…"; break;
			default: title = "Add your plugin key"; body = "Open Settings and paste your key to see live flips."; break;
		}
		final JLabel t = new JLabel(title);
		t.setForeground(Palette.GOLD);
		t.setFont(I18n.font(t.getFont().deriveFont(Font.BOLD, 13f)));
		t.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JLabel b = new JLabel("<html><body style='width:180px'>" + body + "</body></html>");
		b.setForeground(Palette.SUBTLE);
		b.setBorder(BorderFactory.createEmptyBorder(6, 0, 10, 0));
		b.setAlignmentX(Component.LEFT_ALIGNMENT);
		final JButton open = new JButton(I18n.t("Open Settings"));
		open.setFocusPainted(false);
		open.setAlignmentX(Component.LEFT_ALIGNMENT);
		open.addActionListener(e -> { if (settingsTab != null) { settingsTab.select(); } });
		p.add(t); p.add(b); p.add(open);
		return p;
	}

	// ── small building blocks ──
	private JPanel row()
	{
		final JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		return p;
	}

	private JComponent sectionHeader(String text)
	{
		final JLabel h = new JLabel(I18n.t(text).toUpperCase(Locale.ROOT));
		h.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		h.setForeground(Palette.GOLD);
		h.setBorder(BorderFactory.createEmptyBorder(2, 1, 6, 8));
		// A hairline rule fills the rest of the header line; raised a little
		// so it tracks the text's optical middle, not the padded label's.
		final JPanel rule = new JPanel();
		rule.setBackground(HAIRLINE);
		rule.setPreferredSize(new Dimension(1, 1));
		final JPanel ruleWrap = new JPanel(new GridBagLayout());
		ruleWrap.setOpaque(false);
		final GridBagConstraints rc = new GridBagConstraints();
		rc.weightx = 1;
		rc.fill = GridBagConstraints.HORIZONTAL;
		rc.insets = new Insets(0, 0, 4, 0);
		ruleWrap.add(rule, rc);
		final JPanel p = new JPanel(new BorderLayout());
		p.setOpaque(false);
		p.add(h, BorderLayout.WEST);
		p.add(ruleWrap, BorderLayout.CENTER);
		p.setAlignmentX(Component.LEFT_ALIGNMENT);
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
		return p;
	}

	private JPanel kv(String k, String v)
	{
		k = I18n.t(k);
		final JPanel p = row();
		p.setMaximumSize(new Dimension(Integer.MAX_VALUE, 18));
		final JLabel kl = new JLabel(k);
		kl.setForeground(Palette.SUBTLE);
		kl.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		final JLabel vl = mono(v, Color.WHITE);
		vl.setHorizontalAlignment(SwingConstants.RIGHT);
		p.add(kl, BorderLayout.WEST);
		p.add(vl, BorderLayout.EAST);
		return p;
	}

	private static JLabel pill(String text, Color col)
	{
		text = I18n.t(text);
		final JLabel p = new JLabel(" " + text + " ");
		p.setOpaque(true);
		p.setBackground(new Color(col.getRed(), col.getGreen(), col.getBlue(), 40));
		p.setForeground(col);
		p.setFont(I18n.font(p.getFont().deriveFont(10f)));
		p.setBorder(BorderFactory.createEmptyBorder(1, 3, 1, 3));
		return p;
	}

	private static JLabel mono(String text, Color col)
	{
		final JLabel l = new JLabel(text);
		l.setForeground(col);
		l.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		return l;
	}

	private JLabel note(String text, Color col)
	{
		text = I18n.t(text);
		// HTML with a fixed body width wraps; a plain label clips mid-sentence
		// at the panel's 226px.
		final JLabel l = new JLabel("<html><body style='width:176px'>" + escHtml(text) + "</body></html>");
		l.setFont(I18n.font(FontManager.getRunescapeSmallFont()));
		l.setForeground(col);
		l.setBorder(BorderFactory.createEmptyBorder(6, 2, 6, 2));
		l.setAlignmentX(Component.LEFT_ALIGNMENT);
		return l;
	}

	private Component gap(int h)
	{
		return Box.createRigidArea(new Dimension(0, h));
	}

	/** Scroll content that matches the viewport WIDTH (so rows never overflow to the
	 * right and clip the EV/profit column) while growing taller than it for vertical
	 * scroll. Holds its child at NORTH so rows keep their preferred height. */
	private static final class ScrollList extends JPanel implements Scrollable
	{
		ScrollList() { super(new BorderLayout()); }
		public Dimension getPreferredScrollableViewportSize() { return getPreferredSize(); }
		public int getScrollableUnitIncrement(Rectangle r, int orient, int dir) { return 16; }
		public int getScrollableBlockIncrement(Rectangle r, int orient, int dir) { return 48; }
		public boolean getScrollableTracksViewportWidth() { return true; }
		public boolean getScrollableTracksViewportHeight() { return false; }
	}
}

package gg.pricecheck.runelite;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * The desk's SESSION · FLOW strip, docked to the bottom edge of the Grand Exchange
 * window: this session's realised profit, gp/hr, flips, win rate, tax paid and
 * average ROI - all from your own flip log (no server call, works for free keys).
 * Opt-in via config.terminalDesk(); look from TerminalKit.
 */
class TerminalSessionOverlay extends Overlay
{
	private static final int H = 56;
	private static final int GAP = 4;

	private final Client client;
	private final PriceCheckPlugin plugin;

	TerminalSessionOverlay(Client client, PriceCheckPlugin plugin)
	{
		this.client = client;
		this.plugin = plugin;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D g)
	{
		plugin.noteSessionStrip(-1, -1, -1);
		if (!plugin.terminalDesk() || !plugin.isGrandExchangeOpen())
		{
			return null;
		}
		final Rectangle ge = plugin.geGridBounds();
		final FlipLogEngine.Summary s = plugin.flipSummary();
		if (ge == null || s == null)
		{
			return null;
		}
		final int x = ge.x;
		final int y = ge.y + ge.height + GAP;
		// Stand down rather than cover the chat input.
		int bottomLimit = client.getCanvasHeight() - 4;
		final Rectangle cb = plugin.chatboxBounds();
		if (cb != null && cb.height > 0)
		{
			bottomLimit = Math.min(bottomLimit, cb.y - 4);
		}
		if (y + H > bottomLimit)
		{
			return null;
		}

		final Object aa = g.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
		final Object taa = g.getRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING);
		final int painted;
		g.translate(x, y);
		try
		{
			painted = paintStrip(g, ge.width, s);
		}
		finally
		{
			g.translate(-x, -y);
			if (aa != null) { g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, aa); }
			if (taa != null) { g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, taa); }
		}
		// Publish the footprint so the ticker snaps directly beneath the strip.
		plugin.noteSessionStrip(x, y + H, ge.width);
		plugin.noteDeskRect("session", x, y, ge.width, painted);
		return new Dimension(ge.width, painted);
	}

	/** Pure drawing (0,0-origin) so the preview harness can render it headless. Returns the painted height. */
	static int paintStrip(Graphics2D g, int w, FlipLogEngine.Summary s)
	{
		TerminalKit.hints(g);
		TerminalKit.panel(g, 0, 0, w, H, I18n.t("SESSION  ·  FLOW"));

		final String today = (s.todayProfit >= 0 ? "+" : "-") + TerminalKit.gp(Math.abs(s.todayProfit));
		final String gphr = s.sessionGpHr == Long.MIN_VALUE ? "-"
			: (s.sessionGpHr >= 0 ? "+" : "-") + TerminalKit.gp(Math.abs(s.sessionGpHr));
		final String win = s.winRatePct < 0 ? "-" : s.winRatePct + "%";
		final String roi = Double.isNaN(s.avgRoiPct) ? "-" : String.format("%+.1f%%", s.avgRoiPct);

		// Six evenly-spaced KPI cells across the strip width.
		final String[] labels = {"REALIZED TODAY", "GP / HR", "FLIPS", "WIN", "TAX PAID", "AVG ROI"};
		final String[] values = {today, gphr, Integer.toString(s.allFlips), win, TerminalKit.gp(s.allTax), roi};
		final Color[] colors = {
			s.todayProfit >= 0 ? TerminalKit.GREEN : TerminalKit.RED,
			s.sessionGpHr == Long.MIN_VALUE ? TerminalKit.DIM : s.sessionGpHr >= 0 ? TerminalKit.GREEN : TerminalKit.RED,
			TerminalKit.AMBER,
			s.winRatePct < 0 ? TerminalKit.DIM : s.winRatePct >= 50 ? TerminalKit.GREEN : TerminalKit.AMBER,
			TerminalKit.LABEL,
			Double.isNaN(s.avgRoiPct) ? TerminalKit.DIM : s.avgRoiPct >= 0 ? TerminalKit.GREEN : TerminalKit.RED,
		};
		final int n = labels.length;
		final int colW = (w - 16) / n;
		for (int i = 0; i < n; i++)
		{
			final int cx = 8 + i * colW;
			g.setFont(TerminalKit.mono(9)); g.setColor(TerminalKit.LABEL);
			TerminalKit.str(g, labels[i], cx, 36);
			g.setFont(TerminalKit.monoB(15)); g.setColor(colors[i]);
			g.drawString(values[i], cx, 50);
		}
		return H;
	}
}

package gg.pricecheck.runelite;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FontMetrics;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.geom.Path2D;
import javax.swing.JComponent;
import net.runelite.client.ui.FontManager;

/**
 * The per-item evidence chart: 24h of 5-minute windows drawn through the
 * shared ChartKit bucketing (volume-weighted corridor, gold where the
 * after-tax spread paid, wick envelope, price grid, volume strip), with the
 * engine's current quotes as labeled price lines, your own logged fills as
 * exact-price markers, manipulation windows ticked, and the forecast band
 * noted.
 */
class ItemChart extends JComponent
{
	/** One item's series + the engine's live read of it, as plain arrays. */
	static final class Series
	{
		long[] ts;          // window start, epoch seconds, ascending
		long[] high;        // avg insta-buy print (what sellers received)
		long[] low;         // avg insta-sell print (what buyers paid)
		int[] hvol;
		int[] lvol;
		boolean[] manip;    // volume-surge manipulation flag per window
		long quoteBuy;      // engine bid (0 = none)
		long quoteSell;     // engine ask (0 = none)
		int fillPct = -1;   // measured odds both sides cross in 4h, -1 = unknown
		int fcFrom = -1;    // forecast band UTC hours, -1 = none
		int fcTo = -1;
		String fcNote;      // e.g. "held 14/18 days"
		// Your own logged fills on this item, from the flip log: exact prices,
		// not approximations. Painted as buy/sell triangles on the series.
		long[] markTs;
		long[] markPrice;
		boolean[] markBuy;
	}

	private static final Color QUOTE = new Color(0xe6, 0xc6, 0x67, 190);
	private static final int PAD_L = 4;
	private static final int PAD_R = 54;   // price labels live here
	private static final int AXIS_H = 13;
	private static final int FILL_H = 20;  // stacked volume bars below the plot

	private Series s;

	ItemChart(Series s, int width, int height)
	{
		this.s = s;
		setPreferredSize(new Dimension(width, height));
		setMinimumSize(getPreferredSize());
		setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
	}

	void setSeries(Series s)
	{
		this.s = s;
		repaint();
	}

	@Override
	protected void paintComponent(Graphics g)
	{
		final Graphics2D g2 = (Graphics2D) g;
		g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_OFF);
		final Series ser = s;
		final int w = getWidth();
		final int h = getHeight();
		g2.setFont(FontManager.getRunescapeSmallFont());
		final FontMetrics fm = g2.getFontMetrics();

		final int chartW = w - PAD_L - PAD_R;
		final int chartH = h - AXIS_H - FILL_H - 4;
		final int chartY = 2;

		final ChartKit.Display d = ChartKit.build(ser, chartW,
			ser != null ? ser.quoteBuy : 0, ser != null ? ser.quoteSell : 0);
		if (d == null)
		{
			g2.setColor(Palette.SUBTLE);
			TerminalKit.str(g2, "No trade history yet", PAD_L + 4, h / 2);
			return;
		}

		// Hour grid + labels every 6h, painted first so everything sits on it.
		for (long t = ((d.tMin / 21600) + 1) * 21600; t < d.tMax; t += 21600)
		{
			final int x = Math.round(ChartKit.x(d, t, PAD_L, chartW));
			g2.setColor(ChartKit.GRID);
			g2.drawLine(x, chartY, x, chartY + chartH + FILL_H + 2);
			g2.setColor(Palette.SUBTLE);
			final String lbl = String.format("%02d:00", (t / 3600) % 24);
			final int lx = Math.max(PAD_L, Math.min(x - fm.stringWidth(lbl) / 2, w - PAD_R - fm.stringWidth(lbl)));
			g2.drawString(lbl, lx, h - 2);
		}

		ChartKit.paintPriceGrid(g2, d, fm, PAD_L, chartY, chartW, chartH, Palette.LIGHT);
		ChartKit.paintCorridor(g2, d, PAD_L, chartY, chartW, chartH);
		ChartKit.paintLevelGuides(g2, d, PAD_L, chartY, chartW, chartH);
		ChartKit.paintVolumeBars(g2, d, PAD_L, chartY + chartH + 2, chartW, FILL_H - 2);

		// Manipulation flags: a red tick at the top of the flagged window.
		if (ser.manip != null && ser.ts != null)
		{
			g2.setColor(Palette.RED);
			for (int i = 0; i < ser.ts.length; i++)
			{
				if (ser.manip[i])
				{
					final int x = Math.round(ChartKit.x(d, ser.ts[i], PAD_L, chartW));
					g2.fillRect(x - 1, chartY, 3, 3);
				}
			}
		}

		// Your logged fills: exact buy/sell prices from the flip log, painted
		// where they happened. Triangle up = your buy, down = your sell.
		if (ser.markTs != null)
		{
			for (int i = 0; i < ser.markTs.length; i++)
			{
				if (ser.markTs[i] < d.tMin || ser.markTs[i] > d.tMax || ser.markPrice[i] <= 0)
				{
					continue;
				}
				final float mx = ChartKit.x(d, ser.markTs[i], PAD_L, chartW);
				final float my = ChartKit.y(d, ser.markPrice[i], chartY, chartH);
				final Path2D tri = new Path2D.Float();
				if (ser.markBuy[i])
				{
					tri.moveTo(mx - 4, my + 3);
					tri.lineTo(mx + 4, my + 3);
					tri.lineTo(mx, my - 4);
				}
				else
				{
					tri.moveTo(mx - 4, my - 3);
					tri.lineTo(mx + 4, my - 3);
					tri.lineTo(mx, my + 4);
				}
				tri.closePath();
				g2.setColor(new Color(0, 0, 0, 170));
				g2.translate(1, 1);
				g2.fill(tri);
				g2.translate(-1, -1);
				g2.setColor(ser.markBuy[i] ? Palette.GREEN : Palette.RED);
				g2.fill(tri);
			}
		}

		// Engine quotes: dotted price lines with right-edge labels. These are
		// the exact numbers the board quotes right now.
		final java.awt.Stroke dotted = new BasicStroke(1f, BasicStroke.CAP_BUTT, BasicStroke.JOIN_MITER, 10f, new float[]{2f, 3f}, 0f);
		if (ser.quoteSell > 0)
		{
			quoteLine(g2, d, dotted, ser.quoteSell, "ask " + Fmt.compact(ser.quoteSell), chartY, chartH, w, fm);
		}
		if (ser.quoteBuy > 0)
		{
			quoteLine(g2, d, dotted, ser.quoteBuy, "bid " + Fmt.compact(ser.quoteBuy), chartY, chartH, w, fm);
		}

		// Forecast band note when the band opens within the coming hours.
		if (ser.fcFrom >= 0 && ser.fcTo > ser.fcFrom)
		{
			final long dayStart = (d.tMax / 86400) * 86400;
			long bandStart = dayStart + ser.fcFrom * 3600L;
			if (bandStart < d.tMax)
			{
				bandStart += 86400;
			}
			if (bandStart - d.tMax < 21600)
			{
				g2.setColor(QUOTE);
				g2.fillRect(w - PAD_R + 1, chartY, 2, chartH);
				g2.setColor(Palette.GOLD);
				final String note = String.format("%02d:00", ser.fcFrom) + (ser.fcNote != null ? " " + ser.fcNote : "");
				g2.drawString(note, w - PAD_R - fm.stringWidth(note) - 4, chartY + 10);
			}
		}
	}

	private void quoteLine(Graphics2D g2, ChartKit.Display d, java.awt.Stroke dotted, long price, String label, int y0, int ch, int w, FontMetrics fm)
	{
		final int yy = Math.round(ChartKit.y(d, price, y0, ch));
		g2.setStroke(dotted);
		g2.setColor(QUOTE);
		g2.drawLine(PAD_L, yy, w - PAD_R, yy);
		g2.setStroke(new BasicStroke(1f));
		g2.setColor(Palette.GOLD);
		g2.drawString(label, w - PAD_R + 3, yy + 4);
	}
}

