	// ── Desk tiers: one control, sized to the window ──────────────────
	// deskMode AUTO measures the free space around the open GE every frame and
	// picks the biggest layout that fits; the fixed modes cap the pick. Panels
	// consult these instead of individual toggles, so nothing can overlap: a
	// tier the window cannot hold simply never gets chosen.
	enum DeskTier { OFF, MINIMAL, COMPACT, FULL }

	DeskTier deskTier()
	{
		final PriceCheckConfig.DeskMode m = config.deskMode();
		if (m == PriceCheckConfig.DeskMode.OFF)
		{
			return DeskTier.OFF;
		}
		final DeskTier fit = measuredFit();
		switch (m)
		{
			case MINIMAL: return fit.ordinal() < DeskTier.MINIMAL.ordinal() ? fit : DeskTier.MINIMAL;
			case COMPACT: return fit.ordinal() < DeskTier.COMPACT.ordinal() ? fit : DeskTier.COMPACT;
			case FULL:
			default:
				return fit;   // AUTO and FULL both take the biggest fitting layout
		}
	}

	/** The biggest tier the current window supports. Client thread (reads
	 *  widget bounds); overlays only call this from render. */
	private DeskTier measuredFit()
	{
		final java.awt.Rectangle ge = geGridBounds();
		if (ge == null)
		{
			// GE closed: only the sidebar + chatbox surfaces matter, and the
			// card overlay gates on the GE being open anyway.
			return DeskTier.FULL;
		}
		final int canvasW = client.getCanvasWidth();
		final int canvasH = client.getCanvasHeight();
		final int right = canvasW - (ge.x + ge.width);
		final int left = ge.x;
		// The Large detail level scales every panel up; the fit thresholds
		// must scale with it or a borderline window overflows at Overnight.
		final double sc = overlayScale();
		final int CARD = (int) Math.ceil(GeItemInfoPainter.TERM_W * sc) + 16;   // terminal card column
		final int RADAR = (int) Math.ceil(TerminalRadarOverlay.W * sc) + 16;    // left column
		if (right >= CARD && left >= RADAR && canvasH >= 620)
		{
			return DeskTier.FULL;
		}
		if (right >= CARD)
		{
			return DeskTier.COMPACT;
		}
		// The card reflows down to TERM_MIN and can anchor on either side of
		// the GE, so the card-only tier accepts whichever side has the room.
		final int MINCARD = (int) Math.ceil(GeItemInfoPainter.TERM_MIN * sc) + 16;
		if (right >= MINCARD || left >= MINCARD)
		{
			return DeskTier.MINIMAL;
		}
		return DeskTier.OFF;
	}

	boolean deskOn()
	{
		return config.deskMode() != PriceCheckConfig.DeskMode.OFF;
	}

	boolean deskFull()
	{
		return deskTier() == DeskTier.FULL;
	}

	boolean deskBlotter()
	{
		final DeskTier t = deskTier();
		return t == DeskTier.FULL || t == DeskTier.COMPACT;
	}

	boolean deskCard()
	{
		return deskTier().ordinal() >= DeskTier.MINIMAL.ordinal();
	}

	// ── Desk self-diagnosis ───────────────────────────────────────────
	// Panels report their painted rectangle every frame; the status bar asks
	// for a verdict. Two failure smells are detected: desk panels overlapping
	// EACH OTHER (a layout bug or a forced tier in a too-small window) and a
	// foreign game interface (collection log, bank, quest panels) sitting on
	// top of the desk. Either way the user gets one plain line with the fix
	// instead of a silently broken composition.
	private static final long DESK_RECT_TTL_MS = 2000;
	private final java.util.concurrent.ConcurrentHashMap<String, long[]> deskRects = new java.util.concurrent.ConcurrentHashMap<>();

	void noteDeskRect(String key, int x, int y, int w, int h)
	{
		deskRects.put(key, new long[]{ x, y, w, h, System.currentTimeMillis() });
	}

	private java.util.List<java.awt.Rectangle> freshDeskRects()
	{
		final long now = System.currentTimeMillis();
		final java.util.List<java.awt.Rectangle> out = new java.util.ArrayList<>();
		for (final java.util.Map.Entry<String, long[]> e : deskRects.entrySet())
		{
			final long[] v = e.getValue();
			if (now - v[4] > DESK_RECT_TTL_MS)
			{
				deskRects.remove(e.getKey());
				continue;
			}
			out.add(new java.awt.Rectangle((int) v[0], (int) v[1], (int) v[2], (int) v[3]));
		}
		return out;
	}

	/** Client thread. Null when the composition is clean. */
	String deskCompositionNotice()
	{
		final java.util.List<java.awt.Rectangle> rects = freshDeskRects();
		if (rects.isEmpty())
		{
			return null;
		}
		// Our own panels colliding: anything beyond a sliver is wrong.
		for (int i = 0; i < rects.size(); i++)
		{
			for (int j = i + 1; j < rects.size(); j++)
			{
				final java.awt.Rectangle o = rects.get(i).intersection(rects.get(j));
				if (o.width > 12 && o.height > 12)
				{
					return "desk panels are colliding - widen the client or set desk to Auto";
				}
			}
		}
		// A foreign game interface over the desk: the GE (465) and the chatbox
		// (162) are desk neighbours, everything else big on top is a squatter.
		final net.runelite.api.widgets.Widget[] roots = client.getWidgetRoots();
		if (roots != null)
		{
			for (final net.runelite.api.widgets.Widget root : roots)
			{
				if (root == null || root.isHidden())
				{
					continue;
				}
				final int group = net.runelite.api.widgets.WidgetUtil.componentToInterface(root.getId());
				if (group == 465 || group == 162)
				{
					continue;
				}
				final java.awt.Rectangle rb = root.getBounds();
				if (rb == null || rb.width < 120 || rb.height < 120)
				{
					continue;
				}
				// Layout containers span (almost) the whole canvas and would
				// "cover" the desk forever - only solid sub-interfaces count.
				final long canvasArea = (long) client.getCanvasWidth() * client.getCanvasHeight();
				if ((long) rb.width * rb.height > canvasArea * 0.8)
				{
					continue;
				}
				for (final java.awt.Rectangle d : rects)
				{
					final java.awt.Rectangle o = rb.intersection(d);
					if (o.width > 40 && o.height > 40)
					{
						return "another interface is covering the desk - close it or resize the client";
					}
				}
			}
		}
		return null;
	}

	/** The one line the status bar shows: an unhonored fixed tier first, a
	 *  broken composition second, Auto's own narration third, nothing when
	 *  the desk is clean. */
	String deskNotice()
	{
		final String fit = deskFitNotice();
		if (fit != null)
		{
			return fit;
		}
		final String comp = deskCompositionNotice();
		if (comp != null)
		{
			return comp;
		}
		return autoFitNotice();
	}

	// Auto used to refit silently, which reads as "auto does nothing" - now a
	// tier change announces itself for a few seconds with the deficit to the
	// next tier up, and the no-room state explains itself for as long as it
	// lasts (otherwise the desk is just absent with no clue why).
	private DeskTier lastAutoFit;
	private long autoFitChangedAt;

	private String autoFitNotice()
	{
		if (config.deskMode() != PriceCheckConfig.DeskMode.AUTO)
		{
			return null;
		}
		final java.awt.Rectangle ge = geGridBounds();
		if (ge == null)
		{
			return null;
		}
		final DeskTier fit = measuredFit();
		final long now = System.currentTimeMillis();
		if (fit != lastAutoFit)
		{
			// Stay quiet on the very first measure (login/GE open): only a
			// CHANGE the user caused deserves a line.
			autoFitChangedAt = lastAutoFit == null ? 0 : now;
			lastAutoFit = fit;
		}
		final int canvasW = client.getCanvasWidth();
		final int canvasH = client.getCanvasHeight();
		final int right = canvasW - (ge.x + ge.width);
		final int left = ge.x;
		final double sc = overlayScale();
		final int CARD = (int) Math.ceil(GeItemInfoPainter.TERM_W * sc) + 16;
		final int RADAR = (int) Math.ceil(TerminalRadarOverlay.W * sc) + 16;
		final int MINCARD = (int) Math.ceil(GeItemInfoPainter.TERM_MIN * sc) + 16;
		if (fit == DeskTier.OFF)
		{
			final int deficit = MINCARD - Math.max(left, right);
			return "auto: no room beside the GE for the desk (+" + deficit
				+ "px) - widen the client or close the sidebar";
		}
		if (autoFitChangedAt == 0 || now - autoFitChangedAt > 6000)
		{
			return null;
		}
		switch (fit)
		{
			case FULL:
				return "auto: full desk";
			case COMPACT:
			{
				final StringBuilder need = new StringBuilder();
				if (left < RADAR) need.append('+').append(RADAR - left).append("px left ");
				if (canvasH < 620) need.append('+').append(620 - canvasH).append("px height ");
				return "auto: compact desk (full needs " + need.toString().trim() + ")";
			}
			default:
				return "auto: card only (blotter needs +" + (CARD - right) + "px right)";
		}
	}

	/** One plain line when a FIXED desk mode cannot fit the current window,
	 *  with the real deficit and the fix. AUTO never complains: silently
	 *  fitting is what it is for. Null when everything the user asked for is
	 *  on screen. */
	String deskFitNotice()
	{
		final PriceCheckConfig.DeskMode m = config.deskMode();
		if (m == PriceCheckConfig.DeskMode.AUTO || m == PriceCheckConfig.DeskMode.OFF)
		{
			return null;
		}
		final DeskTier fit = measuredFit();
		final DeskTier want = m == PriceCheckConfig.DeskMode.FULL ? DeskTier.FULL
			: m == PriceCheckConfig.DeskMode.COMPACT ? DeskTier.COMPACT : DeskTier.MINIMAL;
		if (fit.ordinal() >= want.ordinal())
		{
			return null;
		}
		final java.awt.Rectangle ge = geGridBounds();
		if (ge == null)
		{
			return null;
		}
		final int canvasW = client.getCanvasWidth();
		final int canvasH = client.getCanvasHeight();
		final int right = canvasW - (ge.x + ge.width);
		final int left = ge.x;
		final double sc = overlayScale();
		final int CARD = (int) Math.ceil(GeItemInfoPainter.TERM_W * sc) + 16;
		final int RADAR = (int) Math.ceil(TerminalRadarOverlay.W * sc) + 16;
		final StringBuilder need = new StringBuilder();
		if (want == DeskTier.FULL)
		{
			if (right < CARD) need.append('+').append(CARD - right).append("px right ");
			if (left < RADAR) need.append('+').append(RADAR - left).append("px left ");
			if (canvasH < 620) need.append('+').append(620 - canvasH).append("px height ");
		}
		else
		{
			final int MINCARD = (int) Math.ceil(GeItemInfoPainter.TERM_MIN * sc) + 16;
			final int wantRight = want == DeskTier.COMPACT ? CARD : MINCARD;
			if (right < wantRight) need.append('+').append(wantRight - right).append("px right ");
		}
		if (need.length() == 0)
		{
			return null;
		}
		return want.name().toLowerCase() + " desk needs " + need.toString().trim()
			+ " - widen the client or close the sidebar (showing " + fit.name().toLowerCase() + ")";
	}

	/** True while the offer set-up panel (465:15 or 465:26) is on screen - the state
	 *  the terminal ORDER ticket wants; the blotter yields the right dock to it. */
	boolean setupScreenOpen()
	{
		for (final int child : new int[]{15, 26})
		{
			final net.runelite.api.widgets.Widget w = client.getWidget(465, child);
			if (w != null && !w.isHidden())
			{
				return true;
			}
		}
		return false;
	}

	/** True when the GE grid OVERVIEW is on screen: no offer slot selected and no
	 *  set-up panel open. The desk's left column (radar) shows only here, so when a
	 *  slot is open it yields the left dock to the single terminal card; the classic
	 *  mini-card grid also stands down while the desk is on. */
	boolean geOverviewOpen()
	{
		if (!isGrandExchangeOpen())
		{
			return false;
		}
		final int slotVal = client.getVarbitValue(4439);
		if (slotVal >= 1 && slotVal <= 8)
		{
			final GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
			if (offers != null && offers.length >= slotVal)
			{
				final GrandExchangeOffer o = offers[slotVal - 1];
				if (o != null && o.getState() != net.runelite.api.GrandExchangeOfferState.EMPTY && o.getItemId() > 0)
				{
					return false;
				}
			}
		}
		for (final int child : new int[]{15, 26})
		{
			final net.runelite.api.widgets.Widget w = client.getWidget(465, child);
			if (w != null && !w.isHidden())
			{
				return false;
			}
		}
		return true;
	}

	/** The ranked flip board for the desk panels (radar / movers / ticker); empty
	 *  until live market data has landed. Null entries (a JSON null in the array)
	 *  are stripped so the panels can iterate without per-row null guards. */
	List<FlipData> boardFlips()
	{
		final PriceCheckApiClient.FlipsResult r = lastGoodFlips;
		if (r == null || r.flips == null)
		{
			return Collections.emptyList();
		}
		final List<FlipData> out = new ArrayList<>(r.flips.size());
		for (final FlipData f : r.flips)
		{
			if (f != null)
			{
				out.add(f);
			}
		}
		return out;
	}

	/** Live dump movers for the fresh-dips panel; empty until market data lands.
	 *  Null entries are stripped (see boardFlips). */
	List<CatchData> boardCatches()
	{
		final PriceCheckApiClient.FlipsResult r = lastGoodFlips;
		if (r == null || r.catches == null)
		{
			return Collections.emptyList();
		}
		final List<CatchData> out = new ArrayList<>(r.catches.size());
		for (final CatchData c : r.catches)
		{
			if (c != null)
			{
				out.add(c);
			}
		}
		return out;
	}

	/** Buy-limit read for the terminal card: {boughtIn4h, total, resetEpochMs}.
	 *  total -1 when the item has no published limit or no live data. */
	long[] buyLimitInfo(int geId)
	{
		if (buyLimits != null)
		{
			// Make sure this account's window is loaded before the first read,
			// even if no offer has changed yet this session.
			buyLimits.setAccount(client.getAccountHash());
		}
		final FlipData fd = liveFor(geId);
		final long total = (fd != null && fd.getLimit() != null) ? fd.getLimit() : -1L;
		final long now = System.currentTimeMillis();
		final long bought = buyLimits != null ? buyLimits.boughtIn4h(geId, now) : 0L;
		final long reset = buyLimits != null ? buyLimits.resetAt(geId, now) : 0L;
		return new long[]{bought, total, reset};
	}

	/** How many recent trades the GE overlays show: Active 10, Advanced 20,
	 *  Overnight 30. Drives the item card's tape and on-chart prints. */
	/** Tape depth follows the window instead of a toggle: tall clients get
